/* 平成30年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h30.committeeSessions.push(...[{"id":"h30-20180226-8","meetingId":"h30-cm02","date":"2018年2月26日","dateIso":"2018-02-26","committee":"建設委員会","time":"午前１０時００分～午後 ４時００分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を123件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに、第３０号議案 品川区営住宅条例の一部を改正する条例","agenda":"はじめに、第３０号議案 品川区営住宅条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"そもそもこの減額制度を受けている人の割合はどのぐらいなのでしょうか。制度の周知方法はどうしていらっしゃるのでしょうか。申請がないと行わないということなのでしょうか、お伺いします。","respondent":"長尾住宅課長","answer":"そういったこともありまして、収入報告をいただいていない方というのは今までございません。減額を受けられている方の割合としましては、概ね７割から８割の方が一定程度の減額を受けている状況があります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。それとあと、申請がないとこれは受けられないものなのかということと、それと収入申告をすること等が困難な事情があると事業者が認める者とは、具体的にどなたがどのように判断をされるのでしょうか、伺いたいと思います。","respondent":"長尾住宅課長","answer":"そういった催告というか報告を促したり、あと報告をしていただく補助をしたとしても、なかなか収入の把握ができないような場合を、困難な事情であると捉えることになると考えております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"確認","question":"個々に認知症テストをするとか、そういうことではないということなのでしょうか。向こうから定例の６月の申告がない、その上で指定管理者よりいろいろ確認してもらう上でもなかなかしてもらえないという方を、全てそういう事情にあると認めるということでよろしいのかという確認をお願いします。","respondent":"長尾住宅課長","answer":"先ほどお伝えしたような困難な事情があるという方につきましては、病院でその診断書を書いていただいたり、そういった書面をもってその確認をさせていただいて、報告義務を免除していくという考え方になります。","voiceIndex":9,"id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"結局よくわからないのですけれども、先ほど、今まで認知症等によりということで未報告者はないですよとおっしゃったと思うのですね。ですが、これができたということは、今後何か大きな変わることがあるのかということと、今までご本人ができなかった場合に、管理をしているところでどのように調べて報告をしていたのでしょうか。それから、今までどのような状況だったのか、もう少し聞きたいのですけれども。","respondent":"長尾住宅課長","answer":"今まで収入の報告につきましては、指定管理者を通じて報告をいただいて、報告がいただけなかった場合は個別にお宅まで伺って、その収入の報告をしてくださいということを促しながら、必要な書類の準備の仕方とかがわからないという方もいらっしゃいますので。","voiceIndex":11,"id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"逆に言うと、今までの情報というのはかなり個人情報が入っていたと思うのです。なので、それも含めて今までやっていたということなので、それには何か許可とか規定とかあった上で、そういう権限があってやっていたことなのでしょうか。","respondent":"長尾住宅課長","answer":"指定管理者には入居者の管理の業務をやってもらっていますので、通常その入居の手続きの際も、その収入の状況の確認であるとかはやっておりますので、それと同じ内容でということになります。","voiceIndex":13,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"管理をする側はいいのですけれども、結局認知症の方がよくわからなくなってしまった、出す書類もわからないという方々に対して、その応対も含めて実際わからない方もいらっしゃると思うのです。そういう場合に、指定管理者の方々がどこまでできていたのでしょうかということと、指定管理者の方たちはそこまで調査することができる権限を持って今まで対応していたということなのでしょうか。","respondent":"長尾住宅課長","answer":"今までの指定管理者を通じた収入の報告につきまして、その中で、この方が認知症であるとか、そういったところは特になく、区としてもそういった情報を求めているわけではないので、そこについては今までは確認するようなところはなかったのですけれども。","voiceIndex":15,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"わかりました。それだけの権限を持った上での、要は調査権みたいなものなのですかね。守秘義務を守るということでやってきているのだろうなと。そうすると、結局家賃とかいうのはその収入に応じての家賃の設定になっていると思うのですけれども、その点はどのような形に今後なっていくのでしょうか。","respondent":"長尾住宅課長","answer":"入居されている方につきましては、認知症等でひどい症状の方というのは基本的にいらっしゃいません。そういった方がもしいらっしゃれば、福祉部門のほうにつないで適切な支援が受けられるようにというところは考えております。","voiceIndex":17,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"要は今回の条例は、収入の報告をする必要はありませんよという条例なのですよね。ということは、収入がわからないわけではないですか。それをどういう形で調べて、どういう責任を持って設定するのですか。","respondent":"長尾住宅課長","answer":"収入の確認の方法なのですけれども、官公署の書類の閲覧というところは、具体的には税務課のほうでの収入の確認であるとか、あるいはその方が働いていらっしゃるのであれば、もうその働いている会社自体に確認をするとか、そういったところが考えられます。","voiceIndex":19,"id":"exchange-008"},{"speaker":"大沢委員","kind":"意見","question":"先ほどの話の中で、知的障害、精神障害を含むという言葉があったのですけれども、ちょっとそこのところをもう一回説明をお願いしたい。","respondent":"長尾住宅課長","answer":"公営住宅法の施行規則の第８条の中で、具体的に定められております。具体的に言いますと、介護保険法に規定する認知症である者、知的障害者福祉法で規定する知的障害者、精神保健及び精神障害者福祉に関する法律に規定する精神障害者という定義が示されております。","voiceIndex":21,"id":"exchange-009"},{"speaker":"大沢委員","kind":"確認","question":"今後この「認知症等」という言葉で表現をしますけれども、とどのつまりは区が名義人であるこの方たちの家賃を、さまざまな書類・判断によって区が家賃を設定できるというのがこの改正の趣旨であるのか、もう一回確認させてください。","respondent":"長尾住宅課長","answer":"委員のお話しされていたとおりでございまして、これまでは収入報告を入居者の方からしていただくことによって、それに基づいて使用料を決定する、減額がなされていた状況があるのですけれども。","voiceIndex":23,"id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"入居者というには、名義人である本人と、それと同居人という２者がやはり家の中にいるわけです。この名義人ではない同居人のかかわりは、ここの改正においてどのようにかかわっていくのか、あるいはかかわらなくていいのか、そこのところを教えてください。","respondent":"長尾住宅課長","answer":"同居されているご家族とか、あと連帯保証人の方なども区営住宅にはいらっしゃる場合がありますので、そういった方がいらっしゃる場合は、そういった方たちとも連携をとっております。","voiceIndex":25,"id":"exchange-011"},{"speaker":"大沢委員","kind":"質問","question":"この改正の部分においては、同居人がいなくて単身で生活をしている方たちにとっては、この制度というのが、今までより勝手のいい制度に変わったということで認識していいのでしょうか。","respondent":"長尾住宅課長","answer":"そのような場合に、入居者にとっては不利益をこうむることが少なくなると理解していただいて結構かと思います。","voiceIndex":27,"id":"exchange-012"},{"speaker":"筒井委員","kind":"質問","question":"公営住宅法等が改正されて、それに基づいて品川区の条例の整備ということなのですけれども、この公営住宅法等が改正された時期というのはいつごろなのでしょうか。","respondent":"長尾住宅課長","answer":"こちらが法改正されて施行されたのが、昨年の７月２６日になっております。","voiceIndex":29,"id":"exchange-013"},{"speaker":"筒井委員","kind":"質問","question":"昨年の７月２６日なのですけれども、条例のほうが半年以上たってからなのですけれども、大体法改正に伴っての条例改正という時間というのは、大体半年ぐらいかかってしまうものなのでしょうか。","respondent":"長尾住宅課長","answer":"その報告いただいた内容に基づいて、次年度の使用料というのを決定しているという流れで今までも運用しております。そういったこともありまして、平成３０年度の使用料決定に必要な収入報告というのは、改正法が施行される前の昨年６月にもう既に実施しておりました。","voiceIndex":31,"id":"exchange-014"}]},{"id":"topic-02","title":"第３１号議案 品川区立区民住宅条例の一部を改正する条例","agenda":"第３１号議案 品川区立区民住宅条例の一部を改正する条例","exchanges":[{"speaker":"横山委員","kind":"質問","question":"今回賃貸借契約に移行という話なのですけれども、４７戸全て移行になるのでしょうか。通知ですとか、賃貸借契約もスムーズに進んでいらっしゃるのかどうか、その状況だけお聞かせください。","respondent":"長尾住宅課長","answer":"新管理会社のほうを通じて、新たな契約については個別に調整をしていると伺っておりますが、入居されている方の中でそのまま住み続ける方と、あと出ていかれる方のご予定というところまでは、こちらのほうでは把握しておりません。","voiceIndex":45,"id":"exchange-015"},{"speaker":"横山委員","kind":"質問・要望","question":"今、状況をお聞かせいただきました。１９戸ということで、昨年８月に通知のほうは全てしていただいていて、新しい管理会社の方ともつないでいただいているということを確認できました。今後、今現在の状況でそのままお住みになる方と、また出られる方がいらっしゃるということなのですけれども、スムーズに移行が進むようにサポートのほうをぜひ要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-016"},{"speaker":"大沢委員","kind":"質問","question":"新旧対照表のところに、この資料の日付を見ると、「平成２９年１２月１４日」となっているのは、これはどういう意味なのでしょうか。これをちょっと教えてください。議案を審議する段取りの時系列というものを教えてください。","respondent":"長尾住宅課長","answer":"こちらは、新旧対照表を印刷する際に、その印刷日が入っていただけでありまして、特に改正する期日との連動ということはございません。大変失礼いたしました。","voiceIndex":48,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、順次今回のように借上型住宅の位置づけが廃止されてきたわけですが、これまでのケースでオーナーですとか居住者からのご相談みたいなのはどのようなものがあったのか、そういうのはなかったのかというのをちょっとお伺いしたいと思います。","respondent":"長尾住宅課長","answer":"オーナー側、あと入居者の方からのご相談というところですけれども、特筆するようなところはございませんで、順調に引き継ぎのところについてもできていると考えておりますので、今のところは特に問題はないと考えております。","voiceIndex":51,"id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"そうですか。今回も４７戸のうち１９戸しか入居されていなかったということなのですけれども、位置づけが公の施設ではなくなったということで、その後こういう空いていたところというのは埋まっていっているのでしょうか。それはもはや区の施設ではないのであれかもしれないのですけれども、区としてはつかんでいらっしゃるのか、その状況をお伺いしたいのが１点。","respondent":"長尾住宅課長","answer":"区民住宅としては、建設型・借上型を含めてありましたけれども、一定程度定住化に対しての役割というのは果たしていると考えております。","voiceIndex":53,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと何か今のご説明ですと、一定もうこの目的は達成されているのでという話に聞こえてしまうのですが、今後区民住宅というのは、どのような考えで区としては事業を進めていく考えなのでしょうか、伺いたいと思います。","respondent":"長尾住宅課長","answer":"そういった状況を一度整理しまして、平成３０年度に区民住宅のあり方について検討する予定ですので、その中で今後の活用の仕方も改めて考えていきたいと思います。","voiceIndex":55,"id":"exchange-020"},{"speaker":"西本委員","kind":"質問","question":"４７戸あって、１９戸しか入っていないということは、いつからこういう状況だったのでしょうか。借上型ですから、入っていないところの保証もされていると思うので、かなりの税金が投入されていると思うのです。それはどのぐらいの品川区の負担があったのだろうかと思うのですが、いかがですか。","respondent":"長尾住宅課長","answer":"こちらの区民住宅につきましては随時募集で入居者も指定管理者を通じて募集しておりましたので、そういった入居に向けての動きというのもありましたが、結果的には新しく入ってこられる方というのがいらっしゃらず、逆に出ていかれる方が結果的には出ていったので。","voiceIndex":57,"id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"出ていかれる方が多いということは、何かしらの課題があるのではないかと思うのです。ですが現在このような状況になっているというのは、何か原因があったのでしょうか。そしてまた出られる方もいらっしゃるということになると、やはり何か不都合があったのでしょうか。何かわかればと思うのですが、いかがでしょうか。","respondent":"長尾住宅課長、藤田都市環境部長","answer":"入居されていた方の中で、やはり住み始めたころとちょっと状況が変わって、やはりその方の収入と家賃とのバランスを考えた時に、もう少し安いところへとか、もう少し広いところに行きたいとか。そういう意味で、特殊な事情としては今回の平成３０年８月で終わりというのが一つのタイミングで、入居の形態について皆様お考えになった結果だと区のほうとしても捉えております。","voiceIndex":59,"id":"exchange-022"},{"speaker":"西本委員","kind":"質問・要望","question":"家賃もあまり変わりませんよ、ただ単に管理体系、管理者が変わりますよといっただけでそのように動揺するのか、今までのように同じくしてくれる、もしくは家賃等々少し下げていただけるとかいろいろな状況があれば、いろいろな相場的なものは、もうこれ去年４月の段階で半分ぐらいという形ですから、その後も出ていかれているということは、その運営状態がどうだったのかなという疑問がやはり私は出てきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-023"}]},{"id":"topic-03","title":"第３２号議案 品川区手数料条例の一部を改正する条例","agenda":"第３２号議案 品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"田園居住地域についての参考で、ご説明が資料にありますが、生産緑地がある区とはどこになるのでしょうか。２３区であれば教えてください。それと、田園住居地域の指定は当面考えていないということなのですが、この許可申請が仮に行われて許可された場合というのは、具体的などのような制限がかかるのか伺いたいと思います。","respondent":"鈴木建築課長","answer":"ご質問の２点目ですが、この地域が指定された場合の変化としますと、生産緑地、農地を保全していくという観点からの法改正ですので、今までは生産緑地、農地に伴う、例えばそこで生産されたものを店舗をつくって、店舗でお店として飲食していただくような場合は。","voiceIndex":76,"id":"exchange-024"}]},{"id":"topic-04","title":"第３３号議案 品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"第３３号議案 品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"大崎駅西口Ｆ南地区などにかかわる。地域住民の間で大変な問題になっている、問題が多い計画だなということを言いたいと思いますが、まず２つお伺いしますが、単純にＥ西地区とＦ南地区の容積率の最高限度がすごく違うのですけれども、これはなぜそのように変わるのでしたか。それほど違うのか。それと、区の都市計画決定が都の決定後の３月予定になっている理由が何かあれば、お伺いしたいと思います。","respondent":"稲田都市開発課長、鈴木建築課長","answer":"それと品川区も公道地区とか防火地域、準防火地域等は、その時点で決定はしているというところです。では、なぜ大崎駅西口Ｆ南地区第一種市街地再開発事業の都市計画決定が３月の予定なのかです。それをいかにその都市計画決定の中身を建築基準法のほうにも位置づけて、実効性を担保するかですので、基本的な考え方はこの計画だけではなくて、都市計画決定がされた後、ただちに直近の議会にお諮りして。","voiceIndex":92,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"私がやった質問の中で、なぜ区の部分は都決定の後の３月予定になっているのですかという理由を伺ったので、聞かせてください。しかもその１４９ｍは都市計画でも何でもなくて、ただ単に航空法で目いっぱいということですから、まちづくりでも何でもないと私は思うのですけれども、この再開発のビルが建つ該当地域と、心配されている近接の方々が住んでいる住宅地のそれぞれの用途地域はどうなっているのか。","respondent":"中村都市計画課長、鈴木建築課長","answer":"ただ、これが２つ合わさることによって、やはり適切にまちづくりが進んでいくところは目的としているところではありますが。計画の中では容積率が高いところがありますが、そういった周辺の規定も守りながら計画されているです。これは日影がかかる建物について、その周辺の日影を守らなければいけないというところがありますので、周辺については今までと変わらず。","voiceIndex":95,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっとご説明いただきたいのが、開発計画地の北側にあるところの住宅地の用途地域は何で、具体的にはどういうルールがかかっているのですか。何時間とかあるのではないですかという、そこら辺が聞きたかったのです。説明をお願いします。","respondent":"鈴木建築課長","answer":"北側につきましては第一種住居地域でございまして、日影のほうが４時間、２.５時間です。","voiceIndex":99,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"そこに、では責任を負うのは誰なのかというと、再開発組合ではやはり今のところそういう義務がないので限界があると思いますので、私は行政しかないと思うのですけれども、その複合日影の影響をやはり品川区がしっかりと出さないと、近隣への住環境に配慮したとはとても言えないと思うのですけれども、区が複合日影の影響を出すべきだと思いますし、あるいは出させるよう指導するべきだと思うのですけれども。","respondent":"中村都市計画課長、稲田都市開発課長","answer":"したがいまして、今までは一つ一つの建物それぞれその規制の範囲を守ることによって、周辺環境も一定程度確保しているというような考え方で、これについては法律論になりますので。こちらの開発のほうからの考え方としましては、基本的に都心としての中核拠点であって、品川区におきましても都市活性化という点、大崎駅周辺というのは西口も含めましてこのようなまちづくりを整備するというところで。","voiceIndex":103,"id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"私は一般論で聞いているのではなくて、この大崎でも実際に建っているわけですから、複合日影の影響というのはやはり区が具体的に検証すべきなのではないですかということです。少なくともこの大崎に関しては、区が責任を持って出してほしいと思うのです。これは絶対にお願いしたいのですが、いかがでしょうか。大崎の同様の再開発でそのような計画はあったのでしょうか、伺います。","respondent":"稲田都市開発課長","answer":"そういう中に住宅も含まれておりまして、このまちづくり、大崎の周辺を活性化していこうというところで住居機能も入れているです。そういう中におきましては、ファミリー層向けのところ、それから単身者向けのところということで適正配置を行ってきてあります。","voiceIndex":106,"id":"exchange-029"},{"speaker":"安藤委員","kind":"確認","question":"それと、このような計画というのはあったのですか。日影に関してはぜひやってほしいのですけれども、やる考えはないということなのですか。品川区はそこまでタッチしないと。せめてどういう影響が出るかというのをまずつかんだ上で、それがどうなのかということを考えるべきであって、その検証すら背を向けるというのは私はどうかなと思うのですが、やる考えはないということなのですか、伺わせてください。","respondent":"稲田都市開発課長","answer":"複合日影を検討させないのかというような話ですが、先ほど来言っていますように、地域への配慮という面では考えられるかもしれませんけれども、基本的に私どもはこの条例・基準を守りながらやっているです。","voiceIndex":108,"id":"exchange-030"},{"speaker":"安藤委員","kind":"質問","question":"再度そこは伺わせてください。大崎駅の再開発で、こういうビルで単身者が半分以上を占めるというのはありましたか、ないですかと伺ったので、それはしっかりお答えください。最後、この大崎駅周辺の開発を考える上で、これを進める上での地区計画ということですから伺うのですけれども、大崎駅のあの状態で、さらなる人口の集中の開発を進めるとういのは、私はまちづくりを進める品川区としてどうかと。","respondent":"稲田都市開発課長","answer":"人口をこのように増やしていいのかという話です。これはやはり大きな区の方針であります品川区まちづくりマスタープラン等々に基づきまして、都市型住宅というものを進めていく拠点の整備です。","voiceIndex":110,"id":"exchange-031"},{"speaker":"安藤委員","kind":"質問","question":"今の点は後でお願いします。では品川区は大崎駅をあのままで、もうどんどん進めていくという考えなのでしょうか。それをお伺いしたいと思います。ですからただでさえ今、山手通りに抜ける区道が時間帯によっては超混雑して、何と西口のラーメン店あたりまで車が並ぶ時もあるのですね。問題ないと考えているのでしょうか、伺いたいと思います。","respondent":"中村都市計画課長","answer":"大崎駅の混雑ですけれども、こちらのほうはＪＲのほうにも引き続き改善に対する検討を進めてもらうようにしています。それからあと、区道と山手通りの混雑というところですが、こちらのほうもさまざまなまちづくりの中でいろいろと道路の状況も出てくるかと思います。","voiceIndex":114,"id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"私が伺ったのは、現在の混雑の状況をどのように認識しているのですかという、問題だと思っているのですかというか、かなり混んでいるのですけれども、混んでいるという自覚があるのですかというのが一つ伺いたかったのです。お願いしているからいいのですというふうにはならないと思うのですけれども、いかがなのですか。その辺がちょっとわからないなと思って、そこら辺もお伺いしたいと思います。","respondent":"稲田都市開発課長","answer":"大崎駅の混雑ですが、まず再開発事業を行っていくときには、その直近の駅といいますか鉄道事業者等々にも協議をしまして、開発等をこのような形で今検討していますよということで、協議をずっとしながらやってきているです。","voiceIndex":116,"id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"この３番のところの4)の風営法なのですけれども、これは今規制が見直されたということがあって、今回は従前のものを適用するという考えなのか、これはどういうことを言っているのか。これは今どういう熟度になっているのでしょうか。","respondent":"鈴木建築課長、稲田都市開発課長","answer":"ただ、今その整理ができておりませんので、基本的には各地区計画が制定したとおりの考え方に伴って、ダンスホールは今、「用途地域上できない」というふうに、法体系的にも位置づけるために風営法改正前の風営法を引用するということで。大崎駅西口Ｆ東地区、大崎駅西口駅前地区ですけれども、こちらは現在準備組合で検討が進められて、平成２６年に準備組合ができたのですけれども、今それで検討が進められているところです。","voiceIndex":118,"id":"exchange-034"},{"speaker":"西本委員","kind":"質問","question":"それで手を上げている方もいらっしゃると思うし、それとここは西口商店街の中に入っているので、商店街がどう行動していくのかということもあるし、またそれこそここにはいろいろな娯楽施設も入っているところがあるので、そうなってくるとこの風営法も非常にかかわってくる可能性もあると思いつつ、今、これからのスケジュール感というのはどのようなスケジュール感をもって考えていればいいのでしょうか。","respondent":"鈴木建築課長、稲田都市開発課長","answer":"一括でやるか個別にするかということなのですが、今のところその進め方についてはちょっと内部で検討しているところなのですけれども、個別でご検討いただくというよりも、通知・お知らせ的なところは一括して。大崎駅西口駅前地区ですけれども、現在準備組合への加入促進も図りながら検討を続けているというところでございまして、言われました商業的な話とか、駅前地区であるというところからそういう話も出てきているですが。","voiceIndex":121,"id":"exchange-035"},{"speaker":"西本委員","kind":"質問・要望","question":"その整備を含めて、どう整備していくのかというところがとても不安だなと、風営法ですから、ただ単に法律が変わったのでという形だけでは住民は納得いかないところがあると思うのです。大崎の中でも目玉になるような新しい試みもぜひやっていただきたいという地域であるので、その辺の区のこれからのビジョンを含めて考えた時の、この開発の方向性はどう考えられているのか。","respondent":"鈴木建築課長、稲田都市開発課長","answer":"やはり各地区ごとでお知らせしていく時に、なぜダンスホールが風営法から外れたかというところはしっかりわかりやすく説明をして、それで地区ごとでどう考えていただくかということを、区としてもわかりやすくご提示して。基本的には品川区におきましては、大崎駅周辺地区というのは非常に広域活性化拠点として、業務の集積、商業機能、居住機能等を整備していきながら、まちづくりをやっていくということで、東西の歩行者ネットワーク等々も考えながら。","voiceIndex":124,"id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"ご年配の方が考えているダンスホールというイメージと、２０代とか１０代の方々の考えるダンスホールというのはやはり変わってくるので、定義づけも含めて整理していかないと、なかなかこれは理解を求めるのは難しいところがあると思いますので、ぜひそこをお願いしたいという意見と、それからＦ東地区については、本当にこれは目玉になるような。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-037"},{"speaker":"安藤委員","kind":"意見","question":"反対です。計画自体問題がある再開発を進めるための地区計画ですし、さらに区の再開発事業のかかわる都市計画決定もまだされていませんので、そういった時期の問題から見ても問題だと思いますので、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":134,"id":"exchange-038"}]},{"id":"topic-05","title":"平成３０年請願第９号 コミュニティーバスの運行に関する請願","agenda":"平成３０年請願第９号 コミュニティーバスの運行に関する請願","exchanges":[{"speaker":"新妻委員","kind":"提案","question":"それで、会派としましてもコミュニティーバスの要望等はこれまでもしてきたところではありますが、さまざまご答弁も確認をしていますけれども、まず１つ、公共交通の本数を増やしていくというところをしっかり事業者のほうに要望していくというところを区がこれまでご努力いただいているところですが、現状、どういう形で要望していただいているのか。","respondent":"中村都市計画課長","answer":"区としてこのコミュニティーバスの考え方といたしましては、１つは新しい道路が整備されるに伴いまして路線を増やしていったりですとか、あるいは地域の要望・声に応じまして、それを鉄道、あるいは今回のコミュニティーバスの場合ですとバス事業者のほうに伝えまして。","voiceIndex":144,"id":"exchange-039"},{"speaker":"新妻委員","kind":"質問・要望","question":"区が要望していただいた中で、具体的に今後このようになっていきますというような現段階で見えているところがあるのでしょうか。","respondent":"中村都市計画課長","answer":"事業者のほうは、この開通に合わせて今検討を行って、実施の方向で作業を進めていっているところです。","voiceIndex":146,"id":"exchange-040"},{"speaker":"新妻委員","kind":"質問・要望","question":"そこは、今回新たに２６号線が具体的にというご答弁をいただきましたので、確かにそこが通れば非常に便利になる、そこは一つ改善されると今理解をいたします。進めていただきたいと思います。例えばどのようなことが考えられるのか、区としてはこの地域においての改善策というのはどのようにお考えなのかというところをお聞かせいただきたいと思います。","respondent":"中村都市計画課長","answer":"その辺は事業者に対して、乗客の数とランニングコストとかいろいろとあると思いますけれども、区としてはまず要望を伝えることが大事だと思いますので、引き続きこの要望を伝えてまいりたいと考えております。","voiceIndex":148,"id":"exchange-041"},{"speaker":"新妻委員","kind":"質問・要望","question":"ある地域ではデマンドバスとか、またタクシーを利用しての買い物支援とか、そういうことをやっている地域も出てきておりますが、今後のそういった長期展望の中での高齢者支援、高齢者が生活のために外に出る支援というところでは何があるのか、コミュニティーバスも一つなのですけれども、そのほかにもそういうようなお考えがあるのかというところを確認したいと思います。","respondent":"中村都市計画課長","answer":"ただ、この辺は事業者に対して積極的に働きかけを行ってまいりたいと考えておりますが、やはり今要望の中にはさまざまな方角に行きたいという要望もあれば、またバス停はなるべく近いほうがいいということで、自宅に近いところにまたバス停の増設の要望など。","voiceIndex":150,"id":"exchange-042"},{"speaker":"安藤委員","kind":"質問","question":"ご説明あったのですけれども、２３区の中でのコミュニティーバスの実施状況をどうつかんでいらっしゃるのか伺いたいと、請願にはそういった記述もありますけれども、区としては実施状況をどうつかんでいるか、１点目です。多くの区では区民のニーズに応えてコミュニティーバスを走らせているのですが、なぜ品川区はやらないのか、改めて理由をお聞かせください。","respondent":"中村都市計画課長","answer":"品川区といたしましては、今品川区全域の鉄道路線網、さらにバス路線網もあります。こういったところの中では他区と比べて利便性が高いというところで、先ほどの繰り返しになりますけれども、今のところコミュニティーバスの運行は慎重に検討したいと考えています。","voiceIndex":152,"id":"exchange-043"},{"speaker":"安藤委員","kind":"質問","question":"２０区近くが何らかの形で実施しているということですが、先ほどからの質疑の答弁を聞いても、区として全くしようという意思が感じられずに、事業者へのお願いからということで、デマンドバスの話も出ましたけれども、タクシーですか、それも事業者へお願いしますということで、何と言いますか、住民の移動の権利保障というのは自治体の責務だと思うのですけれども、それを保障しようとするためには。","respondent":"中村都市計画課長","answer":"そのためには、バス、それから鉄道といったものは公共交通ということで、民間が運営している交通手段であっても公共交通と言われているように、簡単に廃止したり、あるいは値上げしたりできないように、それぞれ自治体とも協議をしながら進めて運行してもらっているところです。","voiceIndex":154,"id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"かなり後方支援といいますか、回りくどいといいますか、靴の上からかいているような支援の仕方で、権利はあると認めましたけれども、ただ、それを保障するのは自治体の責務なのではないですかとお伺いしましたので、そこら辺はしっかりどう考えているのかお伺いしたいというのが１点です。","respondent":"中村都市計画課長","answer":"ただ、区といたしましては、やはり先ほど委員もご指摘の移動の権利ですとか、あるいは安全に移動するような区民の外出の機会を多くつくるという考え方に伴いまして、事業者とともにこの利便性の継続を図っているです。","voiceIndex":156,"id":"exchange-045"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはりそういうものではないと思うのです。なぜこの建設委員会の資料では７００ｍで出すのか。区がつくったこの地域交通検討会では５００ｍなのに、なぜ７００ｍなのかというのをお伺いしたいと思いますし、あわせてこの地域交通検討会の資料にあるように、請願が出されている当該地域、南大井地域では、高齢者にとっては交通不便地域だという認識でよろしいのですね、お伺いします。","respondent":"中村都市計画課長","answer":"それ以上の歩行が困難な方というところになりますと、今度まずは福祉部門との連携支援を考えを意識しつつ、そしてまちづくり部門としての交通事業者との調整といったところで、一つの考え方をもって解決していくといった方法があるかと考えています。","voiceIndex":158,"id":"exchange-046"},{"speaker":"安藤委員","kind":"質問・要望","question":"７００ｍというのは相当大変ですよね。なぜ出さないのでしょうかというのをちょっともう一度お聞かせください。それと、地域交通検討会の資料では、南大井地域では交通不便地域となっているのですけれども、そういうことでよろしいのですかというのを伺ったので、しっかりとお聞かせいただきたいと思います。","respondent":"中村都市計画課長","answer":"この駅勢圏、バス停勢圏の距離の考え方については、これはそれぞれ考え方がありますので、この５００ｍという距離は一つの考え方です。今回お示しした７００ｍというのは、これは通常歩行が困難な方でも、ゆっくり歩いても１５分以内で来られるということでお示しをしたものです。","voiceIndex":160,"id":"exchange-047"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと答弁漏れがあるかと思うのですけれども、ここでは区が税金を出して招集したこの会議体、地域交通検討会では南大井地域は高齢者にとっては交通不便地域だと書いてありますが、これは区は認めますよねということをお伺いしたので、５００ｍなのか７００ｍなのかというのはちょっと平行線になりそうなのですけれども。","respondent":"中村都市計画課長","answer":"通常歩行が困難な方に対して歩ける歩行距離というもので、区が設定しているのは７００ｍです。特に困難な方の場合には、さらに短くなる可能性もありますけれども、これはまた別の側面から支援が必要だという考え方に基づく資料の場合は、そういった短い距離で出す場合もあります。","voiceIndex":162,"id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと何か区としての建設委員会で言っていることと、この区が招集した地域交通検討会で言っていることと整合性がとれないというのは、一体どういうことなのかなと思うのですけれども、それではこの資料は何なのですか。伺いますけれども、ここのどのような道路計画の整備でバス路線導入が期待されるのでしょうか。品川区の考え方はどちらなのですか。どちらなのですかというのをお伺いします。","respondent":"中村都市計画課長","answer":"公共交通の地域交通検討会の中でお示しした資料は、かなりもう歩行がほぼできない、別の福祉的な支援が必要な方も想定された中での徒歩圏というような意味です。","voiceIndex":164,"id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺ったもう一つの点、この資料の中ではここは不便地域だと書いているのですが、それでも特に対策を打たなくていいですよと。これはそんな期待されるのですか。どのような道路なのですかというのをちょっとお伺いしたいのですけれども、そこら辺もちょっときちんとお答えいただきたいと思います。","respondent":"中村都市計画課長","answer":"したがいまして、具体的に今ここはいつまでに完成させるというふうにはご提示することはできませんけれども、そういった新たな道路が整備されるに伴って、新しいバス路線も考えられる、また検討の余地がある。","voiceIndex":166,"id":"exchange-050"},{"speaker":"安藤委員","kind":"質問・要望","question":"例えば今までの質疑で２６号線の話が出ていますけれども、２６号線が通ればバスが通るだろうという回答も得ているという話ですけれども、ここは何なのですか。ここはどういう道路が通る予定でそういう期待がされるのですか。これが１点です。それ以外にも上大崎とかでもありますよね。解消法はコミュニティーバスだけではないのだということも言いますけれども、ではほかにどのような対策があるのですか。","respondent":"中村都市計画課長","answer":"ただ、考え方といたしましては、新たな道路の整備によって路線の設置を具体的に事業者のほうに積極的に勧めていっているといった考え方をお示しをしたものです。","voiceIndex":168,"id":"exchange-051"},{"speaker":"安藤委員","kind":"意見","question":"やはり交通不便地域だと書きながら、どういう道路計画があるのかというのもお示しできない、今書けない。でも、それでもって将来に期待されるから対策は打たないというのは、ちょっと私はあまりに行政の無策ではないかと思わざるを得ません。しっかりと地域の実情に応じたコミュニティーバスの運行が必要だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":170,"id":"exchange-052"},{"speaker":"筒井委員","kind":"質問・要望","question":"私も区民の東西の交流・流動や都市型観光という観点から、品川区を東西横断するようなコミュニティーバスというのをぜひつくっていただきたいとかねてから言っておりましたけれども、このたび２６号線が開通予定ということで、武蔵小山から大井町までの路線なのですけれども、これはこの２６号線も活用しながら。","respondent":"中村都市計画課長","answer":"この路線が確かにご指摘のとおり、長ければ長いほどいいのかもしれませんけれども、運行を開始するにあたっては、まずはある一定程度の設定が必要だですので、その辺は今後バス事業者とともに詰めを行っていきたいと考えています。","voiceIndex":171,"id":"exchange-053"},{"speaker":"筒井委員","kind":"質問・要望","question":"先ほど都市計画課長がご答弁で、他区がコミュニティーバスを導入した理由としまして観光ということがあるとおっしゃられましたけれども、品川区も今、都市型観光というものを進めておりますけれども、そうした品川区の都市型観光を進めるという点、それに関連してコミュニティーバスを走らせるというお考えはないのでしょうか。その点はどうでしょうか。","respondent":"中村都市計画課長","answer":"他区の場合ですと、ピンポイントで観光地に駅前から運行したりというのがあります。品川区でも代表的なものは、しながわ水族館行きのバスとか、そういったもので運行しております。今後、必要に応じてその辺はまた検討していく必要はあるかと考えております。","voiceIndex":173,"id":"exchange-054"},{"speaker":"筒井委員","kind":"質問・要望","question":"当然そうするとなかなか廃止しにくいだとか、財政の負担が大きくなる、赤字路線になるといったおそれもあるのですけれども、品川区も本当に必要なルートを絞った上で、都市型観光の観点から検討していくというのが一つの案だと思いますので、ぜひともその点も検討していっていただきたいと思います。よろしくお願いします。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":175,"id":"exchange-055"},{"speaker":"西本委員","kind":"質問","question":"コミュニティーバスについては、今までも幾つか出ていたと思うのですけれども、非常に気になるのが費用対効果なのです。２３区の中で３区がまだということなのですが、他区はどのような運営の方法をしているのかと思うのです。その中で、品川区として費用対効果を何か検証したことはありますでしょうか。ほかのところの運営状況がわかれば教えてください。","respondent":"中村都市計画課長","answer":"小さいところと大きいところでは以上です。区といたしましては、１つは路線を延長した場合はどうかというところを検討した時に、既存のバス路線のバス停を１つ増やし延長すると、約２,０００万円の負担が出るという試算があります。","voiceIndex":176,"id":"exchange-056"},{"speaker":"西本委員","kind":"質問","question":"結構な金額ですね。コミュニティーバスということの政策の位置づけをちょっとお聞きしたいのです。今後いろいろな政策の中でコミュニティーバスの検討をするという気持ちがあるのか、やはりそれは費用対効果を考えるとという計算の中である程度の答えが品川区としては出てくるものなのか、今後需要の中で検討するという余地があるのかどうかということはいかがですか。","respondent":"中村都市計画課長","answer":"いずれにしましてもそういった協議が必要だというところで、非常に慎重な検討が導入には必要だと考えております。","voiceIndex":178,"id":"exchange-057"},{"speaker":"西本委員","kind":"質問・要望","question":"この請願の中に書いてある文書の中に、大井町とか大森のヨーカドーなどのショッピングにという施設もあるのですね。なので、そういう手法も考えられないことではなくて、あとは例えばご答弁にあったように、いろいろな事業者との関係性の中で、ここのところはちょっとやってほしいという場合での補助を出すということも考えられないことではないのかなと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":180,"id":"exchange-058"},{"speaker":"大沢委員","kind":"質問","question":"１つだけ、先ほど７００ｍに４０駅とバス停が２６４個ということで都市計画課長からお話をいただいて、この中で円で７００ｍ以内、あとは５００ｍという話も出たのですけれども、実際品川区、目黒区、江戸川区を除いた２０区は、例えば２００ｍ、１００ｍ、０ｍ、家の前までドア・トゥー・トアみたいに果たしてコミュニティーバスを運行しているのですか。","respondent":"中村都市計画課長","answer":"今、委員ご指摘のとおり、このコミュニティーバスの要望については、総論ではやはりあったほうがいいという意見は非常に多数ですけれども、いざ現実に走らせるとなりますと、今の委員ご指摘のように自分の家の近くから目的地まで運行してほしいという要望の中で。","voiceIndex":181,"id":"exchange-059"},{"speaker":"安藤委員","kind":"意見","question":"結論を出すで、採択なのですが、やはり住民の移動の権利保障をしっかりと自治体の責務として果たしてほしいと。全ての区の施策の土台になりますし、そういったところに税金を使うのは喜ばれる税金の使い方でもあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":187,"id":"exchange-060"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"不採択ですが、今後品川区のまちというのは、先ほど話にも出ていたように２６号線が開通して利便性がとてもよくなる。そういった状況の中で、この都市環境がもう年々変わっていく中で、やはり交通の利便性は常に追求していかなければならないものだと思っていますので、常にアンテナを張ってバス事業者と協議を重ねて、何が最善であるかというのを見出していただきたいと思います。不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":188,"id":"exchange-061"},{"speaker":"西本委員","kind":"意見","question":"本日結論を出すで、不採択。先ほども意見として言わせていただきましたが、今後いろいろな手法を使って、利便性、もしくは観光や福祉の観点も含めて総合的に考えていかなければいけないと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":189,"id":"exchange-062"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこら辺をもう一度説明いただきたいのですけれども、この「高架橋の位置について」というところの上のほうの説明がちょっとよくわからなかったと思って、お伺いしたいと。世帯数とあと建物の数をお伺いしたいと。それと、広場と道路の計画についても、世帯数と建物の立ち退きはどれぐらいになる計画なのか伺います。","respondent":"東野まちづくり立体化担当課長","answer":"こちらの京急線の立体化に伴う立ち退き人数等々ですが、こちらは１２月に行われた説明会の中で、東京都からは２５軒の方にご協力をいただくというような回答がございました。具体的な世帯数、建物数については明確になっておりません。","voiceIndex":199,"id":"exchange-063"},{"speaker":"安藤委員","kind":"質問","question":"高架化に伴う立ち退きのほうの請願にあるような、専門家等第三者による検討はされたのでしょうか、伺いたいと思います。それと、現在それぞれ計画案への公告縦覧と意見書受付がもう終わりまして、環境影響評価の案をつくっている最中だと思うのですけれども、都市計画案への意見書の数と反対・賛成意見の内訳は大体どのような感じなのかというのを伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"立体化の線形等についての第三者による検討です。こちらにつきましては、冒頭でご説明したとおり、東京都が検討・調査を行っているものです。","voiceIndex":201,"id":"exchange-064"},{"speaker":"安藤委員","kind":"質問","question":"それと、広場のほうの資料の具体的な中身についてお伺いしたいのですけれども、この見開きの冊子の開いたところの左下、２、北品川駅周辺における課題ということで、「駅周辺の道路では駅利用者がタクシーや一般車等で駅前に乗り降りするため、道路上の駐停車が発生し円滑な交通や乗降者等の安全を十分に確保できていません」と書いているのですけれども、私はこの地域を歩いていて。","respondent":"東野まちづくり立体化担当課長","answer":"こちらにつきましては、私ども説明会の中でもご説明させていただいておりまして、旧東海道に接するところにつきましては、景観の中にもありますような街道松を植えたりとか、そういうような措置で分けていきたいという考えです。","voiceIndex":203,"id":"exchange-065"},{"speaker":"安藤委員","kind":"確認","question":"旧東海道品川宿周辺まちづくり協議会の方々がやはり旧東海道の幅を守ってほしいというのは、すごく切実な声だと思うのです。それと、資料の件ですけれども、これはそのように伺っているということなので、では別に区が確認しているわけでは、調査したわけでも測定したわけでもないということなのでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"旧東海道品川宿周辺まちづくり協議会からのご意見としては、地域の意見としてどういう対応ができるかという部分は今後考えていきたいと考えています。都市計画の定める中でどのような対応ができるかというところで、今後も検討を進めてまいります。","voiceIndex":205,"id":"exchange-066"},{"speaker":"安藤委員","kind":"意見","question":"それ以前に実態として、こういった課題に挙げられているような課題というのがあるという実態はないと私は認識しておりますので、こういったことを課題に挙げて地域の方に大きな負担をかけるような計画というのは、やはり見直すべきだと思います。一旦やめます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":207,"id":"exchange-067"},{"speaker":"新妻委員","kind":"質問・要望","question":"これもしっかり今後も定期的にそういうご意見等、またこのようになりますよというこちらの情報発信もコンスタントに行っていただきたいと思います。できること、できないことあると思うのですけれども、できることを最大限に寄り添っていただきたいと思いますので、よろしくお願いいたします。いかがでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"都市計画として必要な施設として区のほうでは進めている計画ですが、まちの方々、それから権利者の方々のご意見につきましても、どのような対応ができるかというところも含めまして、今後とも話し合いを行ったり。","voiceIndex":210,"id":"exchange-068"},{"speaker":"西本委員","kind":"質問・要望","question":"ここは東京都の管轄だとしても、図面が出てきた以上、そこにかかわるのはわかりますよね、品川区の住民なので、そこは東京都がやるからとかではなくて、品川区という形でもしっかりかかわって、ご理解を求めながらやっていってくださいねということをお願いしたはずなのですけれども、なかなか時間的に１２月ですか、東京都のほうからの指針が出てきたというところで。","respondent":"東野まちづくり立体化担当課長","answer":"こちらにかかる方につきまして、事前の情報提供をというお話ですが、まずはこちらの都市計画を進めるにあたりまして、この都市計画の位置、それからどういう内容、どういう考え方で都市計画を進めるのかという説明会を行った後に。","voiceIndex":212,"id":"exchange-069"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり立ち退きとかいうのは、高架化は私も要望といいますか、やはり必要だという部分はあるのですね。ただ、そのご協力いただいている方々には丁寧にご理解を求めていくということは、これからもしていただきたいと思うのですが、それと、交通広場については、これは品川区独自の考え方だと思うのです。これはどのようにこれから進められようとするのでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"広場計画につきましては、現在都市計画案としての説明を行っているところです。こちらにつきましては東京都の立体化計画と合わせまして、今後都市計画審議会のほうへ諮っていくような形になります。","voiceIndex":214,"id":"exchange-070"},{"speaker":"西本委員","kind":"質問","question":"結局もうこういう交通広場というふうに先に出てしまっているので、それが決定になってしまうのかなという不安がやはり出てくると思うのです。その中でのこの交通広場というのはどういう位置づけになるのでしょうか。旧東海道品川宿周辺まちづくり協議会との関係もあるかと思いますし、地域の方のご意見もたくさんあるかと思うのですが、今後のやり方についてはいかがでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"この北品川の地域につきましては、こちらのパンフレットにもありますように、駅周辺を重点検討区域と定めておりまして、こちらにつきましては地域の拠点としたまちづくりを進めていると、こちらがまずマスタープラン。","voiceIndex":216,"id":"exchange-071"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、そういう考え方もあるのではないか、その中で十分に地域の方々と再開発も含めて議論して、具体的にそれを達成するためのハード的な整備はどうしたらいいのかという大きな議論をしていただきたいと思うのですが、その辺の考え方はいかがでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"再開発につきましても１０年スパンで行うような事業ですので、そことの整合性はとっていきたいと考えております。","voiceIndex":218,"id":"exchange-072"},{"speaker":"大沢委員","kind":"質問","question":"そもそも京急のこの立体化の話、今西本委員からも全体像を見た位置づけというような話でちょっと私は受け取ったのですけれども、この駅の立体化についても、今お話に出ました品川浦周辺、ひいては港区になりますけれども品川駅周辺、もっと延ばせば今度、品川の新駅について、そこら辺からリンクしている計画の一つであるという認識でここの高架化に対する問題はとらえていいのでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"ちょっと時間を追っていきますと、平成７年当時、京急線八ツ山橋付近の立体化の検討を建設省・東京都・品川区、それから鉄道事業者といったところが入って検討していった結果として、品川駅部分のかさ上げが必要と。","voiceIndex":220,"id":"exchange-073"},{"speaker":"大沢委員","kind":"質問","question":"そうすると、この計画によって、今、課長がおっしゃった３つの踏切の除却をすることによって、交通アクセスまたはその立地の利便性がさらに上がると。武蔵小山周辺も踏切を除却することによって東西がつながって、非常に利便性のよい土地に成長を遂げたということで、この部分についてはそういうような副産物というか成果物が生まれてくるというのは、確信を持っていいのでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"踏切解消をすることによりまして、駅が高架化します。高架化になることで、東西のまちにつきまして行き来がしやすくなる、まちの一体化ができるというようなところもありますので、委員が今おっしゃったとおりです。","voiceIndex":222,"id":"exchange-074"},{"speaker":"大沢委員","kind":"質問","question":"そうなると、今度この事業主体のほうに話は移りますけれども、先ほど来、高架化については東京都主体の事業であるということで、この請願にありますように「現在のルートが唯一無二であることを証明するような」ということなのですけれども、これは現実問題できることなのでしょうか、お伺いしたいです。","respondent":"東野まちづくり立体化担当課長","answer":"私どもはそういう東京都からの報告を受けまして、これが適切な線形だと考えておりますので、これ以上東京都に何ら言うことはないと考えています。","voiceIndex":224,"id":"exchange-075"},{"speaker":"大沢委員","kind":"質問・要望","question":"ではまとめますが、この２つの請願に共通して言うと「立ち退きのない形で」という文言がありますけれども、先ほど来各委員がお話をしたように、やはり利便性が上がる、土地の価値が上がってくるというところにおいてはやはりプラスの要素が非常に多いわけでありますが、立ち退きを迫られる方にとってはやはり住みなれた土地を提供するわけですが、そのあたりの提供される方に。","respondent":"東野まちづくり立体化担当課長","answer":"委員がおっしゃったところは非常に重要なところだと考えています。こちらの事業にかかる方、ご協力いただく方の生活再建を十分に考えた上で、そういった説明についても行いましてご協力を求めていきたいと考えています。","voiceIndex":226,"id":"exchange-076"},{"speaker":"筒井委員","kind":"質問","question":"そういった観点を踏まえて質問しますけれども、まずこの鉄道橋の高架化、ずらさなくてはいけないということなのですけれども、ぱっと素人目線ですけれども、既存の鉄道橋をそのまま使えばいいのではないかと思うのですけれども、それは今現行通っている路線があるから、これを使えないという理由なのですか。この鉄道橋を活かすことはできないのですか。","respondent":"東野まちづくり立体化担当課長","answer":"ですから、現在の京浜急行線を走らせた状態で、それの上を通るようなもの、または東側を通るようなものが必要になってきます。そういった意味では、運行させながらというところは非常に難しいものです。","voiceIndex":228,"id":"exchange-077"},{"speaker":"筒井委員","kind":"質問","question":"羽田新飛行ルートと同じように、何かこれしかないという一本やりで決めてしまうというのは、なかなかよくないことかなと考えておりますので、ほかのセカンドオピニオンとしてほかのルートを探るという、新しい別途第二の意見を持った専門家の方たちにご意見を聞くというお考えはないのでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"こちらも冒頭にご説明していますが、この高架化計画につきましては東京都が計画し、東京都施工で進めるものです。区が改めて専門家、これも専門家と言ってもどこがという部分がありますけれども、改めてそういうところに調査を出すということについては考えてございません。","voiceIndex":230,"id":"exchange-078"},{"speaker":"筒井委員","kind":"質問・要望","question":"それで、この品川浦のほうの開発、品川駅南地域まちづくりビジョン全体としてここの交通広場を設ける必要があるというようなご説明でしたけれども、私もこの資料を見せていただいたのですけれども、それがこの交通広場によって立ち退かれる人、およびこの説明文を見る感じでも、全体のビジョンというのがなかなか見えないので、こういうまちづくりをやりますから。","respondent":"東野まちづくり立体化担当課長","answer":"そういった流れから、まちづくりを進めているというようなものです。駅前広場という部分につきましても、京急の高架化の機会に合わせまして進めていくという位置づけになっているものです。","voiceIndex":232,"id":"exchange-079"},{"speaker":"筒井委員","kind":"質問","question":"一方のまちの方のご意見によりますと、やはり品川浦に行くには、直接品川駅からタクシーなり徒歩なりで行ってしまうので、わざわざここに交通広場をつくる必要はないというご意見もあるのですけれども、それについてどうお考えでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"そういったところ、全体を加味しながら考えているものです。","voiceIndex":234,"id":"exchange-080"},{"speaker":"筒井委員","kind":"質問・要望","question":"いずれにしましても、この交通広場の景観、ここにも隣接旧東海道の景観と合わせたデザインということを書いてありますけれども、まさにそのとおりで、ここは旧東海道に面したところに広めの空間をつくってしまうと、かなりその見え方によって従来のイメージが崩れてしまうというおそれがありますので、そこは非常に配慮していただきたいと考えております。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":236,"id":"exchange-081"},{"speaker":"安藤委員","kind":"質問","question":"計画案作成段階で、住民意見を反映させるというのが都市計画法第１６条ですが、その都市計画法第１６条違反ではないでしょうか、伺います。これが１点です。再開発ではわざわざ地権者のみに限定して、第１７条の説明会を開いて案をつくったのに、なぜ同じ都市計画決定なのに、この広場ですとそれをしないのかもあわせてお伺いしたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"こちらの駅前広場計画につきましては、昨年１月の都市計画素案の説明会、それから１２月の都市計画案の説明会、こちら２回の説明会を行ってあります。都市計画素案の説明会におきましては、法的には都市計画法第１６条の位置づけになってあります。","voiceIndex":237,"id":"exchange-082"},{"speaker":"安藤委員","kind":"質問","question":"ですから、やはりこれはおかしいと。ちょっと伺ったのは、再開発では何で地権者だけを呼んだ説明会をやっているのに、ここでは何でやらないのか。それは何なのですかねと思って、何が違うのかなと思って、同じ財産のかかる地権者にもかかわらずですよ。そこら辺がちょっとわからなかった、答弁もなかったので、１つお伺いします。それぞれ伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"昨年１月の都市計画素案の説明会につきましては、東京都と一緒に行ってありますが、その時は沿線住民の方、広い範囲でご案内をした上で台場小学校で開催させていただいたものです。その中にはもちろん地権者の方へのご案内も含まれているものです。","voiceIndex":239,"id":"exchange-083"},{"speaker":"安藤委員","kind":"質問","question":"これはやり直してもいいぐらいだと私は思いますね。それと清水横丁の話で、しつらえという問題ではないですよね。清水横丁だってその時の幅が残っているわけで、旧東海道もそうですけれども、皆様は幅にこだわっているわけではないですか。ですから、清水横丁はなくなっても仕方ないと考えているということなのですか。それは区の姿勢としてどうなのか、もう一度伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"こちら清水横丁につきましては、幅のところは計画としては拡幅するというような計画になりますが、そういった清水横丁があったという記憶を残すようなしつらえを考える中で対応をしていきたいと考えております。","voiceIndex":241,"id":"exchange-084"},{"speaker":"安藤委員","kind":"質問","question":"人が住んでいない建物が２棟あったけれども、今は除却とありましたけれども、もう既に今は撤去されていますので更地になっているわけです。ですから、伺いたいのは、立ち退きのない範囲での計画に変更したとして、何か問題でもあるのでしょうか。私は現在の方々の立ち退きを発生させない範囲の計画に変更してほしい。それで何も支障がないと思いますけれども、いかがでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"まちの発展のためにきちんと道路に面した駅前広場というものが必要と考えていますので、立ち退きのない範囲でというところにつきましては、今現在としては考えていないところです。協力をお願いしていきたいと思います。","voiceIndex":243,"id":"exchange-085"},{"speaker":"安藤委員","kind":"質問","question":"具体的にお伺いしますけれども、今は踏切があるので、しかも踏切があるにもかかわらず、北品川駅の改札は西側しかないので踏切を一旦渡らなくてはいけない。これはもう全くそこら辺は解消されると。なおかつ駅にも行けるでしょうと。この範囲の中で何か支障があるとは全く思えないのですけれども、具体的にそこら辺の機能に照らして何か問題があるのですか。いかがでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"ロータリー型のものを計画した場合に、車の車輪の関係、軌跡といいますけれども、そういったものをきちんととった形での計画が必要になってありますので、このぐらいの大きさのものが必要と考えているものです。","voiceIndex":245,"id":"exchange-086"},{"speaker":"安藤委員","kind":"質問","question":"それに対して区長が、「広場が必要かどうか。これは明らかに一般論ではなくて、北品川駅の広場の件について聞いたのに答えたわけですから、もう区長がこのように答えたわけです。その中で言っているように、区長は京急に広場が本当に必要なのですかと話をしたのでしょうか。ぶつかることになると思うと言っていましたけれども、ぶつかったのでしょうか。そこら辺をちょっと伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"こちらはこの交通広場というだけではなく、地域のまちづくりにおいて必要な空間であるというところ、そういった機能も兼ね備えたものということで考えてありますので、今後とも京急の連続立体化事業とあわせて進めていきたいと考えています。","voiceIndex":247,"id":"exchange-087"},{"speaker":"安藤委員","kind":"質問","question":"一般質問で私はこの問題も聞きましたところ、区長は何か人が変わったかのように、タウンミーティングでは要らないと言ったのに、一般質問の答弁では、いや、必要ですから進めますみたいなことを言っていたのですけれども、非常に不誠実だなと思ったのですけれども、区長は具体的にタウンミーティングを開いて直接区民の方に回答するという場をつくって、具体的に聞かれたことに対して、「いや。","respondent":"東野まちづくり立体化担当課長","answer":"区長の発言の趣旨としましては、先ほど来私が答えているものと何ら変わらないと考えています。私ども所管といたしましては、区長からの命を受けまして京急などと調整をしています。","voiceIndex":250,"id":"exchange-088"},{"speaker":"安藤委員","kind":"意見","question":"区長からの命を受けて一貫してやっていると、ぶれはないのだということですが、そのような二枚舌のようなことをおっしゃるようなことは私はあってはならないと思いますし、こういう不誠実な対応を重ねているこの事業についても、やはりこれはしっかりと見直してもらいたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":252,"id":"exchange-089"},{"speaker":"筒井委員","kind":"確認","question":"ちょっと確認なのですけれども、先ほどご答弁で旧東海道から出ることしか想定していないということなのですけれども、国道１５号からは右折できないということなのですよね。国道１５号から取付道路、それを確認します。","respondent":"東野まちづくり立体化担当課長","answer":"国道のところにつきましては、真ん中のところが抜けられない形になりますので、右折はできません。左折インで、左折アウトで出ていくという形になります。","voiceIndex":253,"id":"exchange-090"},{"speaker":"筒井委員","kind":"質問","question":"第１のルートとして、北品川の北から旧東海道を南に下がっていって右折して、さらに右折して第一京浜に出るということぐらいしかないのかと思うのですけれども、なかなかそういう距離は短くてどこまで効用があるのかと思いますし、あと考えられるのは、品川浦のほうから都営アパートとかあのあたりから来て、それで第一京浜に抜けるということを想定されているのですか。","respondent":"東野まちづくり立体化担当課長","answer":"今、委員がおっしゃったように、国道側からは北側から入るものを想定しております。なお八ッ山通り側から入る車につきましても、ちょうどこの取付道路部分と書いてある部分を抜けていくというところも想定しています。","voiceIndex":255,"id":"exchange-091"},{"speaker":"筒井委員","kind":"質問","question":"それがどれだけ交通需要があるのかということと、あと旧東海道もそのまま入っていって、南に下る方もやはり増えるかとお思いでしょうか。その場合旧東海道はかなり狭いので、歩行者の通行安全上、ちょっとどうなのかなという危惧もありますけれども、そういう安全性についてはどのようにお考えなのでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"その交通量を北側のこの部分で国道側へ逃がしていくといいますか、そういう効果もあると考えていますので、旧東海道へ直接行くような交通量というのは、この道路をつくることによって若干減るのではないかという予測をしています。","voiceIndex":257,"id":"exchange-092"},{"speaker":"筒井委員","kind":"質問・要望","question":"だったら最初から旧東海道は入ってこないのかなという感じもありますけれども、いずれにしましても本当にこの道路が区にとって意味があるもの、必要なものということをしっかりとこのあたりの地権者の方とか近隣住民の方に説明していく必要があると思いますので、その点、どうかよろしくお願い申し上げます。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":259,"id":"exchange-093"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"いろいろな質問の中でいろいろなご答弁が出ているので、私なりの質問で同じ答弁になるかもしれないですけれども、お答えいただきたいと思います。高架化に関してなのですけれども、３カ所踏切が解消されるということですが、３カ所解消することによってどういうメリットがまず生まれるかとお考えか。逆に言えばもう大田区まで含めて立体になるのかどうなのかというのをまず１点お願いします。","respondent":"東野まちづくり立体化担当課長","answer":"踏切等と電車が交錯しないという部分では、安全な通行が可能となるという部分があります。それから、品川区内につきましては、京急線につきましては全て高架になるという形になります。","voiceIndex":260,"id":"exchange-094"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"これはこういう請願が上がってきているということですから、地域の声をしっかりと聞いて、どのような方向性が一番ベストなのかというのを、もちろん既存の今やられている考えもあろうかと思いますが、幅広くやっていただきたいと思います。次が広場に関して、さまざまもういろいろ質問が出てかぶってしまう部分があろうかと思いますが、普通単純に考えて、この必要性が北品川の駅であるのかどうなのか。","respondent":"東野まちづくり立体化担当課長","answer":"こちらは現在の北品川駅の利用者約９,０００人のうち、１％の方がタクシーを使っているというようなデータがあります。そうしますと大体９０人ぐらいという形になるのですけれども、それらの方が絶対にこの部分が必要なのかというような議論になってくるかと思います。","voiceIndex":262,"id":"exchange-095"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"だって品川駅の駅前の高輪口だってそこにあるわけですから。わざわざ歩道橋で国道を渡って向こうに行ってということになるわけじゃないですか。品川方面は電車に乗れば行ける、大体みんなタクシーを夜は使うと思うので、そういうロータリーの必要性というのはどうなのかなと単純に思うのです。だから見直しも含めて、考え方の再考も含めて、お考えがあるかどうかというのをお聞かせください。","respondent":"東野まちづくり立体化担当課長","answer":"委員がおっしゃっている部分は確かにあると思います。国道側につきましては、まず最初国道側での計画ができないかというところで区のほうも考えたものです。","voiceIndex":264,"id":"exchange-096"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"いろいろ検討したと。高架に関して、地下もいろいろ検討したけれども高架という手法をとると。こちらも国道沿いも考えたと。ただ、どうしても引っかかるのがさっき言った部分なので、それがもし技術的に無理なのであれば、もう地域の声をしっかりと聞いていくということしか言えないので、それだけは真摯に受けとめてやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":266,"id":"exchange-097"},{"speaker":"安藤委員","kind":"質問・要望","question":"というのはきちんとそこら辺は協議をしました。その結果、だめだと言われたのかどうかというのを確認したいというのが１つ。ですからなぜここだけだめなのかというのがちょっとわからないのです。ですから、何をもってここにバスベイができないと判断しているのか、そこら辺をきちんと伺わせていただきたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"品川区としても、その計画につきましてはまた別の案として、今現在の計画を立てたという形になってあります。","voiceIndex":267,"id":"exchange-098"},{"speaker":"安藤委員","kind":"質問","question":"最初国道側にも考えたのだけれども、つくれないと言われたからこういう計画を考えたということの時系列なのかと思いましたけれども、つくれないと言われたと言いますけれども、何でつくれないと言われたのですか。品川区がそこにつくろうという考えがないからではないのですか。","respondent":"東野まちづくり立体化担当課長","answer":"言われた内容といたしましては、交差点から３０ｍ以上離さないと、ベイみたいな形のものは切れないと言われております。そこに先ほどのロータリー形式のものが配置できるかというような計画を立てた時に、それがかなわない計画であったというものです。","voiceIndex":269,"id":"exchange-099"},{"speaker":"安藤委員","kind":"質問","question":"だから別にこれは金科玉条というわけではないのではないかというのが、原則そうかもしれないけれども、だめではないのではないですかというのを１点お伺いします。ロータリーをつくる必要はないわけであって、国道側にバスベイができればそういう問題はなくなる面があるわけですから、私は別にロータリーをという話を聞いたわけではないので、そこら辺はどうなのでしょうか、伺います。","respondent":"東野まちづくり立体化担当課長","answer":"こちらの計画につきましては、さまざまな検討をした結果として、ここに配置を考えたものです。","voiceIndex":271,"id":"exchange-100"},{"speaker":"安藤委員","kind":"質問・要望","question":"本日結論を出すで、趣旨採択で行きたいのですけれども、やはりあらゆる方法で立ち退きがない状態で、高架ができる方策を考えていくということは大事だと思いますので、ぜひそこを最後まで努力をしていただきたいと思っていますので、趣旨採択を主張いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":277,"id":"exchange-101"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"本日結論を出すで、不採択ということでお願いします。ただ、先ほど申し上げたように、しっかりと地域の声を聞いていただきたい。言っていることが心に響いているか私はわからないですけれども、これは本当に地域の話をしっかり聞いてやっていただきたいというのが大前提です。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":278,"id":"exchange-102"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出していただきたいですが、不採択ではあるのですが、高架化に関しては推進をしていきたいと思うのです。この後も補償問題などが出てくると思うのですけれども、それについても十分に話し合って、もうできる限りのことをやっていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":279,"id":"exchange-103"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、採択でお願いしたいのですが、やはり景観も壊し、住民を立ち退かせるという計画でありまして、なおかつ質疑の最後のほうではその必要性も乏しい計画で、区の判断は、やはり東側のほうに広場をつくることありきということで進めているというところも感じとれましたので、これは採択すべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":286,"id":"exchange-104"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"結論を出すで、不採択ですが、いろいろご努力でいろいろな方法を考えた結果だと思っていますが、いまだにちょっとロータリーに関しては引っかかっている部分もあるので、その辺も含めて今後の動向、地域との話し合いもあろうかと思います。真摯に受けとめていただいて、できる限り区民の要望に沿えるような形でやっていただきたいと、もう見守るだけです。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":287,"id":"exchange-105"},{"speaker":"西本委員","kind":"質問・要望","question":"私のほうとしては、本来は継続して審議をしていただきたいという思いがありました。というのは、まだまだ不十分であるということもあったので、これからの経緯をきちんとこの委員会でも報告を受け、議論する必要があるかなと思ったので継続といたしましたが、否決されましたので、趣旨採択ということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":292,"id":"exchange-106"},{"speaker":"安藤委員","kind":"意見","question":"この内容は本当にもう採択すべきものだとは認識しているのですが、趣旨採択だというご意見の方も複数いらっしゃいますので、やはり少しでも前に進めたいという思いもありますので、趣旨採択に変えします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":294,"id":"exchange-107"}]},{"id":"topic-06","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"今の所長の訂正をお願いしたいのですけれども、積み上げられていた「ごみ」を収集したと。タオルはこれはごみではないので、ごみだったらこれは専決処分はしなくていい、損害賠償しなくていいわけで、ごみではないので、そこのところはちょっと訂正していただきたいと思います。","respondent":"工藤品川区清掃事務所長","answer":"大変申し訳ございませんでした。積み上げられています「ごみ」と私のほうは説明いたしましたが、積み上げられているタオルです。大変失礼いたしました。","voiceIndex":300,"id":"exchange-108"},{"speaker":"西本委員","kind":"質問・要望","question":"これは間違ったということで、こういうふうに間違うものもあるなと。その際に、やはり住民側にも区別をちゃんとしてもらいたいと思うのです。なので、おわびを多分されていたと思うのですが、やはりそこは言い方も難しいとは思いますけれども、ご配慮いただきたいということと、間違えましたという形で、そこで何かご迷惑をおかけしたのですが、そこはどういうお話をされたのでしょうか。","respondent":"工藤品川区清掃事務所長","answer":"ただ、先ほどご説明いたしましたように、通常ごみを出している場所から隣接したところ、１ｍぐらい奥にビニール袋の中に入ったタオル、私どものほうも本来確認しなくてはいけないものなのですけれども、しっかりと確認しなかったですので。","voiceIndex":303,"id":"exchange-109"},{"speaker":"西本委員","kind":"質問・要望","question":"今後のことがあるので、多分同じことが起きる可能性もあるなと思っているのです。ただ、いちいちここはどうだったかと聞くのもなかなか大変だと思うので、できれば広報の中で、そういうものとはちょっと区別していただくようにという注意を喚起するようなことも必要なのかなと。同じことを繰り返さないようにと思っているのですが、何かその辺の工夫をぜひお願いしたいと考えていますので、意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":305,"id":"exchange-110"}]},{"id":"topic-07","title":"の(2) 品川区景観計画における「武蔵小山駅周辺地区」重点地区指定","agenda":"の(2) 品川区景観計画における「武蔵小山駅周辺地区」重点地区指定","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"変更点があったということですけれども、Ａ地区はセットバックが前回は０.５ｍ以上の後退ということになっていたのですが、努力義務になったということなのですけれども、現在の表現だとしてもセットバックをしない場合、景観計画上の区の届出ですとか、景観審議会の意見聴取の過程などで、建築確認が下りないなどの事態が発生する可能性はあるのでしょうか。","respondent":"中村都市計画課長","answer":"こういったところは店舗の壁面を後退するだけで、そこの利用の仕方についても、店舗の方、事業者の方が任意に使っていただけるですので、税の優遇は考えてございません。","voiceIndex":312,"id":"exchange-111"},{"speaker":"安藤委員","kind":"質問","question":"それと、景観法第９条では、景観行政団体が計画を定めようとするときは、あらかじめ公聴会の開催と、住民の意見を反映させるために必要な措置を講ずると書いているのですが、今回、一部計画案と変更になった点もあるわけですが、全地権者や商売人の方への意見聴取、アンケートなども含めて、どういう意見を反映するための努力をしたのか、そこら辺を伺います。","respondent":"中村都市計画課長","answer":"パブリックコメントという観点からは、区内の不特定の方からのご意見も寄せられたです。そのような中で、説明会の意見も反映して、こういった５０ｃｍの後退の努力義務ですとか、こういったところを可能な限り反映をさせて、地域の皆様方と一緒にここまで来たです。","voiceIndex":314,"id":"exchange-112"},{"speaker":"安藤委員","kind":"質問・要望","question":"ただ、説明会の過程の中でいろいろ意見を聞いて、少し修正をしたというのは、それはそれで大事な点ではないかと思いますので、今後にもぜひ活かしていただきたいと思います。高層化を誘導する方針になっているのではないかと思うのですけれども、これはちょっと問題ではないかと思うのですけれども、どうなのでしょうか。修正すべきなのではないかとは思っているのですが、区の考えを伺います。","respondent":"中村都市計画課長","answer":"むしろ抑えるほうの考え方に近いのかなと思いますが、いずれにいたしましても周囲とのバランスというところでございまして、それは決して高層化を助長して、望まない事業主に高層化を促すとかいうものではございません。","voiceIndex":316,"id":"exchange-113"},{"speaker":"安藤委員","kind":"質問","question":"やはりさっき言ったように誘導指針を踏まえてとなりますと、必然的にその誘導指針にある都市像を踏まえてくださいとなると思うので、私はちょっと今の説明では、強制力はないにしても、どちらかというと高層化を誘導する方向になっていくのではないかというふうにしか見えないのでけれども、それをそうではないと言う根拠は何かあるのですか。そこら辺はいかがでしょうか。","respondent":"中村都市計画課長","answer":"このスカイラインの調和のところで、当然これを理由に区が高層化を迫るということは現実的には今までもありませんし、これからもそういったことは非常に考えにくいと思います。ただ、少なくともやはりここに書いてるとおりですが、調和を図るという以外に他意はございません。","voiceIndex":318,"id":"exchange-114"},{"speaker":"安藤委員","kind":"質問・要望","question":"他意はないということなので、だったらここに入れる必要はないのではないかと私は思うのですけれども、ぜひこれで高層化を誘導するふうな手立てをしないでほしいとうことを要望したいです。ですから、景観というのであれば、やはりどこかにありましたけれども、パブリックコメントのご意見等というところにも出ていますけれども、やはり下町的地域だと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":320,"id":"exchange-115"},{"speaker":"西本委員","kind":"確認","question":"もう一度確認です。６月１日施行ということなのですけれども、今建築中とか、これから近々に建て替えるとかいう方々はどのような状況になるのでしょうかというのと、それから、現在合致していない店舗というのはどのぐらいあるのでしょうか。","respondent":"中村都市計画課長","answer":"６月１日施行までの間に、地域の皆様方にも十分周知をするということで、いろいろなパンフレットを配布したりですとかいったところも考えておりますけれども、この工事に着工するというところが一つの境になりますが、この辺は周知をして混乱のないようにしたいと考えています。","voiceIndex":321,"id":"exchange-116"},{"speaker":"西本委員","kind":"確認","question":"それでもう少し聞きたいのが、もうちょっと工夫していきたいみたいなものについての自由度というのは、割と相談するという形で許容範囲が広がってくるのか、ただ、それぞれの店舗が必ず建築確認を取るという形でやっていくということになるのか、勝手にやってしまって、いや、いいと思って改築しましたみたいになってしまうのもいけないと思うのですが。","respondent":"中村都市計画課長","answer":"そういった中で、具体的な基準としては、ショッキングな色ですとか、そういったものを使わない限り、おおよそ周りとは調和するのかなと考えておりますので、よほどの特異なデザインでなければ、その範囲の中でご相談を承っていくということになります。","voiceIndex":323,"id":"exchange-117"},{"speaker":"西本委員","kind":"質問・要望","question":"やはりある程度の自由度を持った形で相談を受けていただきたいと思うのです。同じということはないと思いますが、やはり同じだとおもしろ味がなくなってしまうということもあるので、そこはある程度許容範囲を広げながら、この新しい商店街、新しい一つの統一もありながらも特徴がありつつという形でのおもしろい地域になっていただいたらいいと考えていますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":325,"id":"exchange-118"},{"speaker":"新妻委員","kind":"質問","question":"それともう一点は、こういうふうに規制をすることで、今武蔵小山もお店が変わって、かなり一時期よりも本当にきれいに整備されてきていると思うのですけれども、例えばこういう規制をすることで、うちはここまできれいにできないから、出ていかなくてはというようなことにならないようにするべきだと思うのですけれども、そこら辺はいかがでしょうか。","respondent":"中村都市計画課長","answer":"ただ、その時には塗装をしたりですとか、あるいは少し外観をいじったりというものを工事費をかけてやろうという事業主のために届出をいただいて、相談をしていただくということになりますので、その中で例えば塗装が変な色を使うとか、使ってもいい色でも。","voiceIndex":326,"id":"exchange-119"},{"speaker":"新妻委員","kind":"質問","question":"わかりました。それならば、当然専門家の方がアドバイスをしていただくということでよろしいのでしょうか。それと、何か例えば手を加えたいということで、商店街に対してのリフォームするにあたっての助成金とか、そういうのはあるのですか。個々の店舗にですね。","respondent":"中村都市計画課長","answer":"これは一定程度景観のまちづくりが進んだ中で、武蔵小山の方針としてはこういうものがやはりいいよねというのがだんだん固まってくると、その方針に向けて改装をしていただいた場合に補助金が出るというような方向性を決めることができますので。","voiceIndex":328,"id":"exchange-120"},{"speaker":"いながわ副委員長","kind":"質問","question":"そうなった時に、この説明というのは、あれだけ大きな商店街ですからやはりある程度のルールは必要だと思うのですけれども、例えば不動産屋でここがいい物件だから借りますと言って賃貸借契約してから、実を言うとこういうルールがあるので、看板はこういう規制がありますよと気づいてからまた解約するとなるとまたいろいろ大変になってくると思うのですけれども、この説明をする方は。","respondent":"中村都市計画課長","answer":"不動産屋が仲介をした場合に、仲介してそのお店に入る時に、もうすぐにリフォームをして入る方とか、あるいはまずはそこをそのまま使ってしばらくしてリフォームする方、いろいろな形態があると思いますけれども、いずれにしましても不動産の売買ですとか賃貸ですとか。","voiceIndex":330,"id":"exchange-121"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"要は西側にもアーケードがあるし、ちょっと行くと一番街の商店街、これはパルム商店街から派生しているというかパルム商店街から伸びている商店街なのですけれども、そういったところに対して、パルム商店街が盛り上がるのはいいのですけれども、横にも商店街があるということをお忘れなきようにという思いがあるのですけれども、ちょっと内容とは離れていますけれども、そこに対しては今後何か。","respondent":"中村都市計画課長","answer":"パルム商店街のこのアーケードのかかっている部分だけではなくて、ほかもパルム商店街という認識でおりますけれども、今回重点地区をかけるところを足がかりにして、広げていければと考えています。","voiceIndex":332,"id":"exchange-122"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"わかりました。品川区においてもこれが全て完成すると、本当に品川区内の一つのランドマークがまた新たにできるわけであって、やはりここを中心として、また荏原地区が活性化するようにしていっていただきたいので、残された商店街もしっかりとコーディネートしていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":334,"id":"exchange-123"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4224#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":85561,"voices":339}},{"id":"h30-20180226-9","meetingId":"h30-cm02","date":"2018年2月26日","dateIso":"2018-02-26","committee":"文教委員会","time":"午前１０時００分～午後 ２時３１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を69件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第１５号議案 品川区奨学金貸付条例の一部を改正する条例","agenda":"第１５号議案 品川区奨学金貸付条例の一部を改正する条例","exchanges":[{"speaker":"渡部委員","kind":"質問","question":"説明を伺いました。逆を言うと、品川区民のうち、どれぐらいの高校生が対象者となるのかどうかをしっかり教えてください。まして、４月１日から始まるということで、１カ月後にはスタートするわけなのですけれども、そうなったときに、例えば応募が殺到するようなことが万が一あった場合には、現状の体制ではいかないと思うのですが、その辺はどのような体制を組まれるのか。あわせてお願いします。","respondent":"廣田子ども家庭支援課長","answer":"所得制限につきましては、国で実施しております就学支援金の制度、都で実施しております授業料の軽減制度と同じ方式で計算する所得制限に変更しようと考えております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"渡部委員","kind":"質問・要望","question":"予算を超えた場合については要望になりますが、公平性の担保を考えたり、必要な人が借りにこられるわけですから、返還免除があるなしとは別に、そこはしっかり貸していただきたいと思います。ですから、そこに関して、しっかり入り口、出口というのを、ある程度、固まってきているのでしょうけれども、短い時間ですが、誰もが納得すような規則にぜひしていただきたいと思います。","respondent":"つる委員長","answer":"正副で調整します。","voiceIndex":9,"id":"exchange-002"},{"speaker":"渡部委員","kind":"質問・要望","question":"周知です。漏れることのないよう周知を徹底していただきたい。これが次年度以降になるのであれば、例えばそういうパンフレットをつくって公立中学校の生徒全員に配ればいいのですが、今回に関しては、スタートが今年度ですから、丁寧に周知、告知をされる方法を考えていただきたいと思います。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"条例の中に、返還金免除について基準を定めると書いてありますけれども、既に定められているのか確認をさせていただきたいと思います。それから、免除条件として校長の推薦書や地域活動等の実績が必要とご説明がありましたけれども、これは必須になってくるのかどうかもあわせて伺いたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"返還免除の方向性としては、推薦書の内容だけでなく、区内の地域活動等、さまざまなプラスポイントが設けられる形をつくろうという方向で検討をしていますが、細かい基準等につきましては、募集を４月１日以降にもうかけなければならないので、方向性が決まりましたら。","voiceIndex":12,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"運用してみないと、そういったところもわからないと思うのですが、柔軟な対応を求めたいと思います。それから、推薦書というのは、より優秀、トップクラスでないと受けられないのか伺いたいと思います。あるいは、入学準備金として、保護者への貸付を今まで行ってきましたけれども、それが変わるのかどうかも伺いたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"先ほどもご説明したのですけれども、給付の制度が受けられるひとり親であるとか、一般の両親がそろっている低所得の家庭であったり、所得がある一定程度、上の方には受けられない給付の制度がある場合には、併用ができないわけではないのですけれども。","voiceIndex":14,"id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"しかし、本来的に、負担を軽くするということであれば、給付制に踏み出すべきだと思いますので、その実施も検討していただければと思いますけれども、いかがでしょうか。保護者への貸付というのは、奨学金制度の趣旨に反するものですけれども、ほかに増額もされ、運用しやすくなるということで、賛成していきたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"給付につきましては、当初の検討から、品川区としては考えておりません。返還免除については、誰でも返還免除になる制度ではございません。","voiceIndex":16,"id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"当初から給付制については考えていないということ、また、ばらまきだという話もありましたが、教育の機会を保障するというところで、経済的な理由で受けられないことがないように、給付制が必要だと考えています。先ほど予算をオーバーした場合も、今後、検討していくということでしたので、ぜひ、多くの学生がこの制度を受けられるように、柔軟に対応していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-007"},{"speaker":"こんの委員","kind":"確認","question":"確認ですが、そもそも、今、議論になっています、返還免除制度の導入に至った目的はここに書いてあるのですけれども、どういう家庭またはその状態を想定されて、こういう制度の導入を決めたのか。区がどういった認識から、この条例改正に至ったところをもう一度、確認をさせてください。","respondent":"廣田子ども家庭支援課長","answer":"それを少しでも超えてしまうと、給付等が全くないので、ある一定程度の収入要件は設けますが、非課税世帯、その上の中間層の方にも、生活の中で、子どもが学業ができるほど楽にはなっていない部分もあると思いますので。","voiceIndex":19,"id":"exchange-008"},{"speaker":"こんの委員","kind":"質問・要望","question":"いろいろとこれから要件をきちんと整理されていくところで、今、おっしゃった生活保護世帯やひとり親世帯の方が現時点で受けられる制度の上に、もう一つ、こうした制度があるということなので、この制度を活用したいというお子さんの希望ができるだけかなえられるよう、申し込みの時点でもきちんと聞き取っていただきながら、制度の趣旨にかなう使い方をきちんとしていただきたいと考えますが。","respondent":"廣田子ども家庭支援課長","answer":"申し込みの際には公平性も考えまして、非常に難しいところなので、難航しているところではあるのですけれども、収入要件だけではなく、さまざまな本人のやる気や将来の夢が叶うように、限りがある予算なので、どこまで行けるかわかりませんが。","voiceIndex":21,"id":"exchange-009"},{"speaker":"松永委員","kind":"質問・要望","question":"必要額と言っていましたので、例えば１０万１,５００円というような細かいところまで書かないといけないのか。その辺を詳しく教えていただきたいと思います。ここに区内等地域活動ということがありまして、これは、例えば月に何回、地域の活動をしましたとか、年間通してこれだけやりましたとか、１度やったことがあるとか、具体例が決まっておりましたら、ご説明いただきたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"入学準備金ですけれども、近隣校に調査を行いまして、私立校だと、アンケートによると２２万円から１１０万円まで、かなり幅があるのですが、入学金、施設費、制服代など、平均が４９万円と出ているので、かなり差がある認識があります。","voiceIndex":23,"id":"exchange-010"},{"speaker":"松永委員","kind":"質問・要望","question":"この選択制に関しては、１万円単位と理解をいたしました。区内の地域活動に関してですけれども、まだ検討段階ということなのですが、町会長等にも負担がかかるということだったのですけれども、例えば防災訓練の参加はとても大事だし、いろいろ町会でやられている行事に、今、地域の行事に参加するようにと促している中で、そうしたところも必要ではないかと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"私の質問も地域活動のところで、今までの委員とダブるところがあると思うのですけれども、これを導入する理由を改めて伺いたいと思うのです。ただ、地域活動を免除要件とした理由がどういうことかを伺って判断したいと考えていますので、教えていただきたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"地域活動を免除要件とした理由ですけれども、公費を使うわけですので、返還免除をする場合に地域に貢献できる内容についても導入しないと、地域の方、一般の区民の方のご理解が受けられないのではないかという考えが１つです。","voiceIndex":26,"id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"突出するところがない子のモチベーションが上がらない云々かんぬんという説明でしたけれども、私は、先ほど申し上げたように、校長先生が成績出欠状況も含めて総合的にその子どもをどう見ておられるか。だから、一定程度、その子どものＡさんならＡさんの総合的な評価は出てくると思うのです。そういう点でどう考えるかを伺いたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"スポーツでかなり上のレベルを目指しているお子さんがボランティア活動、地域の活動をできないのはこちらも重々わかりますので、そういうことではなくて、普通に修学旅行に行きたいですという理由で、そのお金を借りにきた子は、修学旅行に行って目標達成というのはないので。","voiceIndex":28,"id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"この学校の３年間の生活は、この子どもたちにとってとてもよかったのだ、一生懸命、頑張ったのだ、先生との関係もよく見れるし、本当にそういう気持ちを持って、みんな卒業していく。重く受けとめると思います。だから、加点というのであれば、それこそ総合的に判断されて、こういう括弧書きにしているところを「等」とすることがなぜできないのですか。そこがわかりません。","respondent":"廣田子ども家庭支援課長","answer":"審査にあたっても、一人ひとり、面接を予定していますし、貸し付けるにあたって、親御さんとお子さんには、貸し付けをする前にしっかり何をやりたいかをはっきり押さえていかないと、返還免除を申請したときに、その子が何を頑張ったのかがわからなくなります。","voiceIndex":30,"id":"exchange-014"},{"speaker":"南委員","kind":"質問","question":"そういうことが結果的に伝わらないのであれば、それは区の面接のときの対応がどうだったのかということになると思うし、一人ひとりにきちんと親子で面接をするという場を踏んでから貸し付けるわけですから、その場面で、いいかげんな態度ではだめということをきちんと伝えればいい話で、活動状況等々についても見るということは口頭で述べていけばよく。","respondent":"廣田子ども家庭支援課長","answer":"６０万円の金額につきましては、費用の中で、今までの金額と、修学旅行について一番高く設定された学校が３０万円だったので、最低でも修学旅行には行ける金額が設定しないといけない金額なので、返還免除制度があるとはいえ、あくまでも貸し付けなので。","voiceIndex":32,"id":"exchange-015"},{"speaker":"南委員","kind":"意見","question":"当然、そういう審査会の議論も含めて、こういう形になったということは承知しているつもりなのですけれども、修学旅行だとかクラブ活動にかなりのお金がかかる。修学旅行は、特に最高で３０万円かかっている学校があるということも含めて、この金額が導き出されたのは、そういうことで理解できると思います。そこが非常に心配するところです。そういう意見を付しておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":34,"id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"質問","question":"幾つかお聞きします。１つ目は、在学応援資金は３０万円掛ける２０人で、当初予算を計上していますが、何人の方が返還免除とするのかはまだ決まっていないということでよろしいのか。それから、もう一つは、もう高校入学が迫っているわけで、議会で議決されるのがギリギリなのですが、具体的な周知方法について、先ほどちょっとお話があったのですが、教えていただければと思います。","respondent":"廣田子ども家庭支援課長","answer":"今、平成３０年度４月に入学する子のうち貸付の予約生になっているお子さんに関しては把握していますので、その方には個別に新制度についてご説明をするつもりです。","voiceIndex":35,"id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"確認","question":"何らかの形で周知する方法がないかと思って、なかなかいいアイデアがないのですが、どうでしょうか。今、高校にいる子も(2)、(3)の対象となるわけですよね。そこを確認です。それから、中学校だと、そういった状況の生徒を把握している先生もいらっしゃるのではないかと思うのですが、そういったところと協力できればいいと思うのですが、その辺はいかがでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"現在の高校１年生、２年生につきましても、入学準備金以外は貸し付けを受けることは可能です。周知の方法については、まだ具体的に詰め切れていないので、委員のご提案も含めまして、これから検討したいと思います。","voiceIndex":37,"id":"exchange-018"},{"speaker":"南委員","kind":"意見","question":"先ほども質疑の中で申し上げましたが、地域活動を条件に入れることについては問題があると考えていますけれども、安心して修学ができる、そういう経済的な支援であること、そして、条件はつきながらも免除制度が創設されましたので、賛成をしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-019"}]},{"id":"topic-02","title":"正する条例、(4)第１８号議案 品川区私立認定こども園、私立幼稚園および特定地域型保育事業の利用者負担額に関する条例の一部を改正する条例および(5)第３４号議案","agenda":"正する条例、(4)第１８号議案 品川区私立認定こども園、私立幼稚園および特定地域型保育事業の利用者負担額に関する条例の一部を改正する条例および(5)第３４号議案","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今、ご説明がありました保育料の所得割の計算方法の変更ですが、この対象者は何人ぐらいいるのかということと、この変更で負担増になる人はいるのかも伺いたいと思います。あわせて、多子軽減の対象拡大ですが、居宅訪問型児童発達支援が制度上、新設されるということで、品川区には該当施設があるのか、または、できる方向性があるのかも伺いたいと思います。","respondent":"佐藤保育課長、吉田保育施設調整担当課長","answer":"当面の間できる予定はないと所管から聞いていますので、(2)に関しましては、影響する方は今のところ見込めないところです。２番目のご質問の負担増になる方はいらっしゃいません。就学前乳幼児教育施設、ぷりすくーる西五反田の該当者ですけれども、所得割軽減に対する該当者はございません。","voiceIndex":51,"id":"exchange-020"}]},{"id":"topic-03","title":"第３５号議案 幼稚園教育職員の給与に関する条例の一部を改正する条例、(7)第３６号議案 学校教育職員の給与に関する条例の一部を改正する条例","agenda":"第３５号議案 幼稚園教育職員の給与に関する条例の一部を改正する条例、(7)第３６号議案 学校教育職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"これは労使で妥結していることだと思いますけれども、幾つか聞きたいと思います。今回、扶養手当が変わるということで、この影響なのですけれども、増える人と減る人がそれぞれ何人ぐらいいるのか伺いたいと思います。それから、ひとり親の家庭の方、欠配一子の額が今まで１万３,７００円だったのが９,０００円に下がるということで、この部分が廃止となる理由について伺いたいと思います。","respondent":"熊谷指導課長","answer":"１点目ですけれども、増える人と減る人といった影響です。","voiceIndex":86,"id":"exchange-021"},{"speaker":"のだて委員","kind":"質問・要望","question":"影響のある方は１３名いらっしゃるということと、一概に増える、減るということは言えないということでしたけれども、全体としては、この手当額は変わらないことになるのでしょうか。そこのところを確認させていただきたいと思います。","respondent":"熊谷指導課長","answer":"ですので、全体としてどうかというと、変わらない方が２名、そして、８名が増える状況で、全体としてどうこうと一概には言えないのですけれども、そういう状況にあります。","voiceIndex":88,"id":"exchange-022"}]},{"id":"topic-04","title":"第３９号議案 指定管理者の指定についておよび(9)第４０号議案 指定管理者の指定","agenda":"第３９号議案 指定管理者の指定についておよび(9)第４０号議案 指定管理者の指定","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今回、公募型プロポーザで２つの事業者が選定されたということですが、この選定にあたり利用者や専門家の声を反映する必要があると思うのです。こういった選定時に利用者、専門家の意見を聞かなかった理由について、また聞いていれば聞いた内容を載せていただきたいと思いますが、聞かなかったということであれば、その理由を伺いたいと思います。","respondent":"横山品川図書館長","answer":"それと言いますのも、指定管理の運営にあたりましては、半年ごとにモニタリングおよびアンケート調査を行っておりまして、反応を確認しながら運営を進めてまいりました。第２期におきましても、その成果を評価基準に反映する形で評価をさせていただいているところです。","voiceIndex":108,"id":"exchange-023"},{"speaker":"のだて委員","kind":"質問","question":"モニタリングで間接的に意見を聞いているということでしたけれども、モニタリングで利用者の声を聞いていた記憶が私はないのですが、どのようにそれで反映されているのかを伺いたいと思います。","respondent":"横山品川図書館長","answer":"その結果、２グループと１グループの請負をする事業者が分かれた形になってあります。","voiceIndex":110,"id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"そのことを要望しておきますので、ぜひご検討いただければと思います。それと、この選定の中で、今回、この２つのグループになったということですけれども、その応募の件数は何件ぐらいあって、ほかの運営事業者はどういったところがあったのかも伺えればと思います。","respondent":"横山品川図書館長","answer":"応募の内訳なのですが、Ａ、Ｂ、ＣともにしながわＴＲＣ・リディアグループ、また、日本コンベンションサービスが全てに応募しています。Ｂグループの４事業者の残りの２つにつきましては、丸善雄松堂株式会社および株式会社ヴィアックスです。","voiceIndex":112,"id":"exchange-025"},{"speaker":"のだて委員","kind":"提案","question":"今回、評価が突出して株式会社ヴィアックスが高かった、しながわＴＲＣ・リディアグループも評価が高かったということなのですが、地域特性に見合った提案ですとか、多くの職員による質の高い図書館サービス、また、提案内容が具体的ということが書いてあるのですけれども、もう少し、この事業者が一番よかったのかについてご説明いただきたいと思います。","respondent":"横山品川図書館長","answer":"Ｂグループ、株式会社ヴィアックスの選定理由につきましては、それぞれＢグループの皆さんは、３図書館について、地域の特性であるとか図書館の位置付け、また、そこの図書館の地域性に合った新しい事業の提案をいただいております。","voiceIndex":114,"id":"exchange-026"},{"speaker":"のだて委員","kind":"質問","question":"ある方からお聞きしますと、毎回、行くと人がかわっているというお話も聞いております。地域の文化的側面を図書館は支えていくものだと思いますので、その地域に合った選書ですとか、イベントもいろいろやっていくのだと思いますけれども、そういったことをやっていくには地域に根差した人員配置、職員が長く働き続けていけることが重要だと思いますけれども、いかがでしょうか。","respondent":"横山品川図書館長","answer":"スタッフを長くとどめられるかという点につきましては、人を直接雇用する関係ではなく、指定管理につきましては、ご提案をいただいて運営をお願いする立場ですので、区がとどめることはできません。","voiceIndex":116,"id":"exchange-027"},{"speaker":"のだて委員","kind":"質問","question":"直接雇用ではないので、区としては長くいてもらうことはできないというお話でしたけれども、実際には、職員がころころかわっている状況だと聞いております。そもそも図書館が教育機関として位置づけられており、利用者の資料収集とか情報収集、知りたいという願いに応えるためにあるわけです。この意図は何だと思っていらっしゃるか、区はそぐわないと考えないのか、伺いたいと思います。","respondent":"横山品川図書館長","answer":"今、委員からご指摘がありました、長く勤めないと図書館のサービスが保たれないという点につきましては、先ほどご説明しましたように、指定管理者が行っていることを常に品川図書館の職員が評価し、管理をする形をとって、よりよいサービスに努めてあります。","voiceIndex":118,"id":"exchange-028"},{"speaker":"のだて委員","kind":"意見","question":"公務員だと異動してしまって長く勤められないというお話もありましたけれども、それは委託をしているせいで、１０館には区の職員がいない。１１館もあれば、異動しても次の図書館に移ることも考えられるわけです。そういったところで経験を積んで、さらによくしていくことは区の職員でもできると思います。そういったところが、区民へのサービス低下にもつながってきているのではないかと思います。","respondent":"横山品川図書館長","answer":"区の職員につきましては、３年から５年のスパンで異動となり、同じ職場にまた戻るのは割と例外的な形になりますので、職員での経験の積み上げよりは、図書館専門である事業者のほうがむしろ経験の積み上げは大きいものだと考えております。","voiceIndex":120,"id":"exchange-029"},{"speaker":"のだて委員","kind":"質問","question":"あわせて、働き続けるという面で、総務省が２０１５年に調査をした資料ですと、品川区の指定管理のチェック項目の中で、法令遵守をしているかどうかというところに、ほかのところでは丸がついていないが、図書館のところでは選定時に示している、評定に記載しているというところに丸がついております。こういったところでは、どういった基準になっているのか伺いたいと思います。","respondent":"横山品川図書館長","answer":"先ほどの質問に戻りますが、事業者の欠員という考え方なのですが、指定管理におきまして、応募のときに何人というような基準で公募するという形はとっておりません。","voiceIndex":122,"id":"exchange-030"},{"speaker":"のだて委員","kind":"意見","question":"欠員のところですけれども、何人という募集はしていないというお話ですが、私がお話を聞いたところでは、もともと２人いたところが１人になるとか、そういった状況から欠員になっていると聞いております。全体の中で必要な人数を把握されているといったところとは、ちょっと違うと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":124,"id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"先ほども申したように、品川区の事業を受けているのですから、これから始まる長期基本計画の改訂に向けた作業が各部署で行われていますけれども、そういう改訂にあたって、図書館事業が指定管理者の方々にどういう意見を伺って反映しようとしているのか。あるいは、幼稚園、保育園および病院などへの連携、それらが今までとどう違うのか、向上したのか、そのあたりについても伺いたいと思います。","respondent":"横山品川図書館長","answer":"指定管理が事業になじまないという点につきましては、先ほどご説明させていただきましたとおり、指定管理の事業に関して、区の職員が直接モニタリングを日々行いながら、お互いの協力の中でサービスの質の向上を図ってあります。","voiceIndex":125,"id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"本が好きで応募をして職員になる、そういう方々なのだという先ほどの説明もあったわけですから、司書資格を持つ人を積極的に採用して、誰が窓口に来ても、誰がレファレンスを担当するにしても、きちんとした職責を果たせる、住民の要求にきちんと応えられる、そういう対応が求められるし、だからこそ資格が必要なのだと私は思いますので、その点について、しっかり伺っておきたいと思います。","respondent":"横山品川図書館長","answer":"モニタリングについてですが、半年ごとに項目を定めて、区民満足の視点でアンケート調査を実施、予算執行の観点で、執行額や執行内容についての調査を行います。","voiceIndex":127,"id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"国会図書館以外が１００％でないからいいではないか、そんなことにはならないではないですか。そんなの関係ない話でしょう。品川区は品川区独自で図書館業務をやっているのですから、国会が少ないから品川区が少なくていいと、品川図書館長は本当にそう思っているのですか。それから、区民に働いてもらっているから司書資格を求めないということも、私は間違っていると思います。そこを伺いたいと思います。","respondent":"横山品川図書館長","answer":"一方で区立図書館については、むしろ気軽に来て、相談をしながら本を選ぶことが多く、中心となる業務というところにつきましては、司書資格があるのがもちろん望ましいですが、実際上、取ることが難しい状況があるということを踏まえ、先ほどご説明させていただきましたように。","voiceIndex":129,"id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、できるだけ司書資格を取得していただけるような働き方を行政としてもしていただきたい。できるだけ地区図書館でも必要な資料収集はして、ずっと継続していただくとともに拡充をしていただきたいということは要望としてお願いしたいと思います。そういう点で、幾ら聞いても、そこはわかりませんので、きちんとそこについては答弁をしていただきたいと思います。","respondent":"横山品川図書館長","answer":"そちらにつきましては、館長会等、全体の会議の中でそれを発表しまして、どうしたらそれを取り入れられるか、この提案については良いから、ぜひ実行しようということで、必ず反映をする形をとってございまして。","voiceIndex":131,"id":"exchange-035"},{"speaker":"南委員","kind":"質問","question":"何回も聞いて、ようやくわかりました。ようやくここまで出てきたので、やはり適切に質問を理解していただいて、適切な答弁をよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":133,"id":"exchange-036"},{"speaker":"渡部委員","kind":"提案","question":"２点目に、前回の指定管理は３年間でしたが、基本的に品川区の指定管理は５年間を目安にしており、今回は５年間にしたということは、３年間の指定管理がうまくいったから、この先は５年間でやっていくという認識でいいのかどうか教えてほしい。そして全部、一括で決まっていたはずです。要は、何が言いたいかというと、２事業者の間で格差が生まれないような仕組みづくりはされているのかを教えてください。","respondent":"横山品川図書館長","answer":"事業を実施するにあたっては、必ず企画書を出していただく形になりますので、いい企画については必ず共有して、取り入れられるところは取り入れる方式をこれからもとっていきたいと思いますので、各グループの連絡を密にし、いいところをさらに伸ばしていく運営方式です。","voiceIndex":134,"id":"exchange-037"}]},{"id":"topic-05","title":"平成３０年請願第７号 認可保育園入園のための制度改善を求める請願","agenda":"平成３０年請願第７号 認可保育園入園のための制度改善を求める請願","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"保護者の方は不安を抱えております。幼稚園についても、第１希望、第２希望とある中で、内定日が第２希望のほうが早い場合、２園分、払わなければならないこともあるとお聞きしております。こういった切実な思いをどう考えていらっしゃるのか。計画していた生活が壊されてしまいますので、そこは小規模もやっておりますし、認証保育所でも連携をやっていくべきなのではないかと思いますが、いかがでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"１次の不承諾者が６４名、そのうち３６名は転園希望を出されていて、不承諾になっている方なので、実数としては２８名です。２８名の方に対して１７３名の枠がありますので、２次で空いている園を希望園の中に入れていただければ、ご心配せずとも認可保育園に入園できる状況です。","voiceIndex":156,"id":"exchange-038"},{"speaker":"のだて委員","kind":"質問","question":"空きとしては３６名の転園希望者を入れても６４名ですから、１７３名で対応できるというお話でしたけれども、昨年、１名の方が待機児童になっています。昨年も１名の方がだめだったというのは、地域でのマッチングの問題もあると思います。そういったところを考えても、来年度については３歳児が確実に入ることができると言えるのでしょうか。伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"数で見ていただくと、確実に入れる枠はあるというご説明をせざるを得なくて、それが確実かと言われると、それは、今、不承諾の方がどの範囲までを、ご自身が通える範囲として設定するかという個人の問題もありますので、そこについては。","voiceIndex":158,"id":"exchange-039"},{"speaker":"のだて委員","kind":"質問","question":"いろいろ個々の状況によって、絶対とは言えないということですけれども、そうなってくると、保護者の皆様は不安になると思うのです。小規模保育事業では連携がある中で、認証保育所では３歳でまた新たに申し込んでいかなければならないので、その負担を軽減していくためにもやっていくべきだと思いますけれども、いかがでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"連携についてですけれども、先ほども申し上げましたように、指数が低い方が入園されている認証保育所において、区外の認証保育所を利用されている方、また、ほかの施設を利用されている方、３歳から入園を希望される方との公平性の観点から。","voiceIndex":160,"id":"exchange-040"},{"speaker":"のだて委員","kind":"質問","question":"ですので、区が今、この連携をやらないということであれば、枠的には入れるという話ですけれども、入れなかった場合に何か手立てを講じなければならないと思いますが、そのお考えはあるのか伺いたいと思います。それを解決していかなければ、保護者の方は仕事を続けられませんし、安心して生活をすることができない、保育を保障していくのが自治体の責任だと思いますけれども、いかがでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"待機児童につきましては、認可保育園の開設を中心にしてまいりますけれども、それだけではなく、認証保育所をはじめとして、さまざまな事業の実施により解決をして、解消をしていきたいと考えております。","voiceIndex":162,"id":"exchange-041"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういったところをしっかりと考えていただいて、入れるようにしていっていただきたいと思います。認可保育園に入りたいということが求められているのだと思います。品川区も待機児ゼロを目指すということでやっておりますので、今年の４月に待機児を出さない、こういった取組みが必要だと思います。認可保育園を希望する方が全て入れるようにしていただきたいと思いますが、いかがですか。","respondent":"大澤待機児童対策担当課長","answer":"待機児童解消につきましては、先ほども申し上げましたが、認可保育園の開設を中心に進めてまいりますけれども、それだけではなく、認証保育所等も含めまして、解消に努めてまいりたいと思っています。","voiceIndex":164,"id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"待機児をゼロにしていくことをしっかりと進めていっていただきたいと思います。先ほどご紹介しました実態調査の中でも、利用していない人の中にも、利用したいけれども空きがないという方が３０.７％いらっしゃるということですので、認可保育園の増設が本当に望まれております。質の担保の面でも、処遇改善をしっかりと進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":166,"id":"exchange-043"},{"speaker":"南委員","kind":"質問","question":"基本的なことを伺いたいのですけれども、認証保育所は今現在、何園あって、２歳までの認証保育所、子どもを受け入れるのは何人か、３歳児から就学前の５歳まで預けることが可能な所は、先ほど１３園とおっしゃっていましたけれども、改めて、そのあたりの数字を伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"区内の認証保育所は２６ヵ所あります。３歳以上も受け入れている所が、先ほど言いましたように、その半数の１３です。２歳までの定員は３０６人になります。","voiceIndex":167,"id":"exchange-044"},{"speaker":"南委員","kind":"質問","question":"全部、定員数も伺えばよかったのですけれども、認証保育所が２６園あって何人の定員枠があるのか。なぜ認可保育園を中心とするようになってきたのか、区の思いも伺えればいいと思っています。それと、先ほどの質疑を伺っていて、今年は定数枠が５２３名、受け入れ枠があるということだったと思うのですけれども、申請数に比べて５２３名あるので、十分、枠はある。その辺も伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"認可保育園を中心にというのは、先ほど委員からもありましたけれども、保護者の方のご希望は認可保育園が一番多いということで、０歳児から５歳児まで同じ園で過ごしたいご希望が多いと考えていますので、認可保育園を中心に進めております。","voiceIndex":169,"id":"exchange-045"},{"speaker":"南委員","kind":"質問・要望","question":"私が伺ったのは、認証保育所を中心にかつては増設してきたけれども、今日では認可保育園が中心になっていると思っているのですが、そこの答弁がなかった。５歳までの認可保育園に通しで入れたい保護者の希望もあるというご説明の中で、そういうことから変更されたと伺ったのですが、改めて、そこは確認をしたいと思うのです。その点について、区の認識を伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"先ほどの２歳までの認証の定員数です。失礼いたしました。４１６名です。","voiceIndex":171,"id":"exchange-046"},{"speaker":"南委員","kind":"質問・要望","question":"今までは厳しかったと思うのです。今年は１歳の枠を広げる努力をされていますけれども、３歳の枠が増えたというのは、区のそれなりの努力もあると思うけれども、２歳までしか預かれないけれども、３歳になっても入れる状況はこれからずっとあるというふうに見ていいのですか。その辺を伺いたいのが２つ目です。そこのところの答弁がなかった気がするので、もう一度、そこを伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"それに対して、本会議でも答弁がありましたけれども、今後も８００人から１,０００人の開設を目指していますので、そこの定員差と新規開設園でこの先も見込んでいけますので、３歳児の枠については確保できてあります。","voiceIndex":175,"id":"exchange-047"},{"speaker":"南委員","kind":"質問・要望","question":"そのあたりをどう見るかということも１つ大事な視点ではないかと思いますし、全ての方に本当に納得していただける、そういう対応をしていくことが大事だと思います。区外の方が２割いらっしゃるという話なのですが、区外の人がいるという事実、現実はあるのです。その点についてはどうなのでしょうか。東京都の認証保育を東京都知事も進めていた。そこは伺っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":177,"id":"exchange-048"},{"speaker":"南委員","kind":"質問","question":"区民の皆様が子育てしながら働き続けたい、そのために認可保育園を希望しておられた。昔からそういう状況はずっと父母側にはあるわけです。そういう状況をきちんと受けとめて、品川区としては保育の責任があるわけですから、きちんと認可保育園の建設をしてこなかった、そこのところに今回のような事態が発生する要因があったのではないかと私は思っているのです。その点についての認識はいかがでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"本格的に待機児童対策に取り組んだ平成２２年から、認可保育園はコンスタントに増やしておりますので、きちんと計画を立てて、それに沿って今後も開設をしていきます。","voiceIndex":184,"id":"exchange-049"},{"speaker":"南委員","kind":"質問・要望","question":"そこのところをしっかり受けとめていただきたいと思いますが、そこについての認識を責任者から改めて伺いたいと思います。だから、例えば２歳までしか預からない認証保育園については、何らかの対応を求めていく、そこまで言っていいのかという心配を持ちながらも、そういう気持ちはあります。そういう点については、どう考えたらいいですか。そんな負担をさせてしまって、どう思うのですか。","respondent":"大澤待機児童対策担当課長","answer":"認可保育園の開設は今後も進めてまいりますので、３歳児で路頭に迷うようなことは今後はございません。認証保育所と認可保育園の連携につきましては、公平性という観点から難しいと考えております。","voiceIndex":186,"id":"exchange-050"},{"speaker":"南委員","kind":"質問","question":"２歳までしか預からない保育園が１３園、４１６人分あります。こういう保育園は、これからも存続していくと思います。そして、不承諾通知をいただいた方は、そういう保育園を選択する場面があると思います。選択せざるを得ない状況に対しては、どう区としては考えているのですかと聞いたのですけれども、答弁がありません。答えてください。","respondent":"大澤待機児童対策担当課長","answer":"認可保育園を開設していきます。","voiceIndex":188,"id":"exchange-051"},{"speaker":"南委員","kind":"質問","question":"その選ぶときに、２歳児までしか預からない認証保育所を選ばざるを得ない区民も大勢いらっしゃるわけです。現に４１６人もいらっしゃる。そういう苦労がないように改めていくべきだと私は思っているので、２歳までの保育園ではなくて、何らかの形を考える必要があるのではないかという趣旨の発言をしました。答弁をお願いします。","respondent":"大澤待機児童対策担当課長","answer":"認可保育園をつくっていますけれども、ニーズに追いつけない現状があり、その中で選考させていただいて、残念ながらご希望に沿えない方もいらっしゃいますが、その場合は、例えば認証保育所でしたら保育料を助成して、認可保育園に入った場合と同じ保育料にしているとか。","voiceIndex":193,"id":"exchange-052"},{"speaker":"南委員","kind":"意見","question":"保育料の助成をしているからいいということにはならないと思うのです。２歳児までの保育園に入れざるを得ない人に対しても、保育料を補助しているのだからいいというわけにはいかない。全然、次元の違うことを答弁されたと私は思っているのです。違う答弁だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":195,"id":"exchange-053"},{"speaker":"渡部委員","kind":"質問","question":"もっと言うと、例えば２歳から３歳のときに上がれなかったらどうするではなくて、例えば、１次で今回、確かに不承諾の方がいらっしゃった。品川区の子どものことがどうやったらよくなるのか、きちんとみんなで考えましょう。課長、この先も基本的に２歳と３歳の問題というのは、あらあら品川区は順調にいけそうだと今日の審議の中では捉えてよろしいのですかね。","respondent":"大澤待機児童対策担当課長","answer":"現在の２歳児と３歳児の定員差、新規開設園の３歳児の枠で、申込者分は全てクリアできる数になっております。","voiceIndex":198,"id":"exchange-054"},{"speaker":"こんの委員","kind":"質問・要望","question":"私も、今の議論をずっと伺っていて、確かに請願項目の１番について問題はあろうかと考えています。私のこの理解で合っているかどうかの確認が１つです。１番について問題はあるのですが、今おっしゃったようなことで丁寧にしてくださっていることをさらに続けていただきたいと思いますが、その点、いま一度、ご説明と、私の理解が合っているかどうかを確認させてください。","respondent":"大澤待機児童対策担当課長","answer":"認証保育園については、認可の補完的な役割ということで、何年か先には、申込者の希望が減ってくれば、一定の役割が終わる時期が来るかもしれませんが、いましばらくは認証保育所の必要性はあると考えています。","voiceIndex":200,"id":"exchange-055"},{"speaker":"鈴木（博）副委員長","kind":"質問・要望","question":"ただ、１つだけ、私のところにも、ひよこの家保育園をはじめ、周りの認証保育所から、父兄の方が患者として多数いらっしゃるのです。だから、認証保育所に対して、先ほど保育料の助成をしているというお話があったのですが、それ以外にも区として、認証保育所も大事にして、いろいろとサポートしていただきたいと思うので、その点では、ほかにどのようなことをされているのでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"保育の質ということでは、東京都の指導検査のときに必ず区も立ち合うということで、いろいろ細かい点を見ています。認証保育所は、かなり緩やかな部分もありますので、中にはあえて選んで入園されている方もいらっしゃるかと思います。","voiceIndex":202,"id":"exchange-056"},{"speaker":"鈴木（博）副委員長","kind":"意見","question":"認証保育所に行かれているご父兄の方とか、現に生活しているお子様たちが非常に幸せに豊かに生活できるように、認可保育園に負けないように、その辺、区としてのサポートをよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":204,"id":"exchange-057"},{"speaker":"南委員","kind":"質問・要望","question":"補完という言葉を課長がおっしゃったけれども、補完という位置付けで見ていいのかどうか、私はいろいろあると思いますけれども、とにかく待機児を救ってくれる、そういう役割も果たしていただいていることは事実だと思います。何カ所もの保育園を施設見学させていただいて、いろいろなお話を伺っておりますので、そう受けとめております。そこは正確に理解をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":205,"id":"exchange-058"},{"speaker":"渡部委員","kind":"質問","question":"本日、結論を出すというところです。３歳児に上がる際には、必ずどこかしらの園には入れるという話も伺っています。万が一、この先にもそういう状況があったときには、しっかりと手厚い対応を保護者、お子様にしていただければと思います。認可保育園につきましても、品川区では、この先にも計画がありますし、まだまだ増えていっている状況であると思いますので、この請願に対しては不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":207,"id":"exchange-059"},{"speaker":"こんの委員","kind":"質問・要望","question":"今日、結論を出すでお願いします。先ほども確認をさせていただきましたが、この請願の項目の１番については、区としても、きちんと３歳に上がるときの手当て、あるいはご案内、そうしたもので、ほぼ３歳のときに認可保育園に移る、そうした手続と流れになるように努力をされている話を理解できました。さらに努力をしていただきたい要望も含めて、このことについては不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":208,"id":"exchange-060"},{"speaker":"南委員","kind":"質問・要望","question":"今、区で努力をしている話は伺いました。しかし、今年に限らず、例年、認可保育園で認証保育園に預けておられるお母さんたちが、次の保育園はどうしようか、どうなるのだろうかと苦労してこられた、そういう事実があるわけです。私は、そのことを強くお願いしたいと思います。特に請願項目の２番のほうも力を込めて進めていただきたいとあえて申し上げて、採択の理由にしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":209,"id":"exchange-061"},{"speaker":"松永委員","kind":"確認","question":"請願項目の１番に関しましては、認証保育所と近隣との認可保育園との提携という部分に関しましては、先ほどの議論の中でも確認をさせていただいたのですけれども、公平性に欠ける部分もあります。請願項目の２番に関しましては、現状を踏まえて、今後も認可保育園の増設を進めていかれるということも先ほどの質疑の中で確認をさせていただきました。この請願第７号に関しましては、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":210,"id":"exchange-062"},{"speaker":"高橋（し）委員","kind":"意見","question":"今日、結論を出すということで、請願項目の１番については、議論になっていますが、説明の中で調整指数の公平性の点、それから、２、３歳の定員差、あと新規の開園で、数字的に見ても吸収できるということであります。現状も努力されていますが、今後も対応していくというところでありましたので、その点で進めているということで、この請願に関しては不採択であります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":211,"id":"exchange-063"}]},{"id":"topic-06","title":"を行います。 専決処分の報告","agenda":"を行います。 専決処分の報告","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"平成２７年ごろから滞り始めたということですが、もうちょっと詳しい経緯を教えていただければと思います。平成２７年に全く支払いが行われていないのか、それとも、断続的にではありますが、払っていたのか伺います。","respondent":"廣田子ども家庭支援課長","answer":"平成２６年までは順調にお支払いされていますが、平成２７年を最後に、体調が悪いということで滞り始めたのですが、その後、連絡がとれませんでしたので、再三にわたり、郵送とか電話の督促を行ったのですが、連絡がとれなかったため、弁護士に委任し。","voiceIndex":218,"id":"exchange-064"},{"speaker":"のだて委員","kind":"質問","question":"そうしますと、まだ相手方の状況はあまりつかんでいないということですね。体調が悪いということはありましたけれども、これは事業資金ですから、仕事を続けられないとかいったことも把握されているのか伺いたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"先ほど申し上げたとおり、平成２７年１２月以降、連絡が全くとれておりません。","voiceIndex":220,"id":"exchange-065"},{"speaker":"のだて委員","kind":"質問・要望","question":"全く連絡がとれていないということで、これは意見として言っておきたいと思いますけれども、連絡がとれないからといって、裁判を起こして、おどして返済を迫っているというのは役所のやることなのかと思います。訪問を行うなどの方法もあると思いますし、できるだけ手立てを尽くしてやっていくことが必要だと思います。ぜひ、そういった対応をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":222,"id":"exchange-066"},{"speaker":"南委員","kind":"質問","question":"２年ぐらいの間、連絡がとれずに滞っていたと理解していいのでしょうか。例えば、連帯保証人の方にご連絡をとるとか、どういう状況かということを、やっていたのかもしれないけれども、その辺の説明がないので、あえて伺います。","respondent":"廣田子ども家庭支援課長","answer":"この方が払えない状況であれば、払えないなりの状況をつかむ必要がありますが、この方と会うことができないので、会うための手段として提訴をしたものです。","voiceIndex":223,"id":"exchange-067"},{"speaker":"南委員","kind":"質問","question":"区がどういう対応をとっていたか、そこのところはわかりました。この返済済額が３８万８,０００円なのですが、返還があった最終日を改めて伺いたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"平成２７年１２月１５日です。","voiceIndex":225,"id":"exchange-068"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"南議員の保育の質問の答弁の中で、２次の空きが９８４名で、認証の枠が３１６名あるとのことでしたけれども、この２次の空きと認証の枠、両方ともですが、このうち０歳から２歳の空きは、年齢別で何人なのか伺いたいと思います。既に認証保育園に通っている方の０歳と１歳の子は、認可保育園に何人入れたのかも伺いたいと思います。この質疑を深めるために有効だと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":229,"id":"exchange-069"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4934#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":58530,"voices":231}},{"id":"h30-20180226-5","meetingId":"h30-cm02","date":"2018年2月26日","dateIso":"2018-02-26","committee":"総務委員会","time":"午前１０時００分～午後 ０時２６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を65件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"会議の運営上、契約議案の審査を先に行います。 (5)「第３７号議案 浜川雨水排水管建設工事その２（浜川公園人孔等整備）請負契約の変更」","agenda":"会議の運営上、契約議案の審査を先に行います。 (5)「第３７号議案 浜川雨水排水管建設工事その２（浜川公園人孔等整備）請負契約の変更」","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"ご説明の中で、平成２８年第４回のときにも変更があったというご説明だったので、このときの変更内容と金額をまず１点教えていただきたいのが１つです。今回の金額の妥当性というところなのですけれども、資料の２ページのところに内訳が書かれていますが、このところの変更内容をもうちょっと具体的にお知らせください。","respondent":"立川経理課長、持田河川下水道課長","answer":"１点目、平成２８年第４回定例会での変更内容について説明いたします。２点目のご質問の変更の内訳についての説明です。資料の２ページ目に金額の内訳が載ってございまして、３ページ目に簡単な平面図が載ってあります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特に１点目の障害物の撤去は、ある程度予測はできたけれども数が多かったという、この数はどのくらい多かったのか、こういうのはどうやって調べて、実際に掘りながら予測と違ってきているというのがわかるのかどうか、ちょっとその辺のことと、あと例えば特殊人孔工のところにらせん階段をつけるなどというのも。","respondent":"持田河川下水道課長、立川経理課長","answer":"設計段階ではその鋼材が３本あるというふうに予測していたのですが、実際に工事をする中では５本あったということで、その部分の数の変更ということで。経理課としましては、金額の妥当性等につきましては、変更後の図面、また積算単価の積み上げ、内訳の一覧表などを確認しております。","voiceIndex":8,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"意見","question":"東京都と品川区が、今のご答弁では、きっちりとチェックをされていて、妥当性があるということなので、了解しました。国の森友学園の問題で、ごみがあった、なかったとか、やはりそういう問題が起こったりすると、国民の方、区民の方に、やはりどこでどのようにチェックをされてきたのかという疑惑が今高まっているところなので、今回はきちんとされているということなので、了解しました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"ほんとうに工事をやるたびとは言いませんが、障害物が結構出てきて、そのたびに工事の変更ということで大変だと思いますが、この工事、障害物、そのまま鋼材が残っていたということは、そのもともと区の工事の時にそのまま埋めてしまったものなのですか。それとも、東京都またはほかの機関の工事でそのまま放置したというか、埋め戻してしまったというか、それはもともとどこの責任だったのですか。","respondent":"持田河川下水道課長","answer":"こちらでもともとどんな工事があったかなのですが、こちらは昭和４０年代に同じく下水道の第２立会川幹線という下水道幹線を工事した時の、残された鋼材だというふうに想定しています。","voiceIndex":12,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"すごく思いやりのある回答だと思うのですが、実際こういうものが残っていて、それで地盤が弱くなるとかというのはちょっと考えられない場所だとは思うのですが、仕方がないですね、そういうふうに埋まっていたということなので、そういう過去の工事でこういうものが埋められていたということで、たびたびこういうふうに変更になるというのはほんとうに心苦しいと思いますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"石田（し）委員","kind":"質問","question":"１点だけ、これだけいろいろと変更をなされる中で、いわゆる当初の設計段階と随分変わって、そちらの部分の変更も生じてくるのかなと思うのですけれども、その辺の経費がここに今回は出ていないのですが、その辺というのはどのように変更がされていて、経費の部分でどのようになっているのかだけ教えてください。","respondent":"持田河川下水道課長","answer":"必要な管きょを施工するためにどうしても障害物が出てしまったということで、その障害物を撤去する費用ですとか、また特殊人孔につきましては、維持管理性ということで、当然下水道を流すという機能には支障のない範囲での変更ということでございまして、当初のこの設計。","voiceIndex":15,"id":"exchange-006"},{"speaker":"あくつ副委員長","kind":"確認","question":"１点だけ、確認をさせてください。私も今わかったのですが、工程表があるのですけれども、課長のご説明を聞くと、変更ということでやることが増えたような印象があるのですが、近隣住民への影響等を考えたときに工期には影響がないのか、そこの１点だけ確認をさせてください。","respondent":"持田河川下水道課長","answer":"工期につきましてはこちらの工程表のとおり、今、バーが引いてありますが、平成２９年度末という形での工期の中で工事は行うものです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"質問","question":"これは当初予算より１割高くなったというのは、今までのご答弁で大体理解できました。それは私、理解できました。１点だけお聞きしたいことがあるのですけれども、昨年の１２月に近隣の町会さんとか近隣の方を含めて、現場見学会をやっていますよね。その場所はどの辺のところの見学会をやったのか、それだけお知らせいただければと思います。","respondent":"持田河川下水道課長","answer":"これはこの平面図で行きますとＲＳＮｏ.１と書いてあるオレンジ色の丸、これが下水道の立坑で、２０メートルぐらいの深さの穴が掘ってあるのですが、こちらは浜川公園の中にございまして、浜川公園に住民の皆様に集まっていただきまして。","voiceIndex":19,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２ページと３ページのところですが、もうちょっと詳しく人員の増減のところの内訳を教えていただきたいと思います。特に職種とか仕事の内容がどういう部分の方が増になり減になっているのか、ちょっと今の説明が早口だったのと、もうちょっと詳しく教えていただきたいのでお願いいたします。","respondent":"黒田人事課長","answer":"区固有教員は、学校の先生のほう、いわゆる品川区で採用する教員でございまして、こちらのほうは２名を増員するというものです。","voiceIndex":36,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"職員定数を２,４８０人とする変更ですけれども、参考までに財調人員が何人になっているのか教えていただきたいのと、その差の数をどう理解すればいいのかも教えてください。それが１点です。","respondent":"黒田人事課長","answer":"基本的には、その執行体制の中で、コア業務は職員がやるということで所要人員を算定していますので、公務員でなくてもできる仕事というものにつきましては、例えば民間委託ですとか、そういったところで、できる限り民間活力を活用するという形で進めておりますので。","voiceIndex":38,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"今、所要人員の積み上げという言葉がありましたよね。ちょっと所要人員とはどういう意味なのか。例えば所要人員は多分各職場から要求などがいろいろ出てきて、それの積み上げだと思うのですが、実際的にその職場から出てきた所要人員というのがどういう数だったのか。それと区の判断のところの差がどうなっているのか、具体的に教えてください。","respondent":"黒田人事課長","answer":"仕事が増えているという点では、平成２８年度から平成２９年度は職員の実数も増えてありますので、そういった意味ではこの定数の職員数の中で工夫を図って事業を実施していくというようなところです。","voiceIndex":40,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"所要人員の説明をもう１回してほしいのと、積み上げている数がどうだったのか、具体的に、職場から出ているはずですので、それと実際に配置されるところの差が出ているので、私はどこの職場も満足しているはずはないと思うので、そこの差について答えがなかったので１つ教えてください。","respondent":"黒田人事課長","answer":"減の中の用務職につきましては、保育園の用務職につきましては、退職不補充ということを基本に、用務職が配置されていない保育園につきましては非常勤職員を２名配置して保育園の運営に当たっていただいておりますし。","voiceIndex":42,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"繰り返しますけれども、所要人員と職場との要求の差は持ち合わせていないということなのですが、戻れば出るのでしょうか。用務職の退職不補充、保育園は非正規を２名配置している、この非正規とは１日フルタイムの非正規なのでしょうか。２名配置しているからいいということなのでしょうか。ちょっとその辺、どこでどう意見を聴取しているのか教えていただきたいと思います。","respondent":"黒田人事課長","answer":"用務職につきましては、保育園につきましてはフルタイムの配置かですが、基本的に非常勤職員ですので、フルタイムということではなくて、非常勤職員ですので職員より時間数が短い職員を２名配置しているです。","voiceIndex":44,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私、用務さんがいなくなったというのはびっくりしましたけれども、用務の仕事を人事のところでどう捉えていて、実際にどう委託がされているのですか。用務職はたくさんいろいろな仕事があると思うのですけれども、それがいろいろな職種の人に委託をされているということなのでしょうか。そこをもう１回聞かせていただきたいのと、あと、今、再任用の方がいらっしゃいますよね。","respondent":"黒田人事課長","answer":"再任用につきましては、フルタイム職員は条例内の職員数としてカウントされまして、短時間については条例上のカウントにはなっていないというものです。","voiceIndex":46,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"済みません。長くなっていますけれども。非常勤といわれる職員の方が何人、何パーセントいるのか教えていただきたいと思います。業務委託をいろいろな部分でされていますが、この業務委託に該当する部分において職員が何人削減されたかというのはわかるのでしょうか。","respondent":"黒田人事課長","answer":"業務委託において削減された数につきましては、毎年度それぞれ見直しをしていますので、例えば平成３０年度の状況は、先ほどの説明のとおりでございまして、平成２９年度につきましては会計管理室で執行関係の工夫でマイナス２減など、毎年度見直ししています。","voiceIndex":48,"id":"exchange-015"},{"speaker":"吉田委員","kind":"質問","question":"私からも、保育園のこの用務が２減で、退職不補充ということがちょっといかがかなと思うのですけれども、非常勤２名をそのかわりに配置しているということですけれども、非常勤といっても用務の、例えばこの曜日のこの時間は用務に当たるというふうにきちんと仕事を区分けして採用されているのか、それとももうこの人数の中でこの用務はこの中で何とか工夫をしてやるようにという形の採用なのか。","respondent":"黒田人事課長","answer":"用務職は、配置がないところにつきましては非常勤２名体制ですので、基本的には園の中の工夫で、園運営に支障がないように配置されているというふうに考えてあります。","voiceIndex":50,"id":"exchange-016"},{"speaker":"吉田委員","kind":"質問","question":"今まで保育園の拡充ということを訴えてきていて、区立保育園の場合は処遇という意味では私立保育園よりは恵まれているところがあるかもしれないのですけれども、４定の一般質問でも申しましたけれども、保育士にとってのストレスは処遇のこともそうなのですけれども、それよりも大きいのは保育に専念できない。","respondent":"黒田人事課長","answer":"保育園につきましては、園が開いている時間も長いという意味では、一定程度、シフト勤務の中で交代して工夫を図ってやっていく必要があると思ってございまして、そういった中では用務職の配置を変えて、非常勤を配置するというところにつきましても。","voiceIndex":52,"id":"exchange-017"},{"speaker":"吉田委員","kind":"質問","question":"保育課もそれを把握していらっしゃっていて、それが何事もなくてほんとうによかったと思うのですけれども、そういうのも、どのような対応をするのかということに対して、今課長がおっしゃったような、工夫をして、フォーメーションをもう１回見直して、この時間帯にはこの人がこの辺まで見るみたいな形で対応するというふうに伺いました。","respondent":"黒田人事課長","answer":"今の委員のご指摘内容から言いますと、用務職だからということではなくて、いわゆる保育士が保育を運営する中で、お子さんの安全をきちんと見ていくというところは全体的な対応が必要なのかなと思いますし、非常勤をプラス２名ということで全体的な園運営を。","voiceIndex":54,"id":"exchange-018"},{"speaker":"須貝委員","kind":"質問・要望","question":"ほんとうに定数条例関係で昭和５８年から平成３０年まで職員の削減をして、このような努力をされてきているというのは、私としてはよくやっているのだなと思いますが、品川区は人口がますます増えているではないですか。そういうことに関して、こうやって人員減、今回所属別の内訳を見ても、そちらの高齢者福祉のほうで実際介護等で増えていないと、非常にこれは心配されるのですが、それは大丈夫なのですか。","respondent":"黒田人事課長","answer":"いわゆる高齢者福祉の部門ですと、いわゆる福祉事務所であったりという意味では、専門職と事務職の置きかえなどで、少し専門性を高めていくというところと、高齢福祉部門ですと。","voiceIndex":56,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"一言だけ。こういう定数条例、一生懸命頑張っているのはわかるのですが、ぜひともそれによって区民サービスが減るようなことがないように、より充実させるように、そちらのほうに重きを置いて今後も対応していただきたいと思います。終わりです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-020"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"１点だけ、定数に関しては異論もないのですが、いろいろと今、話の中でも増減の中で現場の声を聞いていますと、これはやはり予算との関係性がどうしても出てくるのかなと思いますが、区としてこういう事業に力を入れるからその部署には人員を増やしていくとか、一方で、この部署の事業は少し抑えめに来年はやるから人員を削減するなどということがいろいろあるのかなと思うのですが、今回この内訳を見て。","respondent":"黒田人事課長","answer":"今、委員からご指摘いただいたこととちょっと関係すると思いますが、これまでは業務内容の見直しなどをメインにプラスマイナスでという形でやってきていたところも当然にあるものでございまして、だけれども、今ＡＩの活用というご指摘がありましたが、そういった中では。","voiceIndex":59,"id":"exchange-021"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"なので、そういった工夫もしながら、人員をどうやって配置していくかというのは、これも今まではなかった人事の考え方かもしれないですけれども、今後どんどん出てくるわけですよ。なので、早い段階でそういったことも視野に入れていただきながらの人員配置というのをしていただきたいと思うので、その辺をぜひ考えていただければと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"いろいろな職場から人手不足の訴えがあると私は思っているのです。再三伺っている所要人員、職場から出されている所要人員を課長からお答えいただけなくて、現在の数値が所要人員だと、私は違うと思いますけれども、そう言って、答えてくださらないのですけれども、ちょっと違った角度から聞いてみますが、仕事の量が増えている職場、多い順に３カ所教えてください。","respondent":"黒田人事課長","answer":"平成２８年度の超過勤務につきましては、指導課でありますとか、これは平均になりますが、オリ・パラ準備課とか、情報推進課というのが多い職場です。","voiceIndex":62,"id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"具体的に聞いていてもご答弁いただけないので、聞き方を工夫しているつもりなのですけれども、残業が多い職場というのは、先ほどの仕事量が増えている職場と残業が多い職場はイコールという意味ですか。ちょっとそこのところを教えてほしいのと、病欠者の数は把握されていますよね。これで私は自分の質問のところで答えが来ない部分を一生懸命埋めようとしているので、答えていただきたいと思います。","respondent":"黒田人事課長","answer":"仕事量が増えた職場につきましては、今回のご審議でも職員を配置している職場は仕事が増えている職場というふうに認識してございまして、病欠者数につきましては、人事のほうで当然把握はしていますが。","voiceIndex":65,"id":"exchange-024"},{"speaker":"飯沼委員","kind":"提案","question":"当然理解しています。人事課長としては、全職場のことを把握した上でいろいろ定数条例の増減を提案をされる立場にあるので、ぜひ全体像をつかんでいらっしゃるのだったら、それをきちんと伝えてほしいと思って聞いているので、数値で出ない部分は後で出るのでしょうか。ぜひ出していただきたいのですが、いかがでしょうか。それだけで終わります。","respondent":"榎本総務部長","answer":"１００名を多分超える要求数は毎年出ていると思います。ただそれに対して、やはり採用できる数というのは限られていますので、それに対して応えられる数というのはある程度それぞれの職場の事情を聞いて、必要なところからつけるという形でいつも調整しています。","voiceIndex":68,"id":"exchange-025"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"そういう、今回は先ほど部長からもご答弁がありましたが、要望がある中でそれは当然そういうことはご判断されると思うのですけれども、そういうご検討があったのか、先ほど高齢者福祉課については、同じ数の中でも専門性を高めていくというご答弁がありましたけれども、そういうことがあったのかどうかということをお答えできる範囲で教えていただいたいということが１つ。","respondent":"黒田人事課長","answer":"保健師の採用をして、いわゆる保健衛生部門に配置するということのほかに、組織の中で必要とされているところに配置できるような形ということで、これは組織運営上の話になりますが、そういった中でも対応できるということで、こちらもその採用できる数が。","voiceIndex":70,"id":"exchange-026"},{"speaker":"飯沼委員","kind":"意見","question":"意見をつけて反対します。２点目は、正規の仕事をどんどん規制緩和で低賃金、低処遇の労働に置きかえていることに対して、反対をいたしますので、この定数条例にも反対します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":76,"id":"exchange-027"},{"speaker":"吉田委員","kind":"質問","question":"私も反対をしたいと思います。昨年も賛成をしながら意見は言ったのですけれども、やはり具体的に、ほんとうにこれは人員が足りないのだというような現場で、事例に遭遇して、それでそれによって一般質問をさせていただきましたが、なおかつそこのところが減らされるということでは、自分たちが主張してきたことと整合がとれませんので、反対したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-028"}]},{"id":"topic-02","title":"第１１号議案 職員の給与に関する条例の一部を改正する条例","agenda":"第１１号議案 職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"資料１の１ページ目の趣旨のところなのですけれども、扶養手当のところ、国の見直しの考え方とかその根拠を教えていただきたいのが１点です。","respondent":"黒田人事課長","answer":"配偶者手当、扶養手当の受給人数ですが、こちらのほうは、これも配偶者手当を区で受けているのが２８０名程度で、そのほかの扶養手当が１,０００名程度で、大体１,３００名弱ぐらいの方が扶養手当ないしは配偶者手当を受給しているというような状況です。","voiceIndex":86,"id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"それぞれありがとうあります。（２）の等級別基準職務表の改定というのが、８級制が６級制になったという、この辺の改正の理由はどういうところなのか教えてください。","respondent":"黒田人事課長","answer":"８級制から６級制に変わった理由ですが、行政系人事制度のあり方についてということで人事委員会の意見の中で管理職及び係長職の職責が高まっており、めり張りのある人事級制度を検討する必要があるというような背景もありまして、この間。","voiceIndex":88,"id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"新旧の給料表が載っているのですけれども、実際的に不利益になるような級とか号給があるのかどうか、あと、同一労働において減になるようなことが生じてしまうのかどうか、そこら辺を教えてください。","respondent":"黒田人事課長","answer":"ただ、今回の行政系人事制度の中で職務の切りかえの中で級が変わった方については、対応した級のほうに切りかわるのですが、その場合も現給を保障するということになりますので、不利益というものはございません。","voiceIndex":90,"id":"exchange-031"},{"speaker":"須貝委員","kind":"質問・要望","question":"今回この条例に反対するものではありませんが、そういう、やはり民間、品川区内で産業を営んでいる商店等ありますが、そういう方たちにはこういう手当というのは支給されていない方が大勢いるということは、私は職員全体の皆さんで理解、認識していていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-032"},{"speaker":"吉田委員","kind":"確認","question":"言葉の確認です。不勉強でまことに恥ずかしいのですけれども、この欠配一子という言葉で、これを調べて、だから扶養する方のお子さんで、既にお子さんを持っていて配偶者を亡くされているのか、離婚されたかわかりませんけれども、そういう人のことと思って理解してきたのですけれども、それでいいのでしょうか。済みません、確認だけさせてください。","respondent":"黒田人事課長","answer":"こちらは欠配一子と略称で書いていますが、こちらは配偶者がいない場合の扶養親族である子のうちの一人ということで、複数お子さんがいらしても一子、扶養している一子のことを指すです。","voiceIndex":93,"id":"exchange-033"}]},{"id":"topic-03","title":"第１２号議案 職員の旅費に関する条例の一部を改正する条例","agenda":"第１２号議案 職員の旅費に関する条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"この条例改正の中身は、１ページ目にあります８級制から６級制に変更されるために当該級に変更があった、そのことによって発生する級を移しかえただけという捉え方でいいのでしょうか。そこのところを教えてください。","respondent":"黒田人事課長","answer":"委員のご指摘のとおり、今回級が再編されましたので、級を移しかえたものです。","voiceIndex":113,"id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問・要望","question":"資料の４ページの別表第２のところの括弧に第３５条関係と書いてあるので、第３５条がどういう中身なのかなというのが資料の中でわからなかったので教えていただきたいのと、ここに載っていない表で基本的な運賃体系のところは、別に何キロメートルが幾らとかあるのですよね。それプラスこの表なのかなと理解しています。基本的なところを教えてください。","respondent":"黒田人事課長","answer":"今回の資料につきましては、変わったところのみ記載しておりますが、ご指摘の別表第２につきましては、委員のご指摘のとおり、距離に応じて運賃の上限が定められておりますので、その中で、この地方がどこであるかということは今具体的に申し上げられませんが。","voiceIndex":115,"id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問","question":"別表第２の中身のことで、この区分が詳しく書かれているのですが、この中身だけ、指定都市とか甲地方、乙地方、丙地方とわかれて金額が違うので、下の６級、５級にアンダーラインが引いてあるのが、ここが変わりましたよということの理解はできているのですけれども、この表の区分の中身についてわかったら教えてください。","respondent":"黒田人事課長","answer":"別表第２のこの指定都市と申しますのは、人事委員会が定める都市の地域を言いまして、甲地方というのは北米地域、欧州地域及び中近東地域として、人事委員会が定める地域のうち指定都市の地域以外の地域で人事委員会が定める地域一帯になりますので。","voiceIndex":117,"id":"exchange-036"},{"speaker":"須貝委員","kind":"質問","question":"１点だけ疑問があるのですが、これを運賃という名称にすればほとんど全て該当すると思うのですけれども、それはそうではないのですか。あくまで船賃ということで限定する必要があるのですか。参考のために聞かせてください。","respondent":"黒田人事課長","answer":"公務員の旅費につきましては、国家公務員等の旅費に関する法律というものがございまして、その中で鉄道賃、船賃、航空賃という区分がございまして、そこから基本的には準拠して制度がつくられるというものです。","voiceIndex":119,"id":"exchange-037"}]},{"id":"topic-04","title":"第１３号議案 公益的法人等への職員の派遣等に関する条例","agenda":"第１３号議案 公益的法人等への職員の派遣等に関する条例","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"この条例、公益法人等への一般職の地方公務員の派遣等に関する法律というのは、もう随分前にできた法律だと思うのですけれども、例えばこの法律ができた段階でわりとさまざまな自治体がこれに準拠する条例をつくっているのですが、品川区はその時点では条例はつくらず、でも私の認識では結構公益法人などへ職員を派遣したりしているのではないかと思うのですが。","respondent":"黒田人事課長","answer":"他の自治体では、その法律ができた直後に条例を制定したところもあるのですが、原則として給料については、法人の身分を取得するので、その該当法人が支払うという意味では、法人側の受け入れができないと派遣ができないということになりますので。","voiceIndex":135,"id":"exchange-038"},{"speaker":"吉田委員","kind":"質問","question":"今回この条例をつくった趣旨はわかりましたが、今までとは性質が違うというようなことなのでしょうか。だとしても、この条例ができた以上、今までのそういう形の派遣のやり方というのはやはりこの条例と整合性をつけなければいけないと思うのですけれども、その辺について、何かこの条例ができたことでこれから整合性をつけなければならないケースとか、そういうことがあったら教えてください。","respondent":"黒田人事課長","answer":"条例を制定しましたので、今回は大会組織委員会がそういった受け入れ体制をとれるということで、今も派遣をしていますが、地域に密接であれば区で給与を支払うということも鑑みて。","voiceIndex":137,"id":"exchange-039"},{"speaker":"吉田委員","kind":"確認","question":"今後のことはわかりましたけれども、現在そういうふうに行われているところとの何か不整合みたいなものは出てこないのでしょうか。それだけもう１回確認させてください。","respondent":"黒田人事課長","answer":"現在行っておりますのは、いわゆる研修派遣でございまして、職員の能力向上を目的として区以外の団体に派遣をしているというところになりまして、区に在籍して、という意味では定数条例上も職員の数に入ってありますので、その中で派遣しているという意味では。","voiceIndex":139,"id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問・要望","question":"根拠法のところで、長い名前で、公益的法人等への一般職の地方公務員の派遣等に関する法律という名称がついていますが、この法の中に多分書かれていると思うのですが、公益的法人というのはどのような認定があるのか、わかったら教えていただきたいのと。","respondent":"黒田人事課長","answer":"対象法人につきましては、資料の項番３のところに書いてありますとおり、米印の、一般社団法人または一般財団法人、一般地方独立行政法人、特別の法律により設立された法人、これはいわゆる公益法人を指していまして、公益財団法人と。","voiceIndex":141,"id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問","question":"今のご説明のところだと、どこの部署から派遣をされているということなのか教えてください。","respondent":"黒田人事課長","answer":"どこの部署からかということは人事異動のヒアリングの中で、大会組織委員会への派遣ということについては話をしまして、人事のヒアリングの中で職員を選抜しますので、どこの部署からかというのを、一般事務職と、技術職についてはその技能を有している者を派遣しますので。","voiceIndex":145,"id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これ自体には賛成のつもりでいるのですけれども、現職場というのはどこも大変な職場から派遣をされるということにおいては、職員の声をしっかりと受けとめて派遣をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-043"}]},{"id":"topic-05","title":"第４１号議案 職員の退職手当に関する条例の一部を改正する条例","agenda":"第４１号議案 職員の退職手当に関する条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"資料１ページの１の趣旨のところです。退職手当は結果的には削減なのですが、国の退職手当の支給水準引き下げの基本的な考え方がわかったら教えてください。特別区内では民間企業の退職手当の支給状況の調査がなくて、比較をする調査がないと聞いたのですが、ちょっとこの辺わかったら教えてください。","respondent":"黒田人事課長","answer":"退職手当についての国の考え方につきましては、先ほど申し上げたように民間の支給状況に準拠して、国家公務員の退職手当の支給額と民間の状況を比べたときに、均衡を図るために国のほうにおいても削減しているという状況がありまして。","voiceIndex":162,"id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問","question":"国のほうの説明は、民間等の支給状況との均衡をということにおいては、民間が下がっているから国も下げていると。特別区のところは、調査対象の資料はないけれども同じような関係なのかという理解でよろしいのでしょうか。その点が１点と、あと、済みません、退職手当の計算式、基本的なところでわからないのがポイント制なのですが、合わせてどのように基本額と調整額が計算されるのか教えてください。","respondent":"黒田人事課長","answer":"退職手当の計算式ですが、基本的にその給料表の月額に、在職の年数に応じて支給月数が定められておりますので、その支給月数を掛けた額に、この調整額ということで、先ほど申し上げたとおり、退職前２０年間に在籍した職、例えばこちらの資料にありますけれども。","voiceIndex":164,"id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問","question":"先ほどの説明で、影響がマイナス２.８２％、平均で６５万円減ということだったのですけれども、影響を受ける層は２の（２）のところで、行政系で部長から主任主事まで並んでいますけれども、人員的にはどこが一番多いのか、また、退職金削減で一番影響するのはどこなのか教えてください。","respondent":"黒田人事課長","answer":"平均の削減率ですが、基本的には一律に支給月数を下げますと、その分基本給が高い部分に大きく影響がありますので、そこは調整額ポイントでバランスをとって、平均的な、国の給与カーブに沿って、退職手当の支給の状況に沿って制度を設定したというふうに。","voiceIndex":166,"id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"最後になります。わからないのが、２の（３）のところなのですが、支給制限規定の改定のところで、１８条のところなのですけれども、これがどう改定されたのかもうちょっとわかりやすく教えていただけたらと思います。","respondent":"黒田人事課長","answer":"従来の規定ですと、懲戒免職処分を受けた場合につきましては退職金は支給しないという規定ですが、他団体のいわゆる裁判例で退職手当につきましては、退職手当と懲戒免職というのは別の規定というか処分であって。","voiceIndex":168,"id":"exchange-047"},{"speaker":"須貝委員","kind":"質問","question":"今のお話ですが、職員の退職手当に関しては、民間の支給率が下がっているから今回支給率を下げたと。今、裁判云々というお話がありましたが、これは民間がほとんどがそういうふうにしている中で、これに関しては民間に準拠しないで国の支給制限規定に準拠するというのは、何か矛盾しているように思うのですが、その点はどうなのでしょうか。","respondent":"黒田人事課長","answer":"ただ、その懲戒免職処分の内容について、非違行為の内容とか、職員のそれまでの勤務状況等を勘案して、一律に全額不支給ということについては違法であるというような、これは裁判、高裁等での判決が出ている中で、国及び都も含めて他団体もそういった形で。","voiceIndex":170,"id":"exchange-048"},{"speaker":"須貝委員","kind":"意見","question":"その辺がちょっと明確に示されてはいないのですが、判例云々はありましたが、それぞれ犯罪の内容、またどういう損害をその自治体または会社に与えたかによってそれぞれ違うと思うのですが、その辺も明確にならないと、この支給制限規定の改定というふうに打ち出されて、国に準じた規定にしますよとなると、何かややもすると一般の区民からも誤解を招きかねないですよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":172,"id":"exchange-049"},{"speaker":"飯沼委員","kind":"意見","question":"意見をつけて賛成をします。退職手当というのは退職後の生活を支える基本的な労働条件の１つであるので、慎重であってほしいなと思います。特に特別区内での比較する対象が不明確というところは非常に疑問は残りますが、労使で合意をしているということなので賛成します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":177,"id":"exchange-050"},{"speaker":"吉田委員","kind":"質問・要望","question":"生活者ネットワークも賛成なのですけれども、先ほどもありましたが、やはり退職後の生活ということを考えると、ぜひ慎重であっていただきたいと思います。ただ、やはり民間の中にはなかなか退職金の支給そのものが厳しいというところも出ておりますので、準拠するということではやむを得ないと判断し、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":180,"id":"exchange-051"}]},{"id":"topic-06","title":"平成３０年請願第６号「核兵器禁止条約への参加・批准を政府・国会に求める意見書の採択を求める請願」","agenda":"平成３０年請願第６号「核兵器禁止条約への参加・批准を政府・国会に求める意見書の採択を求める請願」","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"は５０カ国が批准をし、９０日後に発効するということなので、ぜひその方向になってほしいなと思っています。区の姿勢も、その中では伺っていきたいと思っています。そういった意味で、他会派の皆さんにもぜひ賛同していただきたいと考えていますが、率直にご意見を出していただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":188,"id":"exchange-052"},{"speaker":"吉田委員","kind":"質問","question":"私も同意見です。非核平和都市品川宣言というのを改めて読み直すと、相当踏み込んで高らかにうたい上げています。ほんとうにそのとおりで、宣言をした以上、何らかの行動が必要だと考えています。今がこの行動のある意味チャンスかなと思いますので、まずは国に対する意見書というのを議会としても採択していくことを主張したいと思いますが、皆さん、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":190,"id":"exchange-053"},{"speaker":"石田（し）委員","kind":"意見","question":"平和首長会議にも加盟をされて取り組まれているという中で、一地方自治体としてこういった宣言も含め事業を展開していることもあり、区民に対しては十分に平和事業として取り組まれているのかなと思いますので、現時点で国に対して意見書を提出する必要性があるのかというのは、我々としては現時点では必要ないのではないかなと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":192,"id":"exchange-054"},{"speaker":"須貝委員","kind":"質問・要望","question":"ただ、私自身も核兵器禁止条約は参加すべきだと思うのですが、この内容そのものはやはり国で、あれだけの国会議員の皆さんがいて、そこでしっかり議論をして、そこで結論が、例えば反対なら反対ということを出していただかない限り、我々はあくまで区議会、区民の代表として活動しているのですから、国会、国への話をここでどうこうするということになると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":193,"id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問・要望","question":"日本国内では１７１７区市がこの平和首長会議に参加をし、ホームページを開くと、核兵器禁止条約の早期締結を求める署名活動の訴えがされています。現状では２６６万９,７８０筆、今年の２月１日現在ですが、署名が集まっています。ちょっと発言をされていらっしゃらない方もおられるので、ぜひご意見を伺いたいのと、最後のところで、ぜひ品川区の見解もお伺いしたいと思います。","respondent":"米田総務課長","answer":"非核平和都市品川宣言が昭和６０年に発出されております。これを品川区としては継続的に区内、それから区外に向け発信し続けているというようなことです。","voiceIndex":195,"id":"exchange-056"},{"speaker":"吉田委員","kind":"質問・要望","question":"品川区の平和事業はよく承知をしております。今回のこの請願の求めに応えて、国に対する意見書を出すということはそれらの平和事業と何ら矛盾するものではありません。国会で議論をされているときだからこそ、やはり区議会としてはこういう方向で議論をしてほしいという意見書を出す意味があると思います。ぜひ採択して、品川区議会としての意見書を提出したいということを主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":198,"id":"exchange-057"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"結論を出す。このため、私ども公明党、また、これは日本政府も含めまして、昨年に賢人会議の設立というものを世界に求めまして、これが一昨年の１１月に被爆地の広島市で初会合が開催されました。この賢人会議を国際関係の真の橋渡しのスタートとするということに当たりまして、私どもは今回のこの意見書を求める請願に対しては賛成はできないというのが私どもの意見であります。長くなりましたが以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":202,"id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問・要望","question":"結論を出すということで、意見を添えて、採択を主張します。私たちは、核抑止論は間違っていると考えています。この間、政府に核兵器のこの考えについて転換を求める意見書、１月２２日現在で１１３議会から提出をされています。ぜひ非核保有国、核をもっていない国も核を保有している国も、やはりこのことに真正面から向き合ってほしいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":203,"id":"exchange-059"},{"speaker":"石田（し）委員","kind":"質問","question":"結論を出すで、我が会派としては不採択です。趣旨としては理解できますが、先ほど述べたとおり、国での議論をしっかりと行っていただければと考えていますので、現時点で我々として意見書を提出する必要はないという判断のもと、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":204,"id":"exchange-060"},{"speaker":"須貝委員","kind":"質問・要望","question":"ただ、これはやはり国の進路を左右することですから、私は国会でやはり国会議員が議論をして、きちんとした、批准しないなら批准しない理由を国民が納得するような発言をしっかりしなければいけないし、被爆国であるこの日本がそのまま放置して批准しなかったということは、まことに世界にとっても恥ずかしいことだと思います。それだけはしっかり申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":205,"id":"exchange-061"},{"speaker":"吉田委員","kind":"質問・要望","question":"ネットとしても本日結論を出すということで、採択を主張します。その点についてはそのとおりだと思います。品川区民にとって一番身近な区議会に対してこういう意見書を求めてきて、それに応えて、国に対しての意見書を出すということはどこに問題があるのか私には理解することができません。ぜひこの請願を採択して、意見書を出すという方向での採択を主張いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":206,"id":"exchange-062"}]},{"id":"topic-07","title":"「その他」を行います。 まず、本定例会の一般質問にかかわる所管質問でありますが、本定例会の一般質問中、総務委員会にかかわる項目","agenda":"「その他」を行います。 まず、本定例会の一般質問にかかわる所管質問でありますが、本定例会の一般質問中、総務委員会にかかわる項目","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"共産党の南恵子議員の代表質問なのですが、３点目の待機児ゼロの問題での人事にかかわるところが、主に答弁漏れと言おうか、何と言うのでしょう、質問内容は、残業とかそういった病欠とかの関係ですけれども、昨年の議会の３定だったと思うのですが、質問をしたところがどのように改善をされたのかというところの内容が不十分であったのと、病欠の現在の人数と増減を聞いているのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":211,"id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問","question":"質問の中で、残業のことと病欠のことを聞いているのですが、５点目の質問にほとんど答えていらっしゃらないのです。だから、そこのところを。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":215,"id":"exchange-064"},{"speaker":"飯沼委員","kind":"質問","question":"説明が悪くてごめんなさい。総務とか人事にかかわるところなので、そこをお聞きしたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":217,"id":"exchange-065"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2100#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":43278,"voices":220}},{"id":"h30-20180227-6","meetingId":"h30-cm02","date":"2018年2月27日","dateIso":"2018-02-27","committee":"区民委員会","time":"午前１０時００分～午前１１時２９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"田中委員","kind":"質問","question":"都市型観光の視点からの商店街の魅力向上に向けた取組みについて伺いたいのですけれども、にぎわい事業と小規模にぎわいづくり事業とホリデートレーニング事業について、要綱を読んでみたのですけれども、昨年４月に改定された部分、すみません、勉強不足でわからなくて、そこの部分はどこだったのかということを伺いたい。","respondent":"山崎商業・ものづくり課長","answer":"効果測定につきましては、その他の事業ももちろんそうですけれども、事業実施後の成果報告書を徴しておりまして、先ほどご説明した来街者数がどのくらいいて、それから、例えば地元にお住まいの児童・生徒を対象にした外国語に親しんでいただくような事業であれば。","voiceIndex":6,"id":"exchange-001"},{"speaker":"藤原委員","kind":"質問","question":"都市型観光についてという所管事務調査なのですけれども、改めてそもそも論でお伺いしたいのですが、品川区は都市だから都市型観光という形になるのでしょうか。いわゆる都市型観光と品川区の観光とは別なのでしょうか。","respondent":"山崎商業・ものづくり課長、鈴木文化観光課長","answer":"一般に観光地と呼ばれるところ、日本にもすてきな魅力的なエリアがありますけれども、そうした集客が期待できる観光地と呼ばれるものは、品川区にはこれだという特性のあるものではなく、商店街の何気ない日常の町歩きといいますか。ただいま商業・ものづくり課長からは、商店街の面での都市型観光の説明でございましたが、区全体としても、今、課長から答弁があったように、いわゆる地方都市などにある大きな観光資源がある観光地とは違うということで。","voiceIndex":8,"id":"exchange-002"},{"speaker":"藤原委員","kind":"質問","question":"それと、せっかくですから、国際も伺いたいのですが、一番上に書いてある品川・日本への理解を深めるという形でしながわ宿場まつりがあるということですけれども、この中にたしか花魁道中が入っていますね、やっていますよね。先ほど商業・ものづくり課長の説明だと、区長も出られてやっていますという形で、江戸風俗、花魁道中はどういう説明をしていくのでしょうか、お伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-003"},{"speaker":"藤原委員","kind":"質問","question":"総括的な意味において何かあるのではないか。何かあるというのは変な言い方ですが、担当の課長として何かお話ししたいこともあるのではないかという思いもありまして、質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-004"},{"speaker":"藤原委員","kind":"質問・要望","question":"それで、ぜひ水戸黄門が出るという話ですから、そのうち、坂本龍馬、旧道のあそこにあるわけですから、今日も後で説明してくださると思うのですけれども、その辺も含めてやっていっていただきたいという思いがあるのですが、最後に、都市型観光を含めて、坂本龍馬を含めて、その辺についてはこれからどういうふうにしていっていただける、構想があれば、内容をお話いただければ幸いなのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-005"},{"speaker":"田中委員","kind":"確認","question":"先ほど、要綱の部分で確認したことは、昨年の４月に改定された部分は、表現の違いくらいで大きく変わっていないというお話だったのですけれども、大きく中身が、例えば限度額が変わってしまうとか、そういう話になったときには、きちんと報告はされますよねということを確認させてください。","respondent":"山崎商業・ものづくり課長","answer":"もちろん事業実施のスキームが変わるといいますのは、わかりやすく申し上げますと、そこにかける予算額が変わるとかということになりますので、先ほどの例示ですと、今は上限額２０万円で、例えば１０の事業を予定しているということになりますと。","voiceIndex":20,"id":"exchange-006"},{"speaker":"田中委員","kind":"確認","question":"金額に限らず、ほかの決定事項とか、そういう条文の中身でこの部分が変わるというときもきちんと報告はされますよねということを確認させてください。","respondent":"山崎商業・ものづくり課長","answer":"基本的にはご説明をするようなことで対応させていただいているところです。","voiceIndex":22,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"事業としてはいろいろ工夫がされているなと思うのですけれども、品川の商店街の１つ１つのイベントもとても楽しいと思いますし、区民の方も喜んでいらっしゃいますし、ぜひそういう姿を見ていただきたいとも思うだけに、実際、こういうインタビューだったり、アンケートだったり、抽出ですから全体の傾向が取れるかというとなかなか難しい面はあるかもしれませんけれども。","respondent":"鈴木文化観光課長","answer":"ご指摘のありましたインバウンドの方、海外からの方の意見や、それから何が楽しいかというようなところのインタビュー、情報収集ですが、実は今年度、幾つかインタビューと、ご指摘にあったホテルでのアンケート等を実施しております。","voiceIndex":24,"id":"exchange-008"},{"speaker":"中塚委員","kind":"意見","question":"旅行されている方に聞くというのもなかなか苦労はあるかと思うので、そういう意味では、品川にお住まいの方はある意味聞きやすいかというふうに思いますので、学校の卒業式や入学式に参加しても海外の方も増えてきて、みんな仲良く学校生活を送っていますので、ぜひ品川に住んでいる方からもいろいろご意見を聞いてもらえるといいかと思いますので、ひとつご検討いただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":26,"id":"exchange-009"},{"speaker":"渡辺委員","kind":"質問","question":"大きいところは放っておいても独自にできるものですから、やはり行政が支援すべきという視点で、小規模、中規模の商店街支援、その中で売り出しや行事が維持できている、増えているというのをすごく感じます。その中で一番、泣きどころは１つだと思うのです、人手のところ。意欲だったり、リーダーシップだったり、そういう意味でのマネジメントの支援をどうお考えかということを聞きたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"今後は、そういう組織をご支援することは継続、あるいは充実を図りながら、商店街活動を担っていただく地元の後継者といいますか、商店街の中心を担っていただいている会長らも実はもう高齢化をしておりまして、その担い手育成の事業がすごく大事だなというふうに感じております。","voiceIndex":27,"id":"exchange-010"},{"speaker":"渡辺委員","kind":"質問・要望","question":"これは特に商店街などは、売り出し等がそれに近いと思うのですが、商店街という観点の中で、これはなぜかというと、食べ歩きだとか飲食などもメニューの中心なものですから伺うのですが、中長期目標と言ったらいいのか、今は年に１回、それが年に２回だけれども、この種のことを四季折々にやれるとか、あるいは毎月やっているとか、支援制度にそういうストーリーがあってもいいかなと。","respondent":"山崎商業・ものづくり課長","answer":"１００ある商店街が単発でそれぞれイベント事業なり、毎日の販路の活動を何か少し、ストーリーとおっしゃいましたけれども、自主的な商店街の活動を阻害することなく、エリア全体としてもっと広げた形で、何かスキームといいますか、それは大事な視点かなということで。","voiceIndex":29,"id":"exchange-011"},{"speaker":"渡辺委員","kind":"質問","question":"そこで、商店街を含めてなのですが、海外、国際化もそうだし、国内もそうだし、交流都市という点で伺いたいと思います。これをどう生かしているのかと。これはやはり観光の軸になる定期的な動線、まず関係者が動くではないですか、行政もそうだし、商店も。そういう意味では、国内外問わず、交流都市、連携する都市、ここをどう観光施策に生かしていくのか、その辺の道筋を伺いたいのが１つです。","respondent":"遠藤協働・国際担当課長、池田スポーツ推進課長","answer":"ただ、個別の分野でご協力できる、特に大使館などで、アジアですと、タイやインドネシアがありますので、そういうところとお話をしながら、観光面では進めることもできるのかなというところで。こういった事業を、今後、１つ１つの小さなところではなく、例えば委員が今ご提案されたようなスポーツツーリズムの中の１点で、商店街と連携して、いろいろなところから招いた方をさらに商店街、例えば飲食店を活用していただくような。","voiceIndex":31,"id":"exchange-012"},{"speaker":"渡辺委員","kind":"質問・要望","question":"それぞれありがとうございました。というのは、先ほど事例も挙げていただいたように、普通気づけなかったり、あるいは多分、町でそういう商売を営む方が求めていることだと思うのです。その辺の考え方を１つ教えていただきたいのと、それと、そのノウハウを今言った交流都市などに、まだまだ伸びしろがとてもある気がします。先ほどのノウハウと合わせて教えていただければと思います。","respondent":"鈴木文化観光課長","answer":"それぞれ所管課においても、従来の様々な支援事業の中でも、そういう情報の提供というところも支援の１つというふうになると思いますので、今後もできるだけそれぞれで収集した情報を共有できるようにして生かせるように取り組む必要があると考えております。","voiceIndex":34,"id":"exchange-013"},{"speaker":"木村委員","kind":"質問","question":"もしそうであれば、その上にあります「英語少し通じます商店街」プロジェクト、確かに海外の方々が日本に来て、日本人のカタコトの英語で何かやりとりをしているところは想像ができるのですけれども、おもしろいですけれども、そういうことを考えると、在住している外国の方々が、少しというか、日本語も多少しゃべれるでしょうから。","respondent":"遠藤協働・国際担当課長","answer":"ですので、そういう部分につきましては、今、多くのところに参加いただきまして、商店街では５３店舗やっていただいて、もともと商店街の方は、おもてなしというのは非常に慣れていらっしゃるところもありますので。","voiceIndex":36,"id":"exchange-014"},{"speaker":"木村委員","kind":"意見","question":"そういうことを考えると、この品川に多くの海外の方々が来られることによって、そのようなことで犯罪的なものに巻き込まれるようなこともあろうかと思いますけれども、そういうことに関して何かお考えが、ちょっと観点がずれているのかもしれませんけれども、もしよろしければ答えていただけませんか。","respondent":"鈴木文化観光課長","answer":"東京に関しては、基本的には都道府県の事務ですが、保健所を設置している市と２３区は東京都との協議で、事務を扱ったり、それから区の条例で民泊に関する規制をかけたりということが可能になるというところで、品川区としても今、都と協議をしながら。","voiceIndex":38,"id":"exchange-015"},{"speaker":"塚本副委員長","kind":"質問","question":"お伺いしたいのは、品川区内で営業している、品川区内に住んでいらっしゃる可能性も結構あるのではないかと思うのですけれども、そういう方々のコミュニティみたいなものも、品川区の中に固まって住んでいるみたいな、文化の違う地域ができ上がったりしているところは、実は出始めていたりしているのかなという気もしているのですが、そういうことをどの程度捉まえているかということをお聞きするとともに。","respondent":"遠藤協働・国際担当課長、山崎商業・ものづくり課長","answer":"今後の推移を見ながら、またいろいろとアンテナを張って研究していきたいと考えていますので、よろしくお願いいたします。商店街の取組みで、ズバリご質問に対応する答弁になるかということはありますけれども、例えば先ほどもイベント事業のほうで、五反田夏祭りをご紹介して、副委員長からもサンバという単語がございました。","voiceIndex":40,"id":"exchange-016"},{"speaker":"塚本副委員長","kind":"意見","question":"商店街における外国人の方がやられている店舗ということで、いろいろなイベントなどにそうやってうまく取り込んでいくことは非常に大事なことだというふうに思うのですけれども、特にそういう今ある商店街のイベントに外国の方々がそこに協力する、参画していくというアプローチからも入っていかざるを得ないと思いますが、いずれはそういう外国の人たちが自分から発信するようなイベントといいますか。","respondent":"山崎商業・ものづくり課長","answer":"商店街のこれまで培った地域のインフラとしての魅力、それから広く外に向けた少し広域的な観点での観光に資する魅力、それから３つ目が、そうした新しく町の構成として新たな魅力を付加する、そうした可能性のある外国の方々が経営するお店などとのコラボレーションといいますか。","voiceIndex":43,"id":"exchange-017"}]},{"id":"topic-02","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"特に京急の立会川駅を出たところの商店街の方々も、龍馬にちなんだ商品だとか、販売をしておりますし、商品だけではなくて食べ物もしておりまして、先ほどの都市型観光という意味も含めて、集客という意味でも、地域を挙げてしていると思いますので、これからまた行政に対していろいろな要望等も出てくると思うのですけれども、ぜひ品川のいろいろある観光の中の１つとして捉えていただいて。","respondent":"鈴木文化観光課長","answer":"来年度事業でも、区の事業と地域の取組みを連携させて、少し地域の取組みを支援するというようなことも予定しておりますので、今後もしっかりと協力体制で、品川区の魅力発信、観光のコンテンツの発信の中で、しっかりと情報発信しながら。","voiceIndex":50,"id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2804#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":27123,"voices":58}},{"id":"h30-20180227-7","meetingId":"h30-cm02","date":"2018年2月27日","dateIso":"2018-02-27","committee":"厚生委員会","time":"午前１０時００分～午後 ３時４０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を83件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成３０年請願第２号、国民健康保険料の負担軽減を求める請願","agenda":"平成３０年請願第２号、国民健康保険料の負担軽減を求める請願","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは本当に７年間で１８万円も上がってしまった。しかも、健康保険からしても、協会けんぽからしても負担割合が高いというのがずっと問題になってきたというのがこの国保だと思うのです。それをあえて値上げするという、今まで税金で負担軽減をしていたのを税金投入をやめて値上げをするということに対しての矛盾というところはどう考えられているのかというのをお聞かせいただきたいのが１点です。","respondent":"三ッ橋国保医療年金課長","answer":"やはり区といたしましても、法定外繰入金はできる限り解消していかなければならないという国の考え方に基づいて対応してまいりますので、今回の税金投入解消は間違っているとは考えておりません。","voiceIndex":6,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"国保の国庫負担割合を増やすように国に求めてくださいということがここに書かれていますけれども、その要望をさまざまなところで出しているのに対して国はどうなのか。国がそういうふうに、国以外のところではあらゆるところで多分国保への国庫負担の割合を増やすようにということで何十年来求め続けてきていることに対してどう答えているのかと、そのことについてもお聞かせいただきたいと思います。","respondent":"三ッ橋国保医療年金課長","answer":"やはり１,７００億円の部分の激変緩和策というものをとっておりますので、ある程度明確な回答の一つになっているのではないかと推測されます。","voiceIndex":8,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、保険制度なのですよ。どんどん保険料を上げていって払えない人がつくられ、そこをどんどん追い詰めてまた取り立てて、そしてもうどうにもならなくなったら保険証を受け取りにも来ないという形になってしまうわけです。その点もお聞かせいただきたいと思います。それで、改めて直近の滞納者の数、それから短期証、資格証、差し押さえの件数、ここら辺がわかったら教えてください。","respondent":"三ッ橋国保医療年金課長","answer":"そのような方は具体的に教えていただかないと、我々も全然わからない状況なのです。全員皆様が同じ状況ではないというのはご理解いただきたいと考えています。その中で、やはり窓口の対応につきましては、きちんと説明していき、また引き続き丁寧に対応してまいりたいと思います。","voiceIndex":10,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、この請願項目の中には、国保への国庫負担を増やすようにということと、それから０歳から１８歳までの子どもの均等割を減額してくださいとあります。市長会か区長会でも要望していたのではないかと思うのですけれども、そこら辺のところの要望と、それに対しての議論の進み具合、そこら辺はどうなっているのかということもお聞かせいただきたいと思います。","respondent":"三ッ橋国保医療年金課長","answer":"この周知ですが、例えば一般減免という部分では災害等により生活が著しく困難になったときなど、申請に基づき保険料を減免または免除をいたします。例えば、東日本大震災の関係ですとかそのような部分が関係してまいります。","voiceIndex":12,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"３７件というその方というのはどんなことで免除になったのかという理由と、あと失業とか廃業とか、著しく収入が減ってしまったときというのも対象になるのではないかと思うのですけれども、そういう場合の減額・免除というのも実際は行われているのか、その点についてもお聞かせください。","respondent":"三ッ橋国保医療年金課長","answer":"１０番目のところで「医療保険制度の充実」というものがございまして、保険者への財政支援と被保険者の保険料負担軽減策の拡充の中で国庫負担金の割合や調整交付金の財政調整分を別枠とするなど、国庫負担を充実させ、国保財政基盤を強化拡充すること、また。","voiceIndex":14,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その子どもの問題は、本当に均等割が２０１７年度の均等割でも１人当たり４万９,５００円ですよね。正常な状態ではないというのがずっと来ているわけです。けれども、そういうところからすると、やはり払える保険料にしていくということがとても求められているのではないかと思うのですけれども、２割、８割、そこの保険制度としてどうなのかというあたりもお聞かせいただけたらと思います。","respondent":"三ッ橋国保医療年金課長","answer":"再三申し上げておりますように、国保制度が成り立っていかないと、破綻してしまったら大変なことになっていきますので、何としても国民皆保険制度のセーフティーネットとしてこの国保制度というものは成り立っているので。","voiceIndex":16,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"品川区から先陣を切ってという形でやっていただきたいと改めて要望させていただきたいと思います。それをずっと今までも入れ続けてきたわけで、それでも全然財政は成り立ってどんどん基金が増え続けているという健全財政なわけですから、私は改めて法定外繰り入れは今までどおり入れて、さらに削減した分ももとに戻して引き下げるべきだということを求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-007"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"今の議論の中で、特別区長会からも国に要望が出されていると。医療保険制度の充実や多子世帯への支援ということで要望しているとのことですが、この返答というのは何か返ってきているのか伺いたいと思います。","respondent":"三ッ橋国保医療年金課長","answer":"今回の国からの返答と申しますのは、特にこうですという回答が来ているわけではございませんが、今回の激変緩和がその一つなのではないかと考えております。","voiceIndex":20,"id":"exchange-008"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"先ほども２割の方が滞納していることが問題だと、正常ではない状況ではないかということでしたが、品川区は、先ほど制度が成り立たなくなってしまう、だから一人一人ご理解いただきながら払ってもらうと。ですけれども２割の方が滞納しているという中で、要は保険制度としてやはり問題、そして正常ではない、そういった捉え方について区はどう考えているのか、改めてお聞かせください。","respondent":"三ッ橋国保医療年金課長","answer":"したがいまして、今回の平成３０年度からの財政運営の安定化ということで、東京都が保険者に加わって財政運営の責任主体となっていく、それも一つの動きと私は捉えておりまして、やはり一人一人の気持ちもそうかもしれませんけれども。","voiceIndex":22,"id":"exchange-009"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"そういう国に対して要望をし続けていくというのはなかなか大変なことだと思うのですけれども、やはり都からの要望なしには私たち区民の思いは届きませんので、ぜひそこは強く引き続き要望していっていただきたいです。子どもの均等割、私もこの間国保をいろいろ勉強しているさなかですけれども、１人子どもが生まれると４万９,５００円の均等割がかかっていたというのも初めて知ったのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問","question":"結論を出すということでお願いします。その結論としては、不採択ということでお願いいたします。考え方としては、今最後に理事者からご答弁がありましたがその部分と、国民健康保険自体が国民相互扶助、皆保険という制度、そこのところの兼ね合いからも、それから都道府県化をこれからまた進めていく中で、方向性も出ているということで、不採択ということでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-011"},{"speaker":"若林委員","kind":"質問・要望","question":"そういう意味では、窓口のより丁寧な対応については、私も丁寧にしていただいていると理解はしておりますけれども、私もごく一部の方の対応しか知らないといえば知りませんので、滞納者が２割いらっしゃるということで、より一層の丁寧な対応、またそういう方たちのために免除でありますとか、また短期証という制度もありますので、ここら辺もしっかり皆保険。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"結論を出すということで、採択でお願いしたいと思います。それで、大もとには安倍自公政権の社会保障解体路線があるわけですけれども、そういうふうな中だからこそ、最も区民に身近な自治体から、できるところから区民の負担を下げていくというところで、ぜひやるべきだし、そういう中で命を守る国保を命を奪う国保にしない、そのためにもこの請願に対しては採択ということでお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":30,"id":"exchange-013"},{"speaker":"大倉委員","kind":"質問・要望","question":"本日結論を出すということで、態度としては不採択でお願いします。お話も聞かせていただく中で、区としても都道府県等いろいろなところにしっかりと求めていく、特別区長会からもさまざま求めているところですが、まずは進めていくべきところを進めていって、持続可能なサービス提供をしっかりとしていくのだという視点でしっかりとやっていっていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-014"}]},{"id":"topic-02","title":"平成３０年請願第８号 国保料引下げと過酷な取立て中止を求める請願","agenda":"平成３０年請願第８号 国保料引下げと過酷な取立て中止を求める請願","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もうあそこの２０１１年のところから本当に、毎年すさまじい値上げがされ続けていたわけなのです。そういうのは私は東京都の滞納整理マニュアルという、国のほうでもそれをつくるよう指示を出していて、それに基づいて東京都もつくっているし、それに基づいて東京都のほうからも指導がされているのではないかと思うのですが、そこら辺のところがどうなっているのかを１点お聞かせいただきたいのです。","respondent":"三ッ橋国保医療年金課長","answer":"一方、東京都はそのようにいろいろ厳しい係長の手腕などが細かく書かれていると思いますが、区の中につきましては、そのような詳細なものではなく、やはり収納率は保険料の財政基盤となっていく部分ですので。","voiceIndex":39,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、私はこの窓口の相談が、ただただ保険料をどうやって払ってもらうかというだけではなく、その方がなぜ払えないのか、生活実態がどうなっているのかという、そこを把握して親身になって相談に乗って解決のために、いろいろなところにもつないでいく、そういうスキルも持っていくという窓口の相談対応にぜひしていただきたいと思うのですけれども、その点が１つです。","respondent":"三ッ橋国保医療年金課長","answer":"ただ、解決方法は何か見出さなければいけないと思いますので、何とかして丁寧に説明をしていって、なおかつ一番いい解決方法、もちろん保険料を支払っていただくのが国保としてはいい解決方法だと思いますけれども、ただ、実態としてどの程度支払えるのかを勘案していかないと。","voiceIndex":41,"id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どうやって保険料を回収するかという地点からだけ行くとなかなか難しい、そこにノルマがあるということになってしまうと余計難しくなってしまうと思うのですが、生活の状況を聞いて、なぜ払えなくなったのかというあたりは、本当に相談に乗ってくれるよ、国保医療年金課も変わったねという感じになれば、それはそんなに難しくないと思いますので、そこら辺の気持ちですね、姿勢。","respondent":"三ッ橋国保医療年金課長","answer":"私どもに関しましては、先ほど申し上げましたように、差し押さえ禁止に係る給付金も預金口座も振り込まれた場合というのは、預金債権に転化するという考え方に基づき、今現在のところは法令を遵守して適正な滞納処理に努めてまいりたいと考えています。","voiceIndex":43,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"収入がそれ以下だということをつかんでいながら差し押さえるというのは、私はやり過ぎだと思うのですけれども、そういうところはいかがでしょうか。最低生活費は残さなければいけないというのが国税徴収法で１人当たり１０万円、１人増えるごとにプラス４万５，０００円ということですから、それ以下の生活費の人も差し押さえるのかということを私はずっと聞いているのです。その点はいかがでしょうか。","respondent":"三ッ橋国保医療年金課長","answer":"先ほど申し上げましたとおり、判例や法令等いろいろありますけれども、適切な滞納処理に努めてまいります。法令違反はしないのがもちろん大原則ですので、そのあたりにつきましては、きちんと対応しております。判例、法令を遵守して実施してまいります。","voiceIndex":45,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私が言っているのは、国税徴収法では１人当たり１０万円、それから１人増えるごとに４万５，０００円、それが最低生活費だからその分は差し押さえてはいけませんというのが国税徴収法なわけです。最低生活費は差し押さえないという国税徴収法を守るとしていただきたいというのが私の思いなのですけれども、いかがでしょうか。","respondent":"三ッ橋国保医療年金課長","answer":"国税徴収法に基づいて私どもは対応しております。","voiceIndex":47,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"ということは、最低生活費でも預貯金に入った場合は差し押さえ禁止財産の属性を継承しないということで、今までどおりやっていくということなのでしょうか。最低生活費しかないという人までもということなのですけれども。その確認だけお願いします。","respondent":"三ッ橋国保医療年金課長","answer":"差し押さえ禁止財産というものがあります。そのあたりきちんと法令にのっとってやっておりますので、その部分に関しましてはきちんと対応してまいります。","voiceIndex":49,"id":"exchange-020"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"厳しい取り立てにかかわるかなと思うのですけれども、滞納者に区から送られてくる封筒ですが、どれだけ滞納しているかによって色が違うのでしょうか。驚くほどの真っ赤で、滞納していることが分かるような封筒で来るのです。その封筒の色、少し細かいことかもしれないのですけれども、そういうものは何でどういうふうに決められているのでしょうか。","respondent":"三ッ橋国保医療年金課長","answer":"どのようにして決めるかと申しますと、課の中で検討して、今回は黄色、今回は赤、普通の催告のときにはこの色という形をとらせていただいております。","voiceIndex":51,"id":"exchange-021"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"差し押さえもそうなのですけれども、驚いて来させるという、このやり方というのは自治体のやることなのかなとやはりすごく感じるので、そこはもし改善が可能なのであればやっていただきたいなと思います。それが多ければそれだけ対応していくのも大変なのかなと思うのですけれども、そこの人数、平均がわかれば教えていただきたいです。","respondent":"三ッ橋国保医療年金課長","answer":"今回の一人当たり何件か、区の職員の対応ですけれども、今滞納整理関係の職員が１６名程度おりますので、先ほどの滞納件数に割り戻しました部分が１人当たりの件数となります。ただ、１人当たりというノルマは課してはない状況で、グループ制をつくっております。","voiceIndex":53,"id":"exchange-022"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"封筒の色も相談のきっかけというのはわかるのですけれども、やはり滞納されている方というのは滞納している、払わなければいけないという自覚があると思うのです。だから、払わなければいけないけれども払えない、どうしたらいいのかと抱えているものを出しやすいように、やはり自治体としてはしていくべきだと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"本日結論を出すということで、まずはお願いいたします。考え方として、先ほどの説明にもありましたが、保険料自体が国保の財政基盤であるという点を考えても、徴収についてはこれからもしっかりやっていただきたい。当然事情によって個別対応している、その点につきましては、これからもしっかりやっていただくということを前提にしまして、不採択ということでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-024"},{"speaker":"若林委員","kind":"質問・要望","question":"請願項目の１については、先ほど要望も含めて言わせていただきましたので、そのとおりです。２については、いずれにしても先ほどと同じになりますけれども、皆保険制度を維持するために保険者もルールにのっとって適切、適正に保険料を徴収する努力をする、その一環として被保険者の方の気持ちや生活実態にもしっかり寄り添っていただいてということも引き続き要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"結論を出すということで、採択でお願いしたいと思います。とにかく命がかかった問題ですので、そこのところは親身になってやっていただくということでよろしくお願いしたいと思いますし、国税徴収法の最低生活費は差し押さえないというところでぜひやっていただきたいということを改めて求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-026"},{"speaker":"大倉委員","kind":"質問・要望","question":"理由としては、負担の公平性という部分が大前提としてある中で、先ほども述べましたが課題はいろいろある中で、しっかりと将来的に持続可能なサービスの提供をするためという部分では仕方ない、やむを得ないところであるので、そこを行っていただくのと、また請願項目の２については、先ほどもお話の中で一人ひとり丁寧に対応していくということと生活の調査や実態の話というのはなかなか難しいけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-027"}]},{"id":"topic-03","title":"平成３０年陳情第３号 荏原地域に障害者施設の整備に関する陳情","agenda":"平成３０年陳情第３号 荏原地域に障害者施設の整備に関する陳情","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"毎回申し上げていますけれども、やはり本当にこの陳情を出された方々が委員の皆さんにもっと言いたい、聞いてもらいたいと、そういう思いで意見陳述を申請しているわけですから、ぜひ私は審査の前に聞いていただくというのが当然だと思うのです。そういうふうなところで意見陳述を求めているわけですから、ぜひ冒頭に意見陳述を受けてそれで審査をするという形にすべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"特に荏原東地区が真っ白で何一つないという資料が出されたので一目瞭然という状況になったと思うのですけれども、そういう中で今回、福祉計画のご報告がこれからあると思うのですけれども、それを出される中でどういうふうにして具体的にいつまでにどんな施設をどのようにここに増設していくかという具体的なところはどう考えられているのかについて、お聞かせいただきたいと思います。","respondent":"中山障害者福祉課長","answer":"就労継続支援と、それからグループホームというのも地域で生活するというところでは大切だと思っていますので、この２つについては特に開設を目指していきたいと考えているところです。","voiceIndex":71,"id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"目指していくというのは、ここにも書かれていますし、そういう方法だというところはわかるのです。でも目指すという、こういう認識になったのはいつからですか。今回初めて荏原地域にああ、ないのだなというふうなことで、これは建てていかなくてはいけないなと思ったのか、いつそういうふうな方針というか、認識になったのでしょうか。これはもうずっと全くないままなのですから、ずっとないわけです。","respondent":"中山障害者福祉課長","answer":"そういったことをトータルに考えますと、やはり障害者の施設も地域のバランスを考えながら、特に就労継続支援とかグループホームは整備ができるといいだろうというふうなことを考えまして、今回初めて計画のほうにもこのような形で載せさせていただいたところです。","voiceIndex":73,"id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"荏原の西にも東にもそういう就労継続支援Ｂ型やグループホームが全くずっとなかったけれども、荏原の地域にやはり増設していかなければいけないという認識と方向性、計画を立てたのは今回の障害福祉計画が初めてということなのかということを、もう一回確認をさせていただきたいのが一つです。","respondent":"中山障害者福祉課長","answer":"就労継続支援Ｂ型のほうになりますが、これはやはり特別支援学校の卒業生の見込みもあわせて見ていく必要があると考えております。","voiceIndex":75,"id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"金子山はたしか男性しか申し込みができなかったではないですか。そういう点で言えば、そういうところに女性は申し込むことができなかったわけですから、グループホームの需要をきちんと把握するということがまず必要なのではないかと思うのですけれども、そこら辺のところはどう考えられているでしょうか。","respondent":"中山障害者福祉課長","answer":"ただ、グループホームの中には民間で運営をしているグループホームもありまして、そういうところはなかなか区の調整会議のような形はできておりませんので、実際には区立のグループホームとそれから品川総合福祉センターと福栄会の持っているグループホームについては。","voiceIndex":77,"id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それでいいのかと思うのです。だって、そういうふうなことでなかなかグループホームができてこなくて、グループホームの整備率というのは２３区で最低レベルという状況になっているわけですから、これはやはり品川区が主体的に目標を持って、具体的にどこにどういうふうにつくっていこうかというところを持たない限り、私はできないのではないかと思うのですけれども、その点はどうでしょうか。","respondent":"中山障害者福祉課長","answer":"やはり今現在区内にあるグループホームは、定員で７７人分という中であきがそうそう出るわけではありません。","voiceIndex":79,"id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"あきが出ないからこそそういうふうに公平、公正な仕組みをぜひつくるべきではないかと思うのですけれども、その点が１つです。それから、今課長からは林試の森隣のところについては課長として要望をしていくということで確認をさせていただいてよろしいでしょうか。ぜひ強く求めていただきたいと思います。それから、荏原第四中学校跡のところは今答弁がなかったと思うのですけれども、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"ただ、それと実現するかどうかというところはやはりもう少し全体の調整が入るので何とも言えないところだと考えております。","voiceIndex":81,"id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"グループホームを全体で何人が希望しているかというところは、区では現在把握していないということになるのでしょうか。それから、とにかく林試の森隣はほぼ購入するという方向で動いているわけですから、そこのところには一番身近なところでそういう方針を立てて、思いを持っている区民のところの課長が言わなければ、課長から要望が出なければ企画調整課長はなかなかわからない状況があると思うのです。","respondent":"中山障害者福祉課長","answer":"この間も特に荏原地域に障害者施設が必要だということは声は上げてきておりますので、そのときどき、例えば土地の当て等があれば相談という形でこちらにも声はいただける状況であると考えています。","voiceIndex":83,"id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"相談の中で２９名というところなのですけれども、今回の計画の中でも障害者のほうはアンケート調査をしませんでしたので、そういう要望はなかなかつかめないというところがあったと思うのです。私はそういうふうなところできちんとどれだけの要望があるのか、需要があるのかということをつかまないとどれだけつくったらいいのかというところもなかなか見通しがつかないと思うのです。","respondent":"中山障害者福祉課長","answer":"就労継続支援Ｂ型については、特に区として単独で補助をしているものはございませんが、建てるときに国や東京都の補助金があります。","voiceIndex":85,"id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"グループホーム金子山も品川区が土地を取得して、それで建設費もこれだけ補助を出して、そして福栄会に委託をしたという形ですよね。そういうところで、私は品川区が主体になって土地も取得をして、そして建設費も補助を出しながら、事業者を公募する、さまざまな事業者を品川区に入れていくという形にぜひしていただきたいと思うのですけれども、その点どうでしょうか。","respondent":"中山障害者福祉課長","answer":"ただ、区として施設を運営するとき、例えば指定管理をするときに今回の新施設等も全国的に公募もかけましたし、特定の法人だけに頼ってということではなく考えていきたいとは思っておりますので、今後そういった当てがあったとき。","voiceIndex":87,"id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ということは、土地があったとしたら、区が主体になってグループホームや就労継続支援Ｂ型をつくって、そして指定管理者を公募してさまざまな事業者を入れていくという方針を持っているということで確認させていただいていいでしょうか。こんなに整備率が低いという状況ですから、もう少し本当に区が主体になってぜひつくっていただきたいと思っています。そのことについても改めてお聞かせください。","respondent":"中山障害者福祉課長","answer":"ただ、やはり必要だということは思っておりますので、補助金の制度もそうですし、あるいはそういう土地の状況なんかもよくリサーチしながら、何とかこの地域へ就労継続支援Ｂ型とグループホームの開設につなげていければと思っているところです。","voiceIndex":89,"id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこをぜひ逃さないでやってほしいと思います。もう何もかもやはり施設が足りないのです。そういう方には、それまで本当に他県でご苦労をかけているわけですから、ずっとそのままにしておくのではなくて、やはりその方の希望に応えるという形でぜひ私は区が主体になって、土地も探せば絶対にありますから、ぜひ土地も探して区が主体でやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-039"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"なので、課長ってそういう力もあるのだなと私は他県に行って感じたのです。ですので、林試の森のところももう進んでいるという実態もあるかもしれないのですけれども、やはりそこは本当に今障害があるというだけで家族一緒に過ごせない、暮らせないという実態を本気でなくそうというのであれば、それぐらいの課長の熱意で押していくということが必要なのではないかと思うのですが、その辺いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"そうした認識のもと、企画調整課とも話をしながら、最終的にどういう案になるかというのはこれから区のほうで決定をしていくべきものだと考えているところです。","voiceIndex":92,"id":"exchange-040"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ぜひ熱意を持って、私たちもそこは本当に支援していきたい、応援していきたいと思っています。区民の願いですし、障害があるというだけで当たり前の生活がこの品川で送れないということを一日も早くなくしていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-041"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ご本人ともお話はしていますし、質疑の内容から、意見陳述を受けないでこのまま採決で判断していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私も実際にお話もたくさん聞いていますけれども、その上で皆さんに訴えたいということで、陳述の文章も準備をして、当事者が見えているわけです。それを区民の声を聞かない、最後の最後まで声を聞かない。こんな品川の区議会のやり方で私は本当にいいのかと思うのです。準備してきているのに意見陳述を聞かないというのであれば、聞かない理由をぜひ教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-043"},{"speaker":"若林委員","kind":"意見","question":"今、自立支援協議会等も公開をされて、またこの問題については今年の所管事務調査の資料も出していただいて明らかにしていただき、また当事者の声も聞きながら審議を進めているところという認識でおりますので、意見陳述は結構だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":98,"id":"exchange-044"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"先ほども少しお話申し上げましたが、陳情者ご本人からもお話を伺っております。今回の福祉計画の中にもうたっておりますし、それから前回の委員会の中で偏在ということも出ておりました。その辺は踏まえておりますが、全体的な行政需要、土地の問題等の絡みもあるので、継続という形にさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-045"},{"speaker":"若林委員","kind":"意見","question":"同じく継続でいいかと思います。区の姿勢も非常に前向きに捉えているということで、今後計画も正式に立てられていく中で、また取り組みというのは引き続き注視をするという意味では継続で結構かと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":103,"id":"exchange-046"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は結論を出すということで、ぜひ採択をしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-047"},{"speaker":"大倉委員","kind":"質問・要望","question":"継続でお願いしたいと思います。これからいろいろな検討がされていく中で、しっかりと注視をしながらこれについては進めていっていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-048"}]},{"id":"topic-04","title":"平成３０年陳情第４号、品川区公式ホームページにおける障害福祉関連ページの充実を求める陳情","agenda":"平成３０年陳情第４号、品川区公式ホームページにおける障害福祉関連ページの充実を求める陳情","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"先ほども同じなのですけれども、やはり障害の団体の方がこういうふうな形で出されていて、そして、もっと言いたいことがあるのだと、ぜひ聞いてほしいということで準備をされてきているわけですから、その区民の声にしっかりと耳を傾けるというのは議員の役割として当然だと思うのです。ですので、審議の前に聞くほうが、より深い審議ができると思いますので、ぜひ審議の前に意見陳述を受けたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-049"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"去年の８月の厚生委員会の中でホームページ、すごく古い情報がそのまま載っていたということ、またクリックするとリンク先がなかったりということで指摘をさせていただいたときに、区のほうで見直していくという答弁があって、内容のチェックと修正をされたということなのですけれども、これはいつごろされて。","respondent":"中山障害者福祉課長","answer":"８月の時点でやはり古い情報があるというご指摘をいただきましたし、リンク先がなくなっているということもいただきましたので、リンク先につきましてリンクまでクリックして実際にきちんとつながるかどうかの確認、それからしおりを作成してそこを塗り替えて。","voiceIndex":117,"id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこら辺のところをもっと就労継続支援Ｂ型にしても生活介護にしても自立訓練にしても放課後等デイサービスにしても相談の事業所にしても、そういうふうな形で情報として欲しいというときに、すぐわかるものにぜひしていただきたいなと、私は思いますし、そういうご要望も伺っているのですけれども、そういうところではいかがでしょうか。","respondent":"中山障害者福祉課長","answer":"現在、心身障害者福祉会館のところから今、品川総合福祉センターのホームページに行けたというお話だったのですけれども、申しわけありません、少しそこは私は認識が違っておりまして。","voiceIndex":119,"id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そこから品川総合福祉センターのホームページに行き、そこの施設紹介というところをクリックすると、かもめ園、さつき、サンかもめ、福祉工場しながわと全部出てきて、「詳細はこちら」をクリックすると、かもめ園だったらかもめ園がどういう施設なのかを写真から施設からいっぱい出ているので全部見られるようになっているのです。すごく、そういうふうな情報があるといい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":121,"id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"わかりました。そういうふうなページにぜひしていただきたいと思うのですけれども。そういうところでは、この７団体だけを障害者団体ということで載せるというのもわからなかったのですが、そういうようなのも含めて、欲しい情報が得られる、そういうホームページを当事者目線でぜひ作っていただきたいと思うのですけれども、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"障害者団体のところは、今障害者団体登録というのを仕組みとして持っておりますが、やはり区が障害者団体として認識するには、７団体もそうですけれども団体登録をしていただかないとわからないということもありますし。","voiceIndex":123,"id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほど、どこにどう相談をしていけばいいかというときに、これは多分障害者福祉のしおりもそうだったような気がするのですけれども、ほかの区のところはしおりも身体、知的、精神、児童、難病という形で、指定特定相談支援事業所ではここの相談ができますよと丸がついていたりするのです。は相談。ぜひそういう中身に変えていただきたいなと思っているのですが、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"多分今委員おっしゃったことはここのところに主たる対象別みたいなマークがあると、そこから引っ張っていけるのではないかというご提案だと思いますので、最終的にどういう形で施設の情報を外部も含めてリンクさせていくかということも含めまして。","voiceIndex":125,"id":"exchange-054"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"いろいろと様々な区のホームページを見ていたときに、実際問題そこの事業所に通っている人がどのような思いで通われているかというところで、これは練馬だったか、アンケートを全ての通所の利用者の方にとって、そのアンケートの結果も載せているのがあったのです。されていたら、そういうものも参考にしながら選ぶこともできるのかなと思ったのですけれども、その点はいかがでしょうか。","respondent":"中山障害者福祉課長","answer":"施設のほうの例えばＰＲということで、「施設など」のところからその施設のホームページに飛んだところで、自分のところはこういうことを大事にしていってこういう作業をやっていって、事業者の思いはこうですよというような。","voiceIndex":127,"id":"exchange-055"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"多分、今いろいろな、特に若い方とかはネットをすごくよく見ているではないですか。だから、いろいろな自治体のネットもすごくよく研究されていると思いますので、そういうところでの当事者の意見を聞いて、得たい情報が得られるようなホームページにぜひ改善をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-056"},{"speaker":"石田（ち）副委員長","kind":"確認","question":"ですので、やはり多くの方が使われているというところだと思いますし、そこも区も認識はされていると思うのですけれども、ホームページが充実、十分でないというところからみると、まずは一度区に問い合わせてくださいというのが基本スタンスにあるのかないのか、そこを確認させてください。","respondent":"中山障害者福祉課長","answer":"区としては、一律に何でも区に相談してくださいというつもりではもちろんないのですけれども、ただ、例えば今回も身体障害者手帳、愛の手帳のところで、もう少し申請方法だとかそういうことも加えてもいいかと思ったところではありますので、できるだけ情報を載せつつ。","voiceIndex":131,"id":"exchange-057"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"先ほど広報広聴課のほうのセキュリティーとかの関係でといろいろおっしゃっていたのですが、ホームページは障害者福祉課の中だけで更新できないようになっているのですか。ホームページの更新の仕方は、簡単にできてしまうものとそういうふうに入り組んでいるというか、ほかの課もかかわらなければいけないものとかが結構あるのでしょうか。","respondent":"中山障害者福祉課長","answer":"私、実際にホームページの手続をしたことがないので、申しわけありません、詳しくはわからないのですけれども、一応セキュリティー上民間のところにリンクを張ることはできないと聞いています。","voiceIndex":133,"id":"exchange-058"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ぜひそういったほかの課とも連携が必要なところは、こういった陳情も２度にわたって出されているというところからも一緒にやっていただいて、とにかく充実に向けて、障害者が必要とする情報を得られるというところをやはり念頭に置いていただく。それにはやはり当事者の声を聞いていただくというのが一番だと思いますので、進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-059"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私は先日代表者の方からご連絡をいただきました。今日は残念ながらご都合がつかないということだったのですけれども、内容、お話を聞いて、先ほど質疑の中でそのお話を聞いた内容は大体網羅されているのではないかと思いますので、意見陳述に関しては、今回しないでということで進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":137,"id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"私はぜひ意見陳述を受けたいと思います。私たちはあくまでも想像の部分でやっていて、自分たちが気がついたことしか意見は言えないと思います。やはり障害の当事者の方、また親御さん、そういうところでの切実な思いをしっかりと受けとめていくというためにも、意見陳述をぜひ受けてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":139,"id":"exchange-061"},{"speaker":"鈴木（真）委員","kind":"質問","question":"先ほども申し上げましたが、陳情の代表者の方からお話も伺いましたし、この陳情の内容、それぞれ判断をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-062"},{"speaker":"若林委員","kind":"質問・要望","question":"これは要望させていただいて。いかに全体の量と質を担保していくかというのは非常に大変な作業になると思いますので、しっかりととにかく区民、利用者の方、情報を得られたい方の立場に、目線に立って、全体の方針をしっかり立て、計画し、具体化をしてというところにまたしっかり持っていってほしいと思いますので、そういう意味では今後区の対応を見続けていきたいという意味での継続です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-063"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"結論を出すということで、採択でお願いしたいと思います。区のほうとしても、８月に厚生委員会で議論がされて、その後内容をチェックをされて修正もされたという点では、さらに今回のこういう陳情を受けて、より充実をしていっていただきたいと思います。この陳情で出された中身というのは、全くそのとおりだと思いますので、ぜひ採択をしていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-064"},{"speaker":"大倉委員","kind":"質問・要望","question":"お話の中にもありましたが、手直しできるところはもうどんどん随時手直しをしながらやってきているというところと、一方で先ほどもお話にありましたが、セキュリティーの問題、民間などリンクを張る先なども工夫していきながらやっていきたいとか、構成の関係で全体的にホームページを変えていくというのは難しいという部分でも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":146,"id":"exchange-065"}]},{"id":"topic-05","title":"地域福祉計画改定に伴う区民アンケート調査結果報告","agenda":"地域福祉計画改定に伴う区民アンケート調査結果報告","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"意見","question":"この地域福祉計画の策定が来年度というのは４月以降ということですね。そうすると、どんなメンバーでどれくらいの回数、おおよそ何月というところと、それからあと地域福祉計画策定委員会というのは、また公開の場で、傍聴とかも可能なのか、その点についてもお聞かせください。","respondent":"大串福祉計画課長","answer":"合計で５回開催を予定しております。その中でテーマごとに区切った形で委員のメンバー、顔ぶれ等々も変えていければと考えているところです。公開あるいは傍聴の関係です。これは座長の方ともよくご相談させていただき、検討させていただければと考えているところです。","voiceIndex":152,"id":"exchange-066"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすると、４０名程度で五、六月ぐらいから始めるということですと、おおよそ初めのメンバーみたいなのがどういう方というのは決まっているという感じですよね。そこら辺のところも少し、地域の方がどれくらいとか、どういうところでどういうふうに選ばれていくのかというところと、それから座長はどなたがされるのかということについてもお聞かせいただきたいと思います。","respondent":"大串福祉計画課長","answer":"こちらの方にお願いしようかと考えています。それから、会議の公開といったところにつきましてもやはり委員長ともご相談しながら考えてまいりたいと考えています。","voiceIndex":154,"id":"exchange-067"},{"speaker":"大倉委員","kind":"質問・要望","question":"このアンケートについて予算はどのぐらいなのか教えていただきたいのと、男女いろいろ年齢もさまざまな方たちから意見を聞いているのですが、調査結果を見ていくと、男女別とかに分かれていなかったり年齢が分かれていなかったりするのですが、そこまでやらない理由、結構男性と女性とか年齢の違う方で意見が違ってくるのかなという部分では。","respondent":"大串福祉計画課長","answer":"これはあくまでも今の段階では案というか速報値的な取り扱いになっておりますので、今後その属性等々を踏まえて、もう少し詳しいクロス集計等をしながら次年度の策定委員会ではお示しをしていければと考えているところです。","voiceIndex":158,"id":"exchange-068"},{"speaker":"大倉委員","kind":"確認","question":"今案ということで、先ほどもおっしゃっていましたけれども速報値だから、例えば設問８だと男性だとこういう意見が多かった、女性だとこういう意見がある。年齢構成だとこういう意見が若い人たちに多いけれども、割と年齢の行った方だとこういう意見だったという集計はやっていくということでいいのでしょうか。確認だけお願いします。","respondent":"大串福祉計画課長","answer":"例えばこの地区で男性で４０代の方だったらどういった形のご回答になっているかというところもクロス集計をしながら、属性的なところはもう少し分析をしていければと考えていますし。","voiceIndex":160,"id":"exchange-069"},{"speaker":"若林委員","kind":"質問","question":"先ほどのご答弁で、４０名ということで、一堂に会するわけではなくテーマごとに開催するということで、いわゆる全体会議があって、小委員会みたいなのがあって、それを積み重ねて全体会議を５回ぐらいやってというのが最初のイメージだったのですけれども、そういうことでいいのかということと、ではそのテーマごとというのはどういうテーマなのかというところをお聞きしたい。","respondent":"大串福祉計画課長","answer":"この４０名全体でそろうのがやはり第１回目の策定会議のときで、この計画策定の趣旨であるとかそういったところをご説明しながら、その中でまた有効な議論ができればと考えています。","voiceIndex":162,"id":"exchange-070"}]},{"id":"topic-06","title":"第５期品川区障害福祉計画・第１期品川区障害児福祉計画の素案","agenda":"第５期品川区障害福祉計画・第１期品川区障害児福祉計画の素案","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"パブリックコメントもこれだけ１６４件の意見が出されて、その反映というのが今の２点だけということなのでしょうか。このヒアリングをされた団体が１０団体というのは前回よりも多くなっているのか、前回はどれくらいの団体からヒアリングをされたのかということも教えていただきたいのと、ヒアリングされた中で出された意見というのはまとめられているのでしょうか。","respondent":"飛田障害者施策推進担当課長","answer":"自立支援協議会のほうですが、今回３回というところで、前回も答弁しましたけれども、少し今回計画をつくるに当たり非常に少なかったことを反省しまして、次回計画のときは少し多目に協議会を開いていきたいと考えております。","voiceIndex":171,"id":"exchange-071"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところで１年間どうだったのか、実績もしっかりと踏まえて翌年にそれをどう生かしていくかというＰＤＣＡサイクルでやっていくということになると思うのですけれども、そこのところの毎年の実績とか評価というのは公表はされるのか、そこのところの確認を１点お願いしたいと思います。２３区の中でも実施している区のほうが多くて、大半だと思います。","respondent":"飛田障害者施策推進担当課長","answer":"説明会のことなのですが、今のところ説明会の実施は考えていませんが、また親身になって各団体や各個人の意見、窓口にいらっしゃったときに、丁寧な対応をして、また声を聞いていきたいと私も考えております。","voiceIndex":173,"id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当にさまざまある、一つひとつ見ていくと切りがないくらいいろいろな問題が障害福祉のところにあると思います。それからあと、３ページの障害者の団体のところでは、７団体のみと連携するのではなく、多くの障害者団体等と平等・公平に対応および連携し、その旨記載してほしいという意見に対し、ここでいう障害者団体とは団体を特定したものではありませんというふうに書かれています。","respondent":"飛田障害者施策推進担当課長","answer":"今回、難病等のところですが、なかなか難病の方が実際に外に出られなかったり、そういう支援で何が必要かというところを直接ご本人とはお話できないところがありますが。","voiceIndex":175,"id":"exchange-073"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"放課後等デイサービスのほうは平成２９年度の３１５人から４８０人に増えていて、日中一時支援事業が平成２９年度の４,８２８人から８,０７３人に、２倍まではいかないですけれどもかなり増えているのですが、日中一時支援事業のほうが利用が高いと、多分そういうふうなのもここのパブリックコメントの中に書かれていたので、改めてお聞かせいただきたいと思うのですけれども。","respondent":"飛田障害者施策推進担当課長","answer":"日中一時支援事業のところですが、また今度平成３１年４月に障害児者総合支援施設もできますので、それを見込んでの数字をこちらには書いております。","voiceIndex":177,"id":"exchange-074"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"日中一時支援事業は月単位で直すとなると、これを１２で割ればいいという捉え方でいいのでしょうか。","respondent":"飛田障害者施策推進担当課長","answer":"そのようにお願いいたします。","voiceIndex":179,"id":"exchange-075"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"これは同じような形で、その前後とかも人数と日数というふうに書いてあるところが多いですよね。そういうふうに書いてもらったほうが、同じように通っている施設なのでわかりやすいかなと思ったのですけれども、その点お聞かせください。","respondent":"飛田障害者施策推進担当課長","answer":"こちらの通所支援施設のところの、５３ページの障害児通所支援のこちらの項目では、通所支援ということなので月単位で記入をさせていただいているというふうになります。こちらのほうは全部月で統一しています。","voiceIndex":181,"id":"exchange-076"}]},{"id":"topic-07","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"所管事務調査ということですから、委員同士の意見交換というのができるといいのですよね。","respondent":"石田（秀）委員長","answer":"そのとおりです。","voiceIndex":187,"id":"exchange-077"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうですよね。今回の都道府県化で、東京都が国民健康保険運営方針というのを出しているのです。この中で、本当に赤字補填分の法定外繰り入れはなくすべきというのが繰り返し出てくるわけなのですが、そういうところで先ほども議論になった法定外繰り入れをなくすということになると、その分保険料の値上げに置きかわっていくわけですから、本当にどんどん保険料負担が増える。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":189,"id":"exchange-078"},{"speaker":"若林委員","kind":"確認","question":"とりあえず質問になりますけれども、3)の特別区における調整についてというところで、括弧の「ただし」書きのところ、各自治体が独自に対応することも可能とするということで、少し２３区の中で動きがあるやに聞いた覚えがあるのですけれども、ここら辺は今どういう状況で、もしそういう対応が現実にあるとすれば、その内容とともに品川区としての考え方も一応確認はしておきます。","respondent":"三ッ橋国保医療年金課長","answer":"都政新報など新聞報道によりますと、特別区長会においては統一保険料方式を今まで継続してきましたけれども、統一保険料方式を原則としつつ独自も可という考え方に基づいております。今現在のところ、３区が独自という考え方です。","voiceIndex":191,"id":"exchange-079"},{"speaker":"若林委員","kind":"質問","question":"都政新報を読めばわかるのかもしれませんけれども、区が捉えていらっしゃる、そこに出てこない情報もあると思うのですが、この３区がどういうふうに具体的に、要するに独自の設定をどういうふうにされて、それはなぜなのかというのも押さえていたら教えてください。","respondent":"三ッ橋国保医療年金課長","answer":"特別区は先ほど来申し上げておりますように、２３区全体としては６年間の激変緩和措置と、国に基づいた方向性をとってまいりますけれども、今回江戸川区はそれよりも早く法定外繰入金を解消するという考え方です。４年間というようになっております。","voiceIndex":193,"id":"exchange-080"},{"speaker":"鈴木（真）委員","kind":"質問","question":"所得の水準が今出たのですけれども、例えば品川の場合はどのように判断していいのかというのと、逆に支払いの額でいった場合に、医療費の支払いというのもやはり各区それぞれ大分違うと思うのですが、その辺のところを考えたときに品川はどういうふうに考えたらいいのでしょうか。","respondent":"三ッ橋国保医療年金課長","answer":"こちらは都内全体の平均を１といたしますと１.０２ということで、医療費の水準が高い部分です。一方、１人当たりの所得につきましては、２３区の中で９位です。この１人当たりの所得というのも、やはり品川区は全体よりも高いです。","voiceIndex":195,"id":"exchange-081"},{"speaker":"鈴木（真）委員","kind":"確認","question":"すると、品川区としてはやはり統一保険料方式に入ったほうがそういうときにいいという判断なのですか。そこだけもう一回確認します。","respondent":"三ッ橋国保医療年金課長、石田（秀）委員長","answer":"そちらの考え方に賛同している状況です。皆さん、いろいろご意見をください。ただ、こちらにつきましては皆さんよくご存じのように議案がもうすぐ出てまいります。議案について予想されているものも新聞上等さまざま出ておりますが、そのために厚生委員会も開かれます。","voiceIndex":197,"id":"exchange-082"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"都道府県化ということで、今までも先ほどの東京都からの指導みたいなのがあったと思うのですけれども、そういうのはもっと強力にされてくるというところはあるのか。特別交付金も同じような形でこれからも続けられていくのか。そこら辺の見通しについてお聞かせください。","respondent":"三ッ橋国保医療年金課長","answer":"東京都からの指導ですけれども、こちらは今までどおりの状況で、これから厳しくなるかという部分につきましては、特に厳しくなるというのは聞いておりませんので、恐らく大丈夫なのではないかと推測しております。交付金につきましては、これまでどおりと考えております。","voiceIndex":200,"id":"exchange-083"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3500#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":75322,"voices":208}},{"id":"h30-20180227-8","meetingId":"h30-cm02","date":"2018年2月27日","dateIso":"2018-02-27","committee":"建設委員会","time":"午前１０時００分～午後 ３時３０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を98件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"中延一丁目区営住宅および従前居住者用住宅の竣工","agenda":"中延一丁目区営住宅および従前居住者用住宅の竣工","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"スケジュールのところで、新規居住者の募集は終わった。入居はいつからなのか、１点お伺いします。それと、料金のほうですが、使用料がここに出されていますけれども、減額というのがあると思うのですけれども、実際にどれぐらいの方がこの住宅ですと減額対象なのか、減額になるとどれぐらいになるのかをお伺いします。","respondent":"長尾住宅課長","answer":"新規募集によって入居される方の入居予定時期になりますけれども、順調にいきますと、４月の末あたりから入居は可能かと考えております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"料金というのは、区で設定できるものなのでしょうか。それとも、何か基準で区では勝手に決められないというふうになっているのか、そちらをお伺いします。それと、別紙１の間取りのところですけれども、区営住宅と従前居住者用住宅の入口のところなのですけれども、これは別になる感じなのでしょうか。その辺をお伺いします。","respondent":"長尾住宅課長","answer":"は利便性係数というものがありますが、そちらについては区の方針を策定した上で、それにのっとって今までも使用料を決めてきております。こちらの利便性係数の算定の基準につきましては、都営住宅の算定基準なども参照しながら区のほうで決めております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"確認","question":"料金のことに関しては、いろいろ基準がある中で、品川区が係数などを設定して決めていると理解したのですけれども、法令等の基準を参考にして品川区で決めているということでよろしいのかという確認が一つです。それと、自治会のところですけれども、従前居住者用住宅の方も新たに一緒になるということで、そこら辺は自治会としてはどういうふうになるのかなというのがちょっと気になるので教えてください。","respondent":"長尾住宅課長","answer":"入居されてからどういった形での活動の協力があるのかとか、そういったところは調整していくことになると考えております。","voiceIndex":9,"id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"資料なのですけれども、差替え前とどこが違っているのですか。すみません、それがわからなかったので、まずそれを教えてください。","respondent":"長尾住宅課長","answer":"本日机上配付させていただきました資料の中で、変更を加えている部分が、別紙１と別紙２の区営住宅の専用面積の数値になります。配付資料の１枚目の中段部分に、住戸数が記載しておりまして、その中の内訳にそれぞれの住戸のタイプ別の面積を記載しております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"本日配付されたものの数値が合っていますよということでいいですね。それで、従前の方、実際は１８世帯で、本来は３１世帯あったという意味ですか。建替え前の住民は、１８世帯となっているのですけれども、もともと予定していた世帯というのは何世帯あって１８世帯になったのか。そういう理解でいいのか。","respondent":"長尾住宅課長","answer":"区営住宅のもともとの戸数は２１戸でした。仮移転時は１９世帯の方が住まわれておりました。仮移転中に１世帯の方がお亡くなりになりまして、残りの１８世帯全てが今回戻り入居されるということになります。","voiceIndex":13,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"１８世帯の方々で、ほとんどが該当するという激変緩和の措置をされる方ということなのですが、その方々の最高の金額、月４万円だったかな、かなり大幅に上がる方がいらっしゃるのではないかなと思うのですね。その方々のご納得感というか、その交渉はどういう形になって、誰が担当されたのか。説明にあたっては、管理者なのか、それとも区の職員がきっちり話をされているのか、そこら辺はいかがですか。","respondent":"長尾住宅課長","answer":"こちらの新しい使用料の設定の概要につきましては、昨年の１２月に戻り入居者の方に対しての説明会というのを行いまして、私ども住宅課の職員、あと指定管理者と木密整備推進課で主に説明をいたしました。","voiceIndex":15,"id":"exchange-006"},{"speaker":"いながわ副委員長","kind":"質問","question":"ちょっと何点かお伺いしたいのですが、区営住宅の件はそれはそれでいいとして、従前居住者用住宅というのは、ほかにソレイユ戸越も同じような役割を担っていると思います。ここの従前居住者用住宅の入居というのは、いつから始まるのかということ。優先順位としては、やはり今２９号線とかいろいろ都市計画道路の部分であると思うので、どういう扱いで入居されるのかというのを教えてください。","respondent":"高梨木密整備推進課長","answer":"入居の開始日なのですけれども、この２月末に竣工して、３月から入居が開始できる状態、建物として、設備としてはその準備が整うのですが、あとはいつから入居するかというところについては、今入居を希望されている方と調整をしています。","voiceIndex":17,"id":"exchange-007"},{"speaker":"いながわ副委員長","kind":"意見","question":"ちょっと恒久的というのが、もちろんソレイユ戸越も恒久的に住まわれている方がいらっしゃるのですが、まちの更新、更新という言い方はちょっと語弊があるかもしれないのですけれども、どんどん今まちがきれいになっていくというか、整備されていっている状況の中で、やはりすぐ不動産が見つからないで、こういうところに行って、家が建つまで、だから。","respondent":"高梨木密整備推進課長","answer":"区としましても、また、そういう住宅があるということをしっかり知っていただくということで、広報についても啓発に努めてまいりたいと、このように考えております。","voiceIndex":19,"id":"exchange-008"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"先ほど広報というお話がありましたので、ぜひこういう制度があるということは明確にして、その該当地域というのですかね、そういうところにしっかり広報するような感じ、あと欲を言えば、例えば恒久的も大切なのかもしれないですけれども、おそらく家賃もそんなに高い家賃ではない、近傍と比べれば安い家賃だと思うのですが、地域の不動産の団体と連携をとって。","respondent":"高梨木密整備推進課長","answer":"建替えのプランの最初の段階で知っていただく。工務店に相談に来た段階で知っていただくとか、そういったことでもつなげられるような方法について努めてまいりたいと、このように考えております。","voiceIndex":21,"id":"exchange-009"}]},{"id":"topic-02","title":"地震に関する地域危険度測定調査（第８回：東京都）結果報告","agenda":"地震に関する地域危険度測定調査（第８回：東京都）結果報告","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"火災危険度で、火災の延焼時間を６時間から１２時間に変更した理由は何なのでしょうかというのが一つです。それと、災害時活動困難度というのを総合危険度に加味するという変更がありましたが、それが総合危険度のみに加味する変更の理由も伺うと同時に、災害時活動困難度とはどのように算定されるのでしょうか伺います。","respondent":"高梨木密整備推進課長","answer":"続きまして、困難度について、なぜ総合危険度のみに加味するのかということについてなのですが、こちらについては、東京都から個別の説明はございませんでしたが、総合危険度といって、火災だけではない、建物倒壊だけではないといった総合的に危険度を算出する際に。","voiceIndex":27,"id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"研究したいと思います。今回、西大井三丁目、七丁目が出てきましたけれども、ここは第一種低層住居専用地域なのですよね。区内でもそんなにないのですけれども、閑静で、大きな敷地の屋敷が並ぶところなのですけれども、これがなぜ危険地域になるのかというのは、ちょっと生活実感と余りにかけ離れている感じがするのですけれども、このような結果になぜなるのでしょうか伺いたいと思います。","respondent":"高梨木密整備推進課長","answer":"これは何を意味するかというと、先ほど災害時活動困難度の算定方法については説明いたしましたが、要するに、災害時の救援や逃げるために必要な道路であったり、防災公園であったりというものがほかの区域に比べて不足しているということが言えるのではないかと考えております。","voiceIndex":29,"id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"西大井、おそらく想像しますと、６ｍ道路が余りないのではないかと思うのですけれども、ただ個々の住宅はしっかりした大きな敷地で、そんなに延焼がというようなところではないと思うのですよ。６ｍ道路が少ないということなのか、ちょっとそこら辺をもう少しお伺いしたい。","respondent":"高梨木密整備推進課長","answer":"細かな計算の中身であったり、データについては東京都のほうに最終的には聞いてみないと、区の調査ではございませんので詳細なお答えはできませんが、委員がおっしゃるとおり大井・西大井地区というのは、６ｍ以上の広幅員の道路が少ないということと。","voiceIndex":31,"id":"exchange-012"},{"speaker":"安藤委員","kind":"質問","question":"いわゆる６ｍ道路に１４０ｍより遠い消防活動困難地域という区域がありますけれども、この西大井三丁目、七丁目というのは、消防活動困難地域に入っているのでしょうか、ちょっと伺いたいと思います。４ｍ道路はあるわけですけれども、こういった道路では消防車は入れないとか、または角を曲がれないとか、そういう実態、そういうふうになるのでしょうか、それをちょっとお伺いしたいなと思います。","respondent":"高梨木密整備推進課長","answer":"４ｍ道路についてなのですけれども、４ｍ道路で何も駐車車両とかがなければ、そのまま緊急車両等の通行もできる部分もあろうかと思いますけれども、やはり発災時、駐車車両もある、歩行者もいるといった中で。","voiceIndex":33,"id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回の資料にもありましたけれども、この調査の目的ということで、地震災害に対する都民の認識を深め、意識の高揚ということで、２番目には震災対策事業を実施する地域を選択する際に活用と書いてあるのですけれども、伺いたいのは、今回の結果で、区道ですけれども、３１号線という計画がもろ三丁目と七丁目に入っているのですけれども、これを区としては進める動機にお考えなのですか、伺いたいと思います。","respondent":"高梨木密整備推進課長、中村都市計画課長","answer":"４ｍ道路への消防車の進入につきましては、その４ｍ道路の曲がり角の状況とか、入ってくる消防車の規格等によっても異なると思いますので、ここで断定するようなことはできかねると考えております。ただ、今回の地域危険度の結果は、その結果が出る前から道路は既に計画としてはございましたので、直接これを理由に計画を進めるということではなくて、道路の計画そのものは防災性の向上という目的が一つある。","voiceIndex":35,"id":"exchange-014"},{"speaker":"安藤委員","kind":"意見","question":"それで、その数字だけをもって６ｍにしなければいけないとか、道路をつくらなければいけないというような進め方というのは間違っているし、やるべきではない。きちんとその地域特性に応じた住民の方のお話や意見を聞きながら進めていくのが防災対策ではないかというふうに思いますので、３１号線はちょっとやめてほしいというふうな意見はあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"ただ、その変わる中で、これをどう活かしていこうとするのか、あとは地域の状況によっては、なかなか解消が難しいという中で防災対策、これはちょっと担当が変わってしまうと思うのですけれども、防災対策をどういうふうにしていくのかと、ハードとソフトでこれを活用できるのではないかなと思うのですが、これをどのように防災意識を高めていくのに使われようとしているのか、お聞きしたいのですけれども。","respondent":"高梨木密整備推進課長","answer":"先ほどもご説明いたしましたとおり、現在、大井・西大井地区、大井七丁目を含めたところで木密整備推進課としても、地域の皆様と話し合いを進めているところです。","voiceIndex":39,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"実際、これは２月１５日に東京都が発表して、新聞報道は２６日ですよね。町会の中では、既にこの情報は流れているのですよ、町会に。すごいなと思ったのですけれども。１棟建っていたところに、７棟、８棟建っているわけですから。これはどうなのですか、そういうことはどこまで加味されているのでしょうか。それはどういうふうな数値にあらわれているのでしょうか。","respondent":"高梨木密整備推進課長","answer":"ただ、横並びで見てみると、まだまだほかのところよりも改善のスピードがちょっと遅いよねというような形で、しっかりと内容をわかっていただくような説明の仕方が必要だろうと考えているところです。","voiceIndex":41,"id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"そうすると、この数字の中には、最後の件なのですが、加味するのは難しいということなのですかね。それはいかがですか。","respondent":"高梨木密整備推進課長","answer":"そこに火が来たときに燃えるのか、燃えないのかという形を機械的に電算で処理しておりますので、ただ隣棟間隔が狭いと、隣の家との間隔が狭いと火が燃え移る度合いが高くなるという形で、そういった意味では危険度は高くなろうかと思いますけれども、ただ新しい建物ですので。","voiceIndex":43,"id":"exchange-018"},{"speaker":"西本委員","kind":"質問・要望","question":"この数字というのは、客観的に見る上でも大切な数字だと思っているのですね。なので、ランクづけというのもいろいろあって、意味合いがあるなと。割と危機感を持つとそれなりに皆さん気をつけますので、そういう形でこれを有効活用していただきたいと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"今のところ、直ちにというところなのですけれども、大きな屋敷が確かにミニ開発的な感じで分割されていくということは、どの地域でも結構見られてしまうのですけれども、そういうことになりますと、建物倒壊危険度の測定方法ですと、やはり建物量とかというのが出てきますし、今は危険度が上がらないかもしれないけれども、後々３０年等たってくると、それがどうなっていくのかというのは。","respondent":"高梨木密整備推進課長","answer":"ただ、だからといって、全ての地域で、地区計画の際に例えば敷地面積の最低限度をどのようにするのかといったところは機械的に行うのではなくて、こちらについてもしっかり住民同士で話し合っていただいて、地域の。","voiceIndex":46,"id":"exchange-020"},{"speaker":"安藤委員","kind":"意見","question":"そうですね、ちょっと木密地域の再生産というふうにならないようにという話もありますが、それはなかなか実際に実行するには本当にルールづくりとか、まちづくりは百年の計ということもよくおっしゃいますけれども、すごく大事な視点になってくるのかなと思いますので、これからそういった視点も大切にしていただいて、防災対策を考えていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":48,"id":"exchange-021"},{"speaker":"いながわ副委員長","kind":"質問","question":"今回、これが出たのは２月１５日のプレス発表でしたか。ということは、平成３０年度予算にはこれが出る前に予算が査定されて、冊子になっているわけですから、これが出たことによって、また品川区として、今までも十分やっていると思うのですよ。そもそも、この地域危険度測定調査自体が、以前からずっと申し上げているのですけれども、おそらく５年ぐらいずれているわけではないですか。","respondent":"高梨木密整備推進課長","answer":"第７回から第８回でも、先ほど申しましたとおり、しっかりと危険の量自体は減って改善が進んでいるといったことは、さらに強力に推し進めている近年の木密対策のことを考えれば、現時点でまたさらに進んでいるはずだといったところをしっかり自信を持って。","voiceIndex":49,"id":"exchange-022"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"それで出た数字というのは、もちろん東京都が出しているものなので、しっかりそれを一つの参考としながらも、やはり品川区の職員の皆さんは地域にお住まいである方も多いし、地域を回られているというのも私も実際目にしていますので、そういうところからしっかり品川区に何が必要なのかというのを施策として見出していただきたいなという思いがあって質問させていただきました。","respondent":"高梨木密整備推進課長","answer":"そういった意味では、この指標が出たからといって、すぐにこれに惑わされるといったこと、重要な資料ですので、参考にはしたいと思っているのですが、まずは地域に根ざしたまちづくりといったところを優先に、今後も今までと同様進めていきたいと考えております。","voiceIndex":51,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"大崎ですけれども、準備組合とか、あとそれ以前のまちづくり協議会とか、勉強会という形態もあると思うのですけれども、それぞれの段階では、区というのはどういうふうにかかわっているのでしょうか。具体的な支援内容というのがあれば伺いたいと思います。１点です。指定されると、どうなるのかというのをお伺いします。","respondent":"稲田都市開発課長","answer":"準備組合におきましては、大分話が進んでくるですので、まちづくりの方針、もちろん協議会の時点でも話はしているのですが、区の方針とか、そういうものを権利者、地区の皆様方にお話をしながらまちづくりを順次進めていくです。それから、大崎駅西口駅前地区です。","voiceIndex":57,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"それと、大崎駅西口Ｆ東地区のほうは、伺ったのは、指定されるとどうなるのですかねというか、どんないいことがあるのかというのがちょっとわからなかったので、具体的にマンション再生まちづくり制度というのは、どんな制度なのかというのをちょっと知りたかったのでお伺いします。","respondent":"稲田都市開発課長","answer":"具体的に言いますと、東京都は検討するためにマンション再生地区、これを検討するために、検討の費用、コンサルタント費用みたいなものを出しますよというのが目に見えた支援ですが、この大崎西口駅前地区は、既に準備組合で事業協力者等がおりまして。","voiceIndex":59,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"ちょっとＦ東地区のほうは、具体的には特に何か指定する意味がちょっとわからなかったのですけれども、特にいいことはないということなのでしょうか。ちょっとメリット的なものは何も感じられなかったのですが、何かないのですか、あるのですかというのを、もう一度お伺いします。それぞれの地区の、私はどんな計画が検討されているのかなというのをお伺いしたので、そちらもお聞かせいただければと思います。","respondent":"稲田都市開発課長","answer":"先ほどの東五反田二丁目第３地区ですが、こちらはイマジカがあるところです。まさにどういうふうな形でまちづくりをやっていくか、広場の配置、公園等の配置、それから道路の配置等々を考えながら、こちらのまちづくりを進めていこうということで今まさに検討しています。","voiceIndex":61,"id":"exchange-026"},{"speaker":"筒井委員","kind":"確認","question":"東五反田二丁目第３地区と、大崎駅東口第４地区についてなのですけれども、東五反田二丁目第３地区、今ご答弁があったように、イマジカとかが今ある場所ということなのですけれども、地図で確認しますと、やはりそうしたイマジカとか、あとまた大崎駅東口第４地区だと印刷業者とか、そうした企業が今いらっしゃるところが多いのですけれども、この再開発の背景としまして、そうした会社が土地を売って。","respondent":"稲田都市開発課長","answer":"都市再生緊急整備地域、こういう地区に指定されている、昨日来言っておりますが、副都心である等々ございまして、副都心にふさわしいまちづくり、複合市街地の形成というところにおきまして、まだ具体的にどのようにやるというところでは、その辺はまだ現在話し合いをしています。","voiceIndex":63,"id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"話し合いの段階だと思うのですけれども、基本的にはやはり今いる企業は抜けられるという形で考えてよろしいのでしょうか。","respondent":"稲田都市開発課長","answer":"最終的に出ていくのか、出ていかないのかという話ですけれども、現在のところ、そこにいる企業もこの協議会に入って一緒になって検討しているです。","voiceIndex":65,"id":"exchange-028"},{"speaker":"筒井委員","kind":"質問","question":"イメージ的には、その企業もありながら住宅も建てていく、西品川一丁目地区のような感じになるのかなということを私はイメージしたのですけれども、そのような理解でよろしいのでしょうか。","respondent":"稲田都市開発課長","answer":"その辺で、そういうふうな方向性だとか、そういうところはまだ今固まっていないというのですか、いろいろ話し合いはされていますけれども、この場ではなかなか言えないということです。","voiceIndex":67,"id":"exchange-029"},{"speaker":"西本委員","kind":"確認","question":"大崎駅のほうなのですが、３番、西品川一丁目地区の下のほうに書いてありますように１６３号線、先ほどトンネルを掘るというお話を聞きましたが、これは本当に大丈夫ですか。どこまでいっているのでしょうか。どこまで話が進んでいて、具体的にＪＲとの話がどこまで行って、信憑性がどこまであるものなのでしょうかというのが１点。それと、大崎駅です。要はチェック機能ですね。","respondent":"稲田都市開発課長","answer":"その辺、ＪＲとも今後も引き続き大崎駅の混雑について話をしていくところですが、ＪＲのほうもやはり大崎駅の乗降客数の多さについては認識しているところでございまして、トップのほうというのですか、上のほうの方たちもよく認識しているところでございまして。","voiceIndex":69,"id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"やはり、区は品川区民の代表にもなるわけですから、やはりそこはきつく言っていただかないと進んでいけないのではないかということをとても心配しております。そこの状況。それから平成３５年に完成するということですが、この５年間はどういう対応をとられるのですか。それを進めていくのがエリアマネジメントの仕事なのかなと思うのですが、その辺のこれからのあり方、進め方についていかがでしょうか。","respondent":"稲田都市開発課長","answer":"これはＪＲのほうも認識はあるですが、やはり抜本的な改良等も含め、それができるかどうかは別としまして、今後検討していかなければいけないと区のほうも考えておりまして、その辺の検討は早い段階でやっていこうかなと考えています。それから、５年間、開通までの対応はです。","voiceIndex":71,"id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"すみません、武蔵小山駅のほうを１点だけお聞きします。非常にビルをたくさんつくっているなと、知ってはいますけれども。ここができ上がったときに、人口がどれだけ増えてしまうのだろうかと、ここは武蔵小山駅もあるわけでありまして、交通の便とかを含めて、どのように人口が増えて、行政として対策を考えられているのかなと思うのですが、いかがですか。","respondent":"稲田都市開発課長","answer":"そういうところも踏まえながら、駅に関しましては東急電鉄もこういう再開発がありますよ、そういうふうな話を会議の中でも、連絡会議を開きながら進めていくということで考えております。","voiceIndex":73,"id":"exchange-032"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、そこは今後進めていく中でも危機管理も含めて監視していただいて、対応策をぜひとっていきつつ、開発を進めていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-033"},{"speaker":"大沢委員","kind":"質問","question":"大崎のほうで駅のキャパシティとかいろいろな話が出たのですけれども、あえて伺いたいのですけれども、二つ棟ができると大体５,０００名増えるというような試算が出ていますよね。これにプラスして新しく駅前のところにまず最初に、世帯数は別にして、人口が約２,５００名増える。そのまた隣の駅前のところで２,５００名。","respondent":"稲田都市開発課長","answer":"我々区のほうもそういう点は危惧しておりまして、先ほども言いましたが、東急電鉄、そちらのほうと今そういうところにつきましても今後対応策というのは具体的に検討していかなければいけないと考えております。","voiceIndex":76,"id":"exchange-034"},{"speaker":"大沢委員","kind":"質問・要望","question":"現状でもそうなので、そこらあたりを含みおきで、ご答弁は結構ですので、そういうような状況をよく加味しながら東急あるいは周辺の関係団体とお話を進めていただきたいと考えていますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-035"},{"speaker":"安藤委員","kind":"質問","question":"西品川一丁目の話もちょっと出たので、もともと竣工と同時に道路ができるはずが、５年も遅れているということで、生活道路、駅からの７,０００人の従業員とマンション住民が大崎駅を利用するということで、その影響で隣の町会が再開発組合と話し合いを続けていまして、そこで超党派の地元の議員も参加しているという状況があります。そこら辺はどう考えていらっしゃるのか、伺わせてください。","respondent":"稲田都市開発課長","answer":"車道の片側車線を１本抜きます。全部で２本のトンネルをこの下に通していくというところでございまして、歩道につきましては、十分計画量をこなせるというところでございまして、トンネルが抜けた暁には、スムーズな通行が可能になると考えております。","voiceIndex":79,"id":"exchange-036"},{"speaker":"安藤委員","kind":"質問・要望","question":"武蔵小山のほうもちょっと聞きますが、駅の北側ですが、街並み再生地区に入っているということで、水色の点線があるのですけれども、ここはどんな具体的な計画ができ、現段階になっているのか伺いたいと思います。網かけ、これは水色の網かけの中身ですね、このかかるということは、どんな規制の緩和ですとかがあるのか、具体的に中身を伺いたいと思います。","respondent":"稲田都市開発課長","answer":"そういう中におきまして、これはあくまでまちづくり方針をつくったところ、再生地区ですね、街並み再生方針をつくったところですので、実際これをまた地区整備計画、そういうのを立てていかないと、そういう具体的な条件にはまったものというのはできてきませんので。","voiceIndex":81,"id":"exchange-037"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと私が伺ったのは、具体的には整備計画をつくらなければいけないと思うのですけれども、この網がかかることで、どういうそういう地区計画ですとか整備計画ですとか、そういった緩和が可能になるのかというのをちょっと知りたかったので、そこはちょっともう一度お願いしたい。","respondent":"稲田都市開発課長","answer":"この街並み再生方針ですが、この再生方針は、その地区に合ったまちづくりができるというところでございまして、その中の街区再編まちづくり制度によりまして、細分化された敷地の統合や、細街路の付替えなどを行いながら。","voiceIndex":83,"id":"exchange-038"},{"speaker":"安藤委員","kind":"質問","question":"地権者の数はパルムが８９名で、駅前通りが５５名ということだったと今伺いましたけれども、そのうち組合加盟している人の数、それと転出した方というのはどれぐらいいたのかというのをちょっとお伺いしたので、お答えいただければと思います。それと、駅の北側ですけれども、具体的な今動きというのですかね、どこまで進んでいるのかというのもちょっと伺ったので教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-039"},{"speaker":"安藤委員","kind":"質問","question":"最後、すみません、この沿線ですね、随分と、１、２だけではなくて、やはり再開発の動きが広がっているなというふうに思うのですけれども、これだけ超高層が建っていく計画で、商店街のアーケードはどうなるのかなというのかすごく気になるのですけれども、どうなるのですか。アーケードはどうなってしまうのかな、残るのですかというのをちょっと伺いたいと思う。","respondent":"稲田都市開発課長","answer":"現在アーケードに接する部分で、武蔵小山パルム駅前地区が計画を立てて工事をやってあります。この部分、アーケードを存続させて商店街のにぎわいを保つためにパルム駅前地区のビルのほうも、そちらに向いた形での店舗展開とか、そういうところでやっていくという状況です。","voiceIndex":89,"id":"exchange-040"}]},{"id":"topic-03","title":"(5)の耐震改修促進法に基づく耐震診断結果の公表","agenda":"(5)の耐震改修促進法に基づく耐震診断結果の公表","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"診断結果の公表の目的について改めて教えてください。それが一つです。それと、既に平成２７年５月には特定緊急輸送道路沿道の建築物について発表があったということですが、何かそれについて問い合わせとか、反応みたいなものはあったのでしょうか。そういうのを区がつかんでいることがあれば聞かせてください。","respondent":"鈴木建築課長","answer":"反応についてですが、特段公表してもらっては困るという強い声はございません。それまでに、公表するまでには診断を促しながら法による、これは東京都の条例になりますが、公表のご説明もしてまいりまして、最終的には診断していただけずに公表したです。","voiceIndex":101,"id":"exchange-041"},{"speaker":"安藤委員","kind":"質問・要望","question":"それで、例えばここにも書いていますけれども、病院ですとかあるいは公共浴場というのも東日本大震災でも結構そういったところがやはり被災された後の被災者の方々にとっても非常に重要な役割を果たしたということもありましたし、こういう公共的に重要な施設の耐震化というのをやはり公はしっかり財政支援を含めて促進する具体策もとるべきなのではないかと思いますし、それを要望したいのですけれども。","respondent":"鈴木建築課長","answer":"特定緊急のほうですが、特定緊急のほうは、耐震化はこれからというところで、診断は高い、９５％の形で耐震診断はしていただいていますが、その後、設計補強に進んでいただくための、やはり公表して促進策として、本定例会でも提案していますが。","voiceIndex":103,"id":"exchange-042"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひそういったところにも何らかの形で、任せておくとなかなか進まないという現状もあると思いますので、ぜひそういったところにも目を配って支援していただけるような研究などを進めていただきたいなというふうに思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"これ以降、全く該当者の方たちは何もしていないという認識でよろしいのでしょうかということと、それで２番目の(2)の１６６棟が該当しているというところなのですが、当然ここには入っていないのが、逆に平成２７年のときはしていなかったけれども、その後にして、１６６棟の中に入っているものもあるのか、そこら辺の状況はどうなっているのでしょうか。","respondent":"鈴木建築課長","answer":"未診断の建物、平成２７年５月以降、働きかけは継続して行っておりまして、そのうちの１棟は公表後、診断をしていただいて、１６６棟のほうに入っているという状況です。１６６棟の中には、診断結果の公表ですので、診断をしていませんという方の公表は今回行いません。","voiceIndex":106,"id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"そうすると、本来(2)のところに１６６棟と書いてありますけれども、今は診断していないけれども、本来やらなければいけないというところはもっとあるという認識でよろしいのですか。その中の何％ぐらいがこの１６６棟になっていてという、そのちょっと規模を知りたいのですけど。","respondent":"鈴木建築課長","answer":"特定緊急輸送道路沿道建築物につきましては２０９棟ございまして、今回１６６棟なのですけれども、そのうち既に建物自体が除却されているものが２１棟、それから今回１万m2以上のものは東京都が公表しますので、東京都の扱いが１３棟。","voiceIndex":108,"id":"exchange-045"},{"speaker":"西本委員","kind":"質問","question":"協力をされている方も多い中で、やはりなかなか９棟につきましては難しいなというところなのですが、なかなか診断もしにくいという、何かこちらで金銭的な補助なのか、何かその要因がいろいろあって難しい部分があるのかなと思うのですけれども、現状何かきっかけがあれば何とか９棟の解決がつくというものなのか、全くそれは無理というものなのか、どういう感じなのですか。","respondent":"鈴木建築課長","answer":"大分この９棟の方々には直接的な働きかけも、本当にフェイス・ツー・フェイスのやりとりをしてきたのですけれども、やはり診断費用については、ほぼご負担なくやっていただけるような制度設計になっておりまして、診断費用が用意できないというよりも、お声としては。","voiceIndex":112,"id":"exchange-046"},{"speaker":"西本委員","kind":"質問・要望","question":"では最後に。なかなか事情がわからないではないのですが、決まりは決まりですから、やっていただきたいなと思っているのですが、結構２年ぐらいたつのですかね、それ以上交渉されているのだろうと思うのですけれども、できる限りというか、最終的にはどうなってしまうのかなと思うのです。","respondent":"鈴木建築課長","answer":"ただ、法整備の中では、マンションの建替え円滑化法等々、あるいは促進法自体も改定されて、所有権者の合意の件数の緩和ですとか、あるいはマンションの容積率の緩和ですとか、そういった法整備もされておりますので、そういったところを区としてしっかりご説明しながら。","voiceIndex":114,"id":"exchange-047"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"は資産の低下につながると言ったとしても、この１６６棟の方々は、そういうのも含めてやはりしっかり診断をしようとして診断をしているわけですから、この９棟のしない方というのは、やはり区としても、東京都がやるべきなのかもしれないですけれども、区としてもそこはしっかりと、重要事項の説明をしっかり載せるのもたぶん義務づけられると思うので、その辺はしっかりしていただきたいなという部分です。","respondent":"鈴木建築課長","answer":"今後は改修工事にいかに進んでいただくかというところでございまして、現在も特定緊急の改修と補強工事の助成制度はありますが、大分通常の補助よりも充実した内容で行っているのですが、診断が終わった次のステップですので、先ほどもちょっとご説明させていただいたとおり。","voiceIndex":116,"id":"exchange-048"}]},{"id":"topic-04","title":"大井水神公園改修工事","agenda":"大井水神公園改修工事","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"一つは、今回の改修範囲ということで、図で言うと左側のほうになっていますけれども、右側のほうとかというのは、これから予定があるのでしょうか、お伺いします。それと、今回の改修内容を定めるにあたって、住民の意見聴取の機会というのはどのように持たれたのでしょうか伺います。","respondent":"溝口公園課長","answer":"近隣の町会の方、または大井第一地区の町会長が集まった会議に出席して、工事の整備内容、時期、そういったものを説明しながら今日に至っているというものです。","voiceIndex":122,"id":"exchange-049"},{"speaker":"安藤委員","kind":"質問","question":"トイレなのですけれども、多目的トイレが設置されたのですけれども、何かほかのところとかで、つくった後に車いすの転回ができないということがわかったということもあったのですけれども、今回は大丈夫なのでしょうか。それと、天候によってはにおいの問題があったという話も聞くのですけれども、その辺はクリアされるということでよろしいのでしょうか、お伺いします。","respondent":"溝口公園課長","answer":"そういったところを配慮しながら整備を進めていきたいと考えていますし、一つ、においの件があります。これは改修してから、昭和６２年に公園改修、トイレ整備をしてからそのままずっと経年たってきたところで、やはりにおいの苦情が一つ入っておりました。","voiceIndex":124,"id":"exchange-050"},{"speaker":"安藤委員","kind":"質問","question":"駐輪場の件についてちょっと伺いたいのですけれども、地下式駐輪場と公園に再整備された駐輪場はそれぞれ何台分なのかお伺いします。今回の整備に合わせて大森駅前住宅の歩道の駐輪場が一つ課題になっていたと思うのですけれども、その一定縮小ですとか撤去というのをしてほしいのですけれども、そこら辺はいかがでしょうか。","respondent":"桑波田交通安全担当課長","answer":"大森駅前住宅のお話なのですけれども、やはり今後のマンション増加ですとか人口、こういったものの動向等を十分に見極めていかなければなりませんので、今回地上の分ができても、撤去するという考えは現在ございません。","voiceIndex":126,"id":"exchange-051"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっとそうですね、地下もできましたし、マンション動向という話もありますが、安全上ですとか近隣の方のお声とかもありますので、ちょっと動向を見極めながら、一気には無理かもしれませんけれども、大森駅前住宅のほうの駐輪場の段階的な縮小ですとかもぜひ検討していただければというふうに思っております。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":128,"id":"exchange-052"},{"speaker":"新妻委員","kind":"確認","question":"何点かお伺いしたいと思います。トイレですが、男性、女性ともに洋式トイレを設置していただくということで、この洋式トイレの中には、子どもが座るチャイルドシートというのですかね、そういうタイプ、それを設置していただけるのかどうかというところと、あと喫煙所がここの中に設けられるのかどうかというところですね。そこをちょっと確認したいと思います。","respondent":"溝口公園課長","answer":"トイレの件です。子ども用の便座ということで、普通の大人用の便座の上にかぶせてやるタイプ、またいろいろさまざまあるのですが、今の計画では特に男子、女子、多目的トイレとも子ども用のまでは設置は考えておりません。","voiceIndex":129,"id":"exchange-053"},{"speaker":"新妻委員","kind":"質問","question":"ベビーシートではなくて、各個室の中に子どもが、親が用を足しているときに、子どもをちょっと置く、座らせる椅子が、何ていうのですかね、それがつくのかどうかというところでした。それと、喫煙所の場所なのですけれども、この中で言うとどこにつくるのかを教えていただけますか。","respondent":"溝口公園課長","answer":"今のところ、このあたりを喫煙所にしようというふうに考えているものです。当然歩行者の動線、または公園利用者、そういったところも配慮しながら喫煙所というものは設置していきたいというふうに考えているところです。","voiceIndex":131,"id":"exchange-054"},{"speaker":"新妻委員","kind":"質問・要望","question":"ここは公園ですので、当然ながら子どもを連れてくるところもありますから、多目的は当然ながら、しかも男性のところも、あわせて洋式の中に設置をしていただきたいと要望させていただきたいと思いますが、いかがでしょうか。というところと、どういう形で受動喫煙が、公園の中なので基本はやはりなくても、本当はつくってほしくないなと思うのです。","respondent":"溝口公園課長","answer":"どうしてもベビーチェアを入れると、その分ブースを広げたり、建物を大きくしたりとかというところがありますので、これについては引き続きこのほかのところもありますので、トイレの機能としてどういう形で入れていくのか。","voiceIndex":133,"id":"exchange-055"},{"speaker":"新妻委員","kind":"質問・要望","question":"それと、喫煙所に関しては、何か場所が今回ここにということですけれども、こういう真ん中に必要なのかなとか、いろいろ思うところもあるのですけれども、そこも含めて今後の公園の中の、会派からも受動喫煙対策を要望していますけれども、特に子どもたちが来る公園の中においての喫煙所のあり方というのもまたしっかり今後もご検討を続けていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-056"},{"speaker":"西本委員","kind":"質問・要望","question":"だから公園の中のトイレの工夫というのは本当にしてほしいのですね。なので、やはり改修するときには、そういうものを必ず入れていただきたい。工事の状況によってはちょっとどうなのだろうか、お花見の時期とぶつかるような状況にはなっていないのかということを確認したいのです。それと、植栽の中に、「四季を感じられる」と、四季を感じられる草木というのは何でしょうかということですね。","respondent":"溝口公園課長","answer":"トイレの件です。さまざまな利用者の方、またさまざまなご意見をいただいているところです。そういったものをしっかり受けとめて、今後も引き続き皆さんがご利用しやすいトイレを検討していきたいというふうに考えているものです。","voiceIndex":136,"id":"exchange-057"},{"speaker":"西本委員","kind":"質問・要望","question":"桜の老朽化はチェックをしているのでしょうかということと、わかりました、四季、ここは本当にいろいろな花であったりとか木々がたくさんあって、とても癒しの場になっているなというふうに思っているので、さらにそれを深めていただければなというふうに思っております。では、ちょっと先に意見だけ、要望です。最後に桜の老朽化のチェックを。","respondent":"溝口公園課長","answer":"そういった中で、やはり２本ほど樹勢の弱くなっているものがありますので、そういったものも含めて今回新たに桜を植えていく計画にしておりますので、樹勢についてもしっかり調べながら、またそういったものについては植え替えながら。","voiceIndex":138,"id":"exchange-058"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、遊具エリアについてです。滑り台とかスイング遊具というのがありますけれども、ここの下の地面は、お子さんがもし転んでも安全なように、東品川公園のようにクッション性の高い素材とかを使われているのでしょうか、ちょっとその確認だけしたいので、お願いします。","respondent":"溝口公園課長","answer":"２種類のものを使おうと考えています。一つは、弾力性のある舗装材にする、あとは滑り台の周りについては、子どもたちが走っても遊べるように人工芝を張ることによって、より子どもたちが元気に遊んでもけがをしにくい、そういったところの工夫する予定です。","voiceIndex":140,"id":"exchange-059"},{"speaker":"いながわ副委員長","kind":"確認","question":"一番最初に質問がたぶんあったと思うのですが、確認なのですけれども、ほかにあと二つあるのでそこはやる、今後もやる予定とおっしゃっていましたか。そこをまず最初に確認させてください。","respondent":"溝口公園課長","answer":"今のところ、すぐに公園改修に入る予定はないのですが、やはり今後いろいろ遊具が古くなってきたり、また野球の運動ゾーンのところの防球ネットが傷んできたり、そういったところもありますので。","voiceIndex":142,"id":"exchange-060"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"桜がだーっと咲いてという、それは専門的にはどういう感覚でいらっしゃるかは別なのですけれども、ぜひここの改修なんかは随分立派なきれいな公園ができるということで期待するところなのですが、その横もしっかり、順次ということだったのですけれども、前向きにしっかりご検討いただきたいなということと、トイレの位置なのですけれども、ここだけ、今回やる、改修範囲だけ言っていてもあれなので。","respondent":"溝口公園課長","answer":"喫煙所につきましては、喫煙者または非喫煙者、受動喫煙の防止という観点もありますので、そういったところも十分に配慮しながら設置をしていきたいと考えています。最後に、工事の着手時期です。","voiceIndex":144,"id":"exchange-061"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"工事の始まる前にたぶん立て看板は立てられると思いますので、しっかり周知をして、何か楽しみに来たけれども、工事が始まっていたということがないように、告知というか、周知はしっかりしていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":146,"id":"exchange-062"}]},{"id":"topic-05","title":"目黒川安全航行啓発イベントの実施","agenda":"目黒川安全航行啓発イベントの実施","exchanges":[{"speaker":"新妻委員","kind":"質問","question":"これは目黒川でのイベントということなのですが、目黒川だけではなく、運河のほうでもこういうことが、幅が全然違いますけれども、そういうふうなことが見受けられることもあるのですが、運河のほうの対策というのは今後どうされていくのかということをちょっとお考えがあれば教えていただけますでしょうか。","respondent":"持田河川下水道課長","answer":"運河につきましては、現段階では、具体的にどうやっていこうという話はちょっとないような状態ですが、今後ももしこういったような暴走行為とかがあって、やはり地域の舟運を営む事業者の方ですとか、そういった方から声が上がるというようなことがあれば。","voiceIndex":151,"id":"exchange-063"},{"speaker":"安藤委員","kind":"質問","question":"一つは周知をやはりやっていかないとなかなか実効性がないのかなと思うのですけれども、周知の点で力を入れているところはどういうところでしょうかというのが一つ。それと、そもそも事前申請がなくても、目黒川というのはこういう普通に誰でも航行できるものなのかという、そのそもそも論のところですかね、ちょっと聞かせていただければと思います。","respondent":"持田河川下水道課長","answer":"２点目の、基本的には川は通行していいのですよねというお話ですが、おっしゃるとおりでございまして、基本的には川でも運河でも自由に通行していいわけですので、今私が言いましたように当日イベントを知らずに事前届出のない船が来た場合については、しっかり説明をして。","voiceIndex":154,"id":"exchange-064"},{"speaker":"西本委員","kind":"質問","question":"平成２８年度にいろいろ課題があってということで、次の年からこういう活動になって、かなり成果がありましたという報告を受けていると思うのですね。実際、今年も同じような形で啓発活動をしていくのだろうと思うのですが、この申請をされた方というのは実際どのぐらいいたのでしょうか。それと、２日間以外のときは自由に運航できるということなのでしょうか。","respondent":"持田河川下水道課長","answer":"昨年、同様のイベントを実施いたしまして、昨年はこの旗とステッカー、あわせて１７６枚お配りいたしておりますので、それぐらいの規模の船ですとかカヌーですとかが来る可能性があったという形かと思います。","voiceIndex":156,"id":"exchange-065"},{"speaker":"西本委員","kind":"質問","question":"昨年もたしか２日間ぐらいだったと思うのですけれども、それ以外の日に何か問題があったとかといことはありましたでしょうか。","respondent":"持田河川下水道課長","answer":"昨年に関しましては、この２日間のイベント以外でも、桜の時期に関しては、特に暴走行為等はなかったということで、地元の方ですとか舟運の事業者からも、そういったお声は上がっていないです。","voiceIndex":158,"id":"exchange-066"},{"speaker":"西本委員","kind":"意見","question":"かなり効果が上がっているなというふうに思っているのですけれども、たぶんこの日以外は大丈夫だというような情報が行かないとは限らないので、何かそういう問題が起きたらすぐ対応できるようにお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":160,"id":"exchange-067"},{"speaker":"筒井委員","kind":"質問","question":"検証方法というのはどうされているのかをお聞きしたいと思います。","respondent":"持田河川下水道課長、松代防災まちづくり部長","answer":"目黒川に関しましては、桜の時期に非常に船が目立って多いということもありまして、そういったところで暴走行為がありますと、桜を観覧していただく船が必要以上に揺れるとか。監視カメラを数台つけまして、そういった実態があれば、その実態の報告を警視庁に上げて、さらに警視庁のほうでも対応方、先に進めてもらうようにしていく、そんなことを今ずっと続けております。","voiceIndex":161,"id":"exchange-068"},{"speaker":"筒井委員","kind":"質問・要望","question":"ちょっと幾つか確認したいのですけれども、ちなみに昨年度はこうした啓発イベントを知らずに水上バイクや大型船舶の方の暴走行為というのはあったのでしょうかということと、やはり水上オートバイがかなり悪いイメージになっていますけれども、とはいっても、水辺に親しむための重要な乗り物だと私は考えておりまして、そうした方を規制とかで強く抑えるのではなくて。","respondent":"持田河川下水道課長","answer":"そういった形で、水上バイクの団体のほうとも、そういった運航のマナーについては協力しながら、向上を目指していくです。","voiceIndex":164,"id":"exchange-069"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"こういった場合というのは、なかなか啓発しようにも、昨年は１７６枚出たとか、１７６艇出たというイメージなのか、ちょっとその辺は別にしても、なかなか周知しきれない部分があるとなると、当然河川とか船舶免許を所有している方はルールにのっとってということをたぶん教習というか試験でやるわけであって、当然彼らはしっかり安全確認をしなければいけない部分だと私は思っているのです。","respondent":"持田河川下水道課長","answer":"それは今後桟橋等の整備を本格化したときに、サインについても合わせて考えていきたいというふうに思っているところです。","voiceIndex":166,"id":"exchange-070"},{"speaker":"いながわ副委員長","kind":"意見","question":"これは改めて知る必要性もあるし、非動力の船の横を水上バイクがそこだけフル加速したら、たぶんひっくり返ると思うので、そういったルール、例えばカヌーは上流に向かってどっち側を航行してくださいよとか、何かそういったやはりルールというのは、ここまでやるということは限られた範囲なので必要だと思うので、そういったルールブックみたいなのは同封して送られているのか。","respondent":"持田河川下水道課長","answer":"ルールブックというほどではないのですが、ルールを明記した、この今日の委員会資料につけましたチラシとは別のルールを明記したビラをつくってございまして、申請に来た事業者ですとか団体の方には旗といっしょにルールのビラをお渡ししている、そんな対応をしています。","voiceIndex":168,"id":"exchange-071"},{"speaker":"大沢委員","kind":"質問・要望","question":"先ほどジェットスキーというような目黒川で無謀な通行をする者に対してカメラというような話をいただいたのですけれども、先ほど来課長たちの話を伺っていて、道路では道路交通法という法律があって、河川においては、通行に関する決まりが明確でなくて自由であるという話がありました。","respondent":"松代防災まちづくり部長","answer":"その実態をきちっと警視庁としても把握をする中で、規制といいますか、何らかの形の手だてを考えていきたいと、このような話がありまして、私どもも実態を目視では何回か見ているのですが、それを記録にはなかなかまだとどめておりませんでしたので。","voiceIndex":170,"id":"exchange-072"},{"speaker":"大沢委員","kind":"質問","question":"非常に大事なことで、管理というか河川の秩序というか、それを守る有効な手段、方法ではあると思うのですけれども、カメラを設置する、ちょっと伺いたかったのは、道路の場合は道路交通法という法規があると。","respondent":"松代防災まちづくり部長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":172,"id":"exchange-073"}]},{"id":"topic-06","title":"第３４回品川区防災フェア","agenda":"第３４回品川区防災フェア","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"今回の防災フェアにおきまして、今回私も一般質問のほうでさせていただきましたが、男女共同参画の視点がどこに反映をされるのかということで、既に男女共同参画センターがわが家の防災ハンドブックのサイドリーダーのパネルを作成をして、男女共同参画センターのほうで展示をしていますが、それをこの防災フェアでぜひ活用していただきたいなと思うのですけれども、それが１点と、もしくは何か男女共同参画。","respondent":"古巻防災課長","answer":"男女共同参画の視点でということでは直接ないのですけれども、やはり先ほども申し上げたとおり、お子さんを含めました若い世代の方々により多く参加していただけるようにということで、そういった方面への周知を十分にやっていくような形で今準備を進めております。","voiceIndex":179,"id":"exchange-074"}]},{"id":"topic-07","title":"の最後に、(9)品川区地域防災計画の素案の修正","agenda":"の最後に、(9)品川区地域防災計画の素案の修正","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"ちょっと細かい、文言とかではないのですが、パブリックコメントを１カ月やっていたのですが、やはりこういう防災というのはかなり関心が高い分野だと思うのですけれども、やはり意見的には低調だったのかなと思うような件数だと思います。それと、やはりちょっと低調だったかなと思うのですけれども、何が原因なのかなと区としては考えていらっしゃるかお伺いしたいと思います。","respondent":"古巻防災課長","answer":"そういった意味で、今回低調ではありましたけれども、貴重なご意見もいただいていますし、それについては十分反映をしていきたいと思いますし、また地域防災計画をつくっておしまいということではありませんので、実際具体的な避難所のマニュアルをつくるとか。","voiceIndex":186,"id":"exchange-075"},{"speaker":"安藤委員","kind":"提案","question":"ちょっとやはり関心が高い分野だと思うのですけれども、低調だったというのはなぜなのかなというのをちょっとお伺いしたので、区としてはどうしてなのだろうという意見を、理由についてどのようにお考えなのかというのをお聞かせいただきたいのと、それと私としてはやはり内容が伝われば、意見を言いたくなると思うのですけれども、やはりなかなか防災計画そのものについての説明がないといいますか。","respondent":"曽田災害対策担当部長","answer":"今回低調だったというのは確かにそうだと思います。ただ、５年前に地域防災計画を改正するときに同じような方法でパブリックコメントを実施しました。その際には、このようなペーパーが１０枚以上来てきます。やり方は一緒です。","voiceIndex":188,"id":"exchange-076"},{"speaker":"安藤委員","kind":"質問","question":"私は、なぜそうなってしまったのかというお考えはわかりましたけれども、そうですね、だからこそやはりいろいろな方々に意識をもう一回掘り起こしていただくことも大事かなと思いますので、私はむしろそういうのであれば、なおさらそういう説明会というのを合わせてやって、ある意味計画を知らせること自体が、説明すること自体がやはり啓発にもつながってくるし。","respondent":"古巻防災課長","answer":"方針としましては、今災害対策担当部長から答弁申し上げたとおりですけれども、啓発につきましては、ご指摘いただいた点を含めまして、今後きちんと、当然これは防災課の使命でありますので、進めていくです。","voiceIndex":190,"id":"exchange-077"},{"speaker":"西本委員","kind":"確認","question":"それに関して何か反映することがあるのかというのが一つと、それからあと、たしか中央公園にヘリポートができましたので、広域の協力体制の中に、それを近隣の自治体との関係の中で、そういうのも具体的なところが入っているのだろうかということをちょっと確認したいのですね。それから、支援物資の受援体制なのですけれども、情報発信はどうされるのでしょうか。","respondent":"古巻防災課長","answer":"ただ、中身について、特に変更があった、考え方を変えたというよりは、今まで少し誤解が生じていた部分について、はっきりと環境省のほうで同行避難というのは必ずしも室内に一緒にいられる避難ではありませんよということを打ち出したというか。","voiceIndex":192,"id":"exchange-078"},{"speaker":"西本委員","kind":"意見","question":"区民の皆様はこれを見ても絶対見ないと思うのですね。私らも見るのが結構大変なので、わかりやすいものができるといいなというふうに思うのですけれども、そういう考えなどはありますか。","respondent":"古巻防災課長、曽田災害対策担当部長","answer":"具体化につきましては、まさに委員おっしゃるとおりで、地域防災計画だけでは具体的な動きとかがなかなか見えにくい部分がありますので、そういったところをマニュアルに落とすですとか。支援に関する情報発信ですけれども、先ほど配りました資料３の震５－１９の下のほう、オ、支援ニーズに書いてありますけれども。","voiceIndex":194,"id":"exchange-079"},{"speaker":"筒井委員","kind":"確認","question":"ちょっと確認になってしまうのですけれども、私はちょっと十分読み込んでいない点もあるかもしれませんけれども、昨年１０月にたしかボランタリー・アーキテクツ・ネットワークと避難所の協定を結ばれたかと思うのですけれども、紙管パイプを利用した避難所とかをやられていると思うのですけれども、その点についての記載というのはあるのですか。","respondent":"古巻防災課長","answer":"具体的に協定の中身ですとか、そういったところの記載はございませんが、避難所におけるプライバシーの確保ですとか、そういったことについてもう少し一般的な書き方では記載しています。","voiceIndex":197,"id":"exchange-080"},{"speaker":"筒井委員","kind":"質問","question":"一般的な書き方、抽象的な書き方でその中で包括して書いていくと。実際に具体的にどういうことをやるのかというのは、そのときに実際に対応していくという理解でよろしいのでしょうか。","respondent":"古巻防災課長","answer":"プライバシーの確保といいましても、間仕切りだけではなくて、さまざまなプライバシーの考え方とか、やり方があると思いますので、そういったところもさまざま組み合わせて対応していくことになろうかなというふうに思います。","voiceIndex":199,"id":"exchange-081"}]},{"id":"topic-08","title":"の議会閉会中継続審査調査事項","agenda":"の議会閉会中継続審査調査事項","exchanges":[{"speaker":"横山委員","kind":"確認","question":"ちょっと簡単な確認なのですけれども、こちらの訓練によって、防災行政無線の聞こえ方ですとか、そういった伝わり方というのは基本的にどのように確認を行っていらっしゃるのでしょうか。","respondent":"冨澤防災安全担当課長","answer":"区民への伝わり方ですが、昨年１１月１４日に実施しておりますけれども、そのときに電話で防災課のほうにご連絡が数件ございました。その内容につきましては聞きづらい等々の内容がほとんどでございました。","voiceIndex":208,"id":"exchange-082"},{"speaker":"新妻委員","kind":"確認","question":"これはお願いなのですけれども、先ほどこの周知をホームページ、広報しながわということでしたが、全てのＳＮＳ、ツイッター、フェイスブック、インスタでもされるのかどうか確認をしたいと思います。","respondent":"冨澤防災安全担当課長","answer":"ツイッター等につきましては、当日周知をする予定です。しなメール、ツイッター、フェイスブックにつきましては当日配信の予定です。あわせまして、当日区のパトロールカーによりまして、巡回広報を実施する予定です。","voiceIndex":210,"id":"exchange-083"},{"speaker":"筒井委員","kind":"質問","question":"先ほどご答弁で前回は聞きにくいというお問い合わせがあったということなのですけれども、それを受けて、区としては今回何か改善というか、そうしたことを行った上で実施するのでしょうか。","respondent":"冨澤防災安全担当課長","answer":"昨年聞きづらいという内容につきましては、ご家庭の窓を閉めていたので何が鳴っているのかわからなかったという内容でございました。","voiceIndex":212,"id":"exchange-084"},{"speaker":"筒井委員","kind":"質問","question":"第一に伝達というか、そういったことはどうお考えなのでしょうか。事前の周知とかで、伝えて窓をあけてもらうとか、そういったことになるのでしょうか。","respondent":"冨澤防災安全担当課長","answer":"周知につきましては、やはり窓を閉めている方もいらっしゃると思うのですけれども、いろいろな広報媒体を使いまして、この時期、この時間帯にＪアラートによる訓練が行われますという形で周知をしたいと考えています。","voiceIndex":214,"id":"exchange-085"},{"speaker":"新妻委員","kind":"確認","question":"東京都が１００万部発行するというふうに聞いておりますが、品川区に何冊来るのか確認をさせてください。","respondent":"古巻防災課長","answer":"ただ、ほかの消防署等での配布数につきましては、消防署は全体で７００部というふうに聞いているのですけれども、そのほかの箇所については、ちょっと東京都の公表がございませんので、区内で全部で何冊かというのはちょっと手元に資料がない状態です。","voiceIndex":222,"id":"exchange-086"},{"speaker":"新妻委員","kind":"質問・要望","question":"今パブリックコメントの件数が地域防災のほうは非常に少なかったということでした。品川区も女性目線であったり、多様性をしっかりと今回地域防災の中にも入れているということで、例えば品川区でも女性の目線での防災ブックの作成、これを東京都でもつくりましたので、品川区版の、品川ナイズしたこういう防災ブックの作成ということもぜひ要望したいと思いますが、いかがでしょうか。","respondent":"古巻防災課長","answer":"防災フェアにおきます配布部数ですけれども、現時点では１,５００部を予定しております。それから、パネルとあわせての展示というか設置ですけれども、こちらもあわせて検討させていただければというふうに思います。","voiceIndex":224,"id":"exchange-087"},{"speaker":"新妻委員","kind":"質問・要望","question":"品川区版の女性目線というハンドブックにおいては、わが家の防災ハンドブックのサイドリーダーが既に一つありますので、それも参考にしながら、そこにプラスアルファ網羅していただいて、何かそういうちょっと特化したものがあったらいいのかなとも思いますので、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":226,"id":"exchange-088"},{"speaker":"西本委員","kind":"質問","question":"先ほど６,３００部となっているのですけれども、足りなくないですか。たぶん町会にわたるというと、町会は２００町会あるわけですから、そこに５冊ずつ行っても１,０００冊ですよね。桁が違うのですけれども、１桁多くするぐらいの品川区の規模を考えたら、何で６,３００冊なのですかと。配って何ぼの世界なので、余りけちらないでほしいのですけれども、その６,３００冊はもっと多くなりませんか。","respondent":"古巻防災課長","answer":"足りなくなれば当然追加をということで、東京都で足りなくなって、本当に足りなくなったら増刷をということで考えると思いますので、そういった中で十分に対応していきたいと思います。","voiceIndex":227,"id":"exchange-089"},{"speaker":"西本委員","kind":"質問・要望","question":"大体品川区だと、あっ、こことここに置いたらいいなと、すぐぱっと開いて、せいぜい、やはり万単位でしょうね、必要なのは。なので、すぐはけると思います。品川区でがっぽりともらっていただいて、有効活用どんどんしたほうが私はいいと思いますので、既に足りなくなるという形で、東京都のほうには要望をぜひしていただきたいと思いますが、いかがでしょうか。","respondent":"古巻防災課長","answer":"ご指摘いただいたとおりです。確かに体裁も手にとりやすい形になっていますので、いろいろ反響がまた出てくると思います。早目に手配をかけていきたいというふうに思っております。","voiceIndex":229,"id":"exchange-090"},{"speaker":"いながわ副委員長","kind":"質問","question":"それとも、品川区に言ったら何か、とりあえず、だからこれを置ければいいわけですよね。そういうのを、品川区で例えば女性が集まる会とか、女性を中心としたセミナーとかを品川区の団体などがよくやられているのですけれども、そういう場所で必要だといったときは、課長のところに行って、すみません、何冊欲しいのですけれどもと言ったら、くれるのですか、どうですか。","respondent":"古巻防災課長","answer":"部数にもよりますけれども、防災課では一定数は確保しているので、おっしゃっていただけば、出せる分についてはお出しできますけれども、基本的に例えば事業所でお客さん向けに置きたいのだということであれば、それは東京都のほうに直接ご請求いただければ。","voiceIndex":231,"id":"exchange-091"},{"speaker":"いながわ副委員長","kind":"質問","question":"だから、逆にこの窓口は本当に東京都に言わなければいけないのか、たぶん東京都に言うと、何か申請書を出してくださいと言って、冊子が来るまでにやはりタイムラグがすごくあると思うのですけれども、品川区だったら何か地域を議員が回っていて、実を言うとこういうイベントがあるから欲しいのだけれどもとか、地域のお店がこういうのを置きたいのだけれどもというのを課長に言えばすぐもらえて。","respondent":"古巻防災課長","answer":"決して消極的なつもりはないのですけれども、おっしゃっていただければ当然きちんと手持ちの分についてはお出しできるような体制はとっていきたいと思います。","voiceIndex":233,"id":"exchange-092"},{"speaker":"新妻委員","kind":"質問・要望","question":"これは東京都のホームページでは、公表されているのですけれども、品川区のホームページでもぜひこういうのができましたということと、品川区ではこういうところに置いてありますというところまで、区有施設ならびに店舗、例えば全部掌握し切れなくても、また例えば東京都のホームページにリンクしてでもいいのですけれども。","respondent":"古巻防災課長","answer":"区ホームページの掲載についても、少しどういった形がいいかどうかを含めまして考えます。","voiceIndex":235,"id":"exchange-093"},{"speaker":"新妻委員","kind":"質問・要望","question":"例えば、周知することで数が足りなくなってしまうというご心配があるのであれば、それはその上でしっかりとまた追加も区として要望していただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":237,"id":"exchange-094"},{"speaker":"横山委員","kind":"質問","question":"こちらは都の冊子ということなのですけれども、設置場所というところで、今３番でいただいているのですが、配布の対象者というのはどういった方を想定してつくられているのか、もし把握していらっしゃいましたら教えてください。","respondent":"古巻防災課長","answer":"要は、広報東京都と配布形態が同じような形でということで、当初、区の広報のほうへ照会があったですので、幅広く手にとっていただけるというようなことを目的につくって、そういった形で配布をしているというふうに認識しております。","voiceIndex":238,"id":"exchange-095"},{"speaker":"横山委員","kind":"質問・要望","question":"私は本日いただいたので、きちんと内容を細かく見ているわけではないのですけれども、女性の視点ということで、女性本人がいろいろ備えたりする部分に大変役に立つのかなと思いましたのと、あとは男性の例えばリーダー的立場の方ですとか、お子さんがいらっしゃったり、奥様がいらっしゃったりというような、そういう方が。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":240,"id":"exchange-096"},{"speaker":"安藤委員","kind":"質問・要望","question":"すみません、１点だけ。質問は１点だけなのですけれども、所管としては今回のように公園で遊んでいるお子さんですとか親御さんとかなどから、具体的な遊具についてのご意見を受けた際というのは、どのように処理を行って、それをどう反映させているのか、その具体的なプロセスといいますか、仕組みといいますか、考え方をお伺いしたいです。","respondent":"溝口公園課長","answer":"そういったところにやはり冒険、挑戦、そういったものをすることによって情操教育というか、心身ともに能力を高めていく、そういった反面もありますので、そういったところの兼ね合いも見ながら考えていくというのはありますので。","voiceIndex":242,"id":"exchange-097"},{"speaker":"安藤委員","kind":"意見","question":"ちょっと１点だけ。すみません。ちょっともう少し、いただいた意見というのは、蓄積、情報共有というふうにありますけれども、どういう感じで具体的には積み上げているといいますか、どういう形で共有しているのか、もう少し具体的に知りたいなと思うのですけれども、もしあれば。","respondent":"松代防災まちづくり部長","answer":"今後もしっかりとそういった面では安全性の向上に取り組んでまいりたいと、このように考えているところです。","voiceIndex":245,"id":"exchange-098"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4226#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":85333,"voices":248}}]);
